/* ============================================================
   Italia Cycling Stats — app.js  v203
   Hash Router + Page Renderers
   Legge i JSON statici da data/ via fetch()
   ============================================================ */

'use strict';

// ── CONSTANTS ─────────────────────────────────────────────────
const BASEPTS = { 1:15, 2:12, 3:10, 4:8, 5:6, 6:5, 7:4, 8:3, 9:2, 10:1 };
const RENDER_BASE      = 'https://italiacrit.onrender.com';
const SUPABASE_STORAGE = 'https://aqqsstsbgpapzoxllosh.supabase.co/storage/v1/object/public';
const IS_LOCAL         = location.hostname === 'localhost' || location.hostname === '127.0.0.1';
const API_BASE         = IS_LOCAL ? '/api' : `${RENDER_BASE}/api`;
const PHOTOS_BASE      = IS_LOCAL ? '' : SUPABASE_STORAGE;
const MEDIA_BASE       = IS_LOCAL ? '' : SUPABASE_STORAGE;

// Normalizza il path di una foto salvata in entity_overrides: gli script di
// scraping più vecchi (prima di oggi) salvavano path "corti" tipo
// "/pcs/slug.jpeg", senza il prefisso "/photos/" del bucket Supabase — senza
// normalizzazione l'URL finale punta a un file inesistente (404, foto non
// mostrata). Il formato attuale include già il prefisso corretto
// ("/photos/atletas/pcs/slug.jpeg"), quindi passa invariato.
function mediaUrl(photoUrl) {
  if (!photoUrl) return '';
  if (/^https?:\/\//.test(photoUrl)) return photoUrl;
  const path = photoUrl.startsWith('/photos/') ? photoUrl : `/photos${photoUrl.startsWith('/') ? '' : '/'}${photoUrl}`;
  return MEDIA_BASE + path;
}

// ciclismo.info è solo HTTP → su HTTPS il browser blocca le immagini (mixed content).
// xpix.it invece è HTTPS ma il suo storage (xpix.fsn1.your-objectstorage.com)
// non manda NESSUN header CORS — fetch(mode:'cors') fallisce sempre, non è un
// problema di rete lenta (confermato: manca del tutto Access-Control-Allow-
// Origin nella risposta). Entrambe passano dal proxy del server, che le
// riserva dal nostro stesso dominio (CORS sotto il nostro controllo).
function icProxy(url) {
  if (!url) return url;
  if (/ciclismo\.info\//i.test(url)) return `${API_BASE}/ic-image?url=${encodeURIComponent(url)}`;
  if (/xpix\.fsn1\.your-objectstorage\.com\//i.test(url)) return `${API_BASE}/xpix-image?url=${encodeURIComponent(url)}`;
  return url;
}

// ── YOUTUBE HELPER ────────────────────────────────────────────
// Estrae l'ID video da qualsiasi formato URL YouTube:
//   https://www.youtube.com/watch?v=ID
//   https://youtu.be/ID
//   https://youtube.com/shorts/ID
//   https://youtube.com/embed/ID
function ytId(url) {
  if (!url) return null;
  // Il primo pattern (?v=/&v=) da solo non è specifico di YouTube — un link
  // Facebook come facebook.com/watch/?v=ID contiene anch'esso "?v=" e veniva
  // scambiato per un ID YouTube (miniatura sbagliata, click che apriva il
  // player sbagliato). Deve esserci comunque youtube.com/youtu.be nell'URL.
  if (!/(?:youtube\.com|youtu\.be)/i.test(url)) return null;
  const m = url.match(/[?&]v=([^&\s]+)/)
    || url.match(/youtu\.be\/([^?&\s]+)/)
    || url.match(/youtube\.com\/(?:shorts|embed|live)\/([^?&\s]+)/);
  return m ? m[1] : null;
}

// Riconosce un link a un video Facebook (pagina/watch/reel/fb.watch) —
// non ha un id embeddabile come YouTube, ma FB offre un iframe pubblico
// (Video Plugin) che funziona per qualunque video pubblico senza bisogno
// di API key o app registrata.
function isFacebookVideoUrl(url) {
  return !!url && /^https?:\/\/(www\.|m\.|web\.)?(facebook\.com|fb\.watch)\//i.test(url);
}

// Normalizzazione nome canale/piattaforma per confronto per parole intere
// (NON substring: "ciclismo" non deve combaciare dentro "extraciclismo") —
// stesso criterio già usato per il dedup dei profili media (_normPlatformName
// altrove nel file, duplicato qui perché serve PRIMA nel file).
function _normChannelName(s) {
  return String(s || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[^A-Z0-9]+/g, ' ').trim();
}
// Cache di tutti i profili media attivi (foto+video), usata per raggruppare
// i canali/testate dei video legacy (es. "ToscanaSprint", "Toscana Sprint",
// "ciclismoweb / ExtraCiclismo") sotto UNA sola pagina profilo già esistente,
// invece di un cerchietto separato per ogni variante di scrittura del nome.
let _allMediaProfilesCache = null;
async function _ensureAllMediaProfiles() {
  if (_allMediaProfilesCache) return _allMediaProfilesCache;
  try { _allMediaProfilesCache = (await fetch(`${API_BASE}/media/profiles`).then(r => r.json())).profiles || []; }
  catch { _allMediaProfilesCache = []; }
  return _allMediaProfilesCache;
}
function _matchChannelToProfile(channelName, profiles) {
  const norm = _normChannelName(channelName);
  const chCompact = norm.replace(/ /g, '');
  const chWords = new Set(norm.split(' ').filter(w => w.length > 3));
  if (!chCompact) return null;
  for (const p of profiles) {
    const pNorm = _normChannelName(p.display_name);
    const pCompact = pNorm.replace(/ /g, '');
    const pWords = new Set(pNorm.split(' ').filter(w => w.length > 3));
    // Nomi compattati (senza spazi) uguali o uno contenuto nell'altro —
    // stesso brand scritto con/senza spazio ("BetaCycling"/"Beta Cycling")
    // o con un suffisso ("ciclismoweb" dentro "ciclismoweb / ExtraCiclismo").
    // Richiede almeno 6 caratteri per evitare corrispondenze accidentali su
    // nomi molto corti.
    if (chCompact.length >= 6 && pCompact.length >= 6 && (chCompact === pCompact || chCompact.includes(pCompact) || pCompact.includes(chCompact))) return p;
    // TUTTE le parole significative del nome più corto devono comparire
    // nell'altro — una sola parola in comune NON basta: "Giro d'Italia"
    // finiva abbinato a "Eurosport Italia"/"GCN Italia" solo per la parola
    // "Italia" (falso positivo confermato in produzione). Richiede anche
    // ALMENO 2 parole significative su entrambi i lati: un profilo che si
    // riduce a una sola parola lunga (es. "GCN Italia" → solo "ITALIA", "GCN"
    // troppo corto) farebbe altrimenti match con QUALSIASI canale contenente
    // quella singola parola.
    if (chWords.size >= 2 && pWords.size >= 2) {
      const [small, big] = chWords.size <= pWords.size ? [chWords, pWords] : [pWords, chWords];
      if ([...small].every(w => big.has(w))) return p;
    }
  }
  return null;
}

// Il player pubblico di Facebook (plugins/video.php) NON incorpora un link
// di una diretta ancora sotto /watch/live/?v=ID — mostra "Video non
// disponibile" (verificato dal vivo) — ma lo stesso identico video sotto
// /watch/?v=ID sì. Normalizzazione difensiva lato client per i video già
// salvati con l'URL "sbagliato" prima di questo fix (il server ora salva
// già la forma corretta per i nuovi inserimenti, vedi canonical_url).
function fbEmbedUrl(url) {
  return (url || '').replace(/\/watch\/live\/(\?|$)/i, '/watch/$1');
}

// Tipo di video: 'yt' (YouTube embed), 'fb' (Facebook embed), 'file' (file
// caricato → <video>), 'link' (altro → apri in nuova scheda).
function videoKind(url) {
  if (!url) return 'link';
  if (ytId(url)) return 'yt';
  if (isFacebookVideoUrl(url)) return 'fb';
  if (/(\.(mp4|mov|m4v|webm|ogg|qt))(\?|$)/i.test(url) || /\/storage\/v1\/object\/[^\s]*videos\//i.test(url)) return 'file';
  return 'link';
}
function isPlayableVideo(url) { const k = videoKind(url); return k === 'yt' || k === 'file' || k === 'fb'; }

// Miniatura per una card video Facebook: niente immagine statica salvabile
// (l'URL di copertina di FB è su una CDN con token che scade — non
// affidabile da conservare), quindi si incorpora lo stesso player pubblico
// usato nel modale, ma SENZA autoplay e con pointer-events:none — il
// player mostra da solo copertina reale + nome/logo della pagina FB
// (gratis, senza API key), i click attraversano l'iframe e arrivano
// comunque al contenitore della card (stesso onclick di apertura modale).
function fbThumbHtml(url) {
  const src = `https://www.facebook.com/plugins/video.php?href=${encodeURIComponent(fbEmbedUrl(url))}&show_text=false`;
  return `<iframe src="${esc(src)}" style="width:100%;height:100%;border:none;pointer-events:none" scrolling="no" frameborder="0" tabindex="-1"></iframe>`;
}

// Modal per video file caricati (non YouTube): player HTML5 nativo.
window.openVideoFileModal = (url, title) => {
  const overlay = document.createElement('div');
  overlay.className = 'video-modal-overlay';
  overlay.innerHTML = `
    <div class="video-modal-box">
      <button class="video-modal-close" onclick="this.closest('.video-modal-overlay').remove()">✕</button>
      <div class="video-modal-title">${esc(title || 'Video')}</div>
      <div class="video-modal-player">
        <video src="${esc(url)}" controls autoplay playsinline style="width:100%;height:100%;background:#000;border-radius:8px"
               onerror="this.parentNode.innerHTML='<div style=\\'color:#fff;padding:24px;text-align:center\\'>Impossibile riprodurre il video qui. <a href=&quot;${esc(url)}&quot; target=_blank style=color:#60a5fa>Aprilo in una nuova scheda</a></div>'"></video>
      </div>
    </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
};

// Modal per video Facebook: usa il "Video Plugin" pubblico di Meta
// (plugins/video.php), che incorpora qualunque video PUBBLICO senza bisogno
// di API key/app registrata — funziona solo se chi ha pubblicato il video
// non ne ha ristretto l'embed altrove (raro per le dirette di pagine
// pubbliche, ma può succedere: in quel caso Facebook stesso mostra un
// messaggio "video non disponibile" dentro l'iframe).
window.openFacebookVideoModal = (url, title) => {
  const overlay = document.createElement('div');
  overlay.className = 'video-modal-overlay';
  const src = `https://www.facebook.com/plugins/video.php?href=${encodeURIComponent(fbEmbedUrl(url))}&show_text=false&autoplay=true`;
  overlay.innerHTML = `
    <div class="video-modal-box">
      <button class="video-modal-close" onclick="this.closest('.video-modal-overlay').remove()">✕</button>
      <div class="video-modal-title">${esc(title || 'Video')}
        <a href="${esc(fbEmbedUrl(url))}" target="_blank" rel="noopener" style="float:right;color:#60a5fa;font-size:.78rem;font-weight:400">Apri su Facebook ↗</a>
      </div>
      <div class="video-modal-player">
        <iframe src="${esc(src)}" frameborder="0" allowfullscreen
                allow="autoplay; encrypted-media; picture-in-picture; web-share"
                style="width:100%;height:100%"></iframe>
      </div>
    </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
};

// ── TOAST ─────────────────────────────────────────────────────
// Notifica leggera in basso a destra, sparisce da sola dopo 3s.
// type: 'success' (verde) | 'info' (blu) | 'error' (rosso)
function showToast(msg, type = 'success') {
  const colors = { success: '#16a34a', info: '#2563eb', error: '#dc2626' };
  const t = document.createElement('div');
  t.textContent = msg;
  t.style.cssText = `position:fixed;bottom:24px;right:20px;z-index:99999;padding:10px 18px;border-radius:8px;background:${colors[type]||colors.success};color:#fff;font-size:.875rem;font-weight:600;box-shadow:0 4px 16px rgba(0,0,0,.3);opacity:0;transition:opacity .2s;pointer-events:none`;
  document.body.appendChild(t);
  requestAnimationFrame(() => { t.style.opacity = '1'; });
  setTimeout(() => { t.style.opacity = '0'; setTimeout(() => t.remove(), 220); }, 3000);
}

// ── AUTH HELPERS ──────────────────────────────────────────────
function authToken() { return localStorage.getItem('italiacrit-token'); }
function authUser()  {
  try { return JSON.parse(localStorage.getItem('italiacrit-user') || 'null'); } catch { return null; }
}
function authSave(token, user) {
  localStorage.setItem('italiacrit-token', token);
  localStorage.setItem('italiacrit-user', JSON.stringify(user));
}
function authClear() {
  localStorage.removeItem('italiacrit-token');
  localStorage.removeItem('italiacrit-user');
}
// Ricarica l'utente dal server (ruolo, nome…) e aggiorna token+localStorage.
// Serve a propagare i cambi di ruolo fatti dall'admin senza ri-login manuale.
async function refreshUser() {
  if (!authToken()) return null;
  try {
    const { user, token } = await apiCall('/auth/me');
    if (user) {
      authSave(token || authToken(), user);
      try { updateNavLoginState(); } catch {}
    }
    return user;
  } catch { return null; }
}

// ── ENTITY OVERRIDES / PHOTO ──────────────────────────────────
const _ovCache = {};
// Fallback statico (committato nel repo) per dati come i social ufficiali.
// Le modifiche da backend/admin hanno comunque la precedenza.
let _staticSocials = null;
async function _loadStaticSocials() {
  if (_staticSocials) return _staticSocials;
  try {
    _staticSocials = await fetch('data/entity_socials.json').then(r => r.ok ? r.json() : {});
  } catch { _staticSocials = {}; }
  return _staticSocials;
}
async function getEntityOverrides(type, id) {
  const key = `${type}:${id}`;
  if (_ovCache[key]) return _ovCache[key];
  const base = (await _loadStaticSocials())[key] || {};
  try {
    const { overrides } = await apiCall(`/admin/override/entity/${type}/${encodeURIComponent(id)}`);
    // Ignora i valori vuoti del backend così non cancellano il fallback statico
    const clean = {};
    for (const [k, v] of Object.entries(overrides || {})) {
      if (v !== null && v !== undefined && String(v).trim() !== '') clean[k] = v;
    }
    _ovCache[key] = { ...base, ...clean };
  } catch { _ovCache[key] = { ...base }; }
  return _ovCache[key];
}

function canUploadPhoto(entityType) {
  const user = authUser();
  if (!user) return false;
  if (user.role === 'admin') return true;
  if (entityType === 'atleta' && user.role === 'atleta') return true;
  if (entityType === 'team'   && user.role === 'team')   return true;
  // Un team verificato può modificare la foto profilo degli atleti del
  // proprio roster (mancava del tutto — pulsante nemmeno visibile per un
  // team su qualsiasi atleta, segnalato dall'utente). Mostrato in modo
  // ottimistico come già per l'atleta sopra (che non verifica qui se è
  // davvero il PROPRIO atleta_id): il server verifica il roster reale e
  // rifiuta con 403 se l'atleta non appartiene al team di chi carica.
  if (entityType === 'atleta' && user.role === 'team') return true;
  return false;
}

function photoAreaHtml(entityType, entityId, photoUrl, initials, shape = 'circle') {
  const size   = shape === 'circle' ? 96 : 88;
  const radius = shape === 'circle' ? '50%' : '10px';
  const canUp  = canUploadPhoto(entityType);
  const imgEl  = photoUrl
    ? `<img data-photo-id="${esc(entityId)}" src="${esc(mediaUrl(photoUrl))}"
           alt="Foto" style="width:100%;height:100%;object-fit:cover;object-position:top center;border-radius:${radius};display:block">`
    : `<div data-photo-id="${esc(entityId)}" style="width:100%;height:100%;border-radius:${radius};
           background:var(--bg-elevated);display:flex;align-items:center;justify-content:center;
           font-family:var(--font-display);font-size:${shape==='circle'?'1.8':'1.6'}rem;
           color:var(--text-muted);letter-spacing:.04em">${esc(initials)}</div>`;
  const hasPhoto = !!photoUrl;
  // Icona matita se la foto esiste già (modifica), fotocamera se va caricata.
  const camIcon = hasPhoto
    ? `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
         <path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z"/>
       </svg>`
    : `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
         <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/>
         <circle cx="12" cy="13" r="4"/>
       </svg>`;
  const camBtn = canUp ? `
    <button class="photo-cam-btn ${hasPhoto ? 'photo-cam-btn--edit' : ''}" title="${hasPhoto ? 'Modifica foto' : 'Carica foto'}"
      onclick="${hasPhoto
        ? `triggerPhotoCrop('${esc(entityType)}','${esc(entityId)}','${esc(photoUrl)}')`
        : `triggerPhotoUpload('${esc(entityType)}','${esc(entityId)}')`}">
      ${camIcon}
    </button>
    <input type="file" id="photo-file-${esc(entityId)}" accept="image/jpeg,image/png,image/webp"
      style="display:none" onchange="handlePhotoUpload(event,'${esc(entityType)}','${esc(entityId)}')">` : '';
  return `<div class="photo-area" style="width:${size}px;height:${size}px;flex-shrink:0;position:relative">
    ${imgEl}${camBtn}
  </div>`;
}

// ── SOCIAL LINKS (atleta / team) ──────────────────────────────
// Normalizza un handle o URL in un link pulito
function _normSocialUrl(kind, raw) {
  if (!raw) return '';
  let v = String(raw).trim();
  if (!v) return '';
  if (/^https?:\/\//i.test(v)) return v;
  v = v.replace(/^@/, '');
  if (kind === 'instagram') return 'https://instagram.com/' + v.replace(/^.*instagram\.com\//i, '');
  if (kind === 'facebook')  return 'https://facebook.com/'  + v.replace(/^.*facebook\.com\//i, '');
  if (kind === 'strava')    return 'https://www.strava.com/athletes/' + v.replace(/^.*strava\.com\/athletes\//i, '');
  if (kind === 'website')   return 'https://' + v;
  return v;
}

// Costruisce la riga di icone social a partire dagli override entità
function entitySocialLinksHtml(ov, kinds) {
  if (!ov) return '';
  const want = k => !kinds || kinds.includes(k);
  // Accetta sia 'instagram' che 'instagram_url' (il DB salva con _url, il file statico senza)
  const get = k => ov[k] || ov[k + '_url'] || null;
  const out = [];
  if (want('instagram') && get('instagram')) {
    out.push(`<a href="${esc(_normSocialUrl('instagram', get('instagram')))}" target="_blank" rel="noopener" class="media-profile-link" aria-label="Instagram"><svg class="social-icon social-icon-ig" viewBox="0 0 24 24"><rect x="2" y="2" width="20" height="20" rx="5" ry="5"/><path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"/><line x1="17.5" y1="6.5" x2="17.51" y2="6.5"/></svg> Instagram</a>`);
  }
  if (want('twitter') && get('twitter')) {
    out.push(`<a href="${esc(_normSocialUrl('twitter', get('twitter')))}" target="_blank" rel="noopener" class="media-profile-link" aria-label="X / Twitter"><svg class="social-icon" viewBox="0 0 24 24" fill="currentColor"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-4.714-6.231-5.401 6.231H2.744l7.737-8.835L1.254 2.25H8.08l4.253 5.622zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg> X</a>`);
  }
  if (want('facebook') && get('facebook')) {
    out.push(`<a href="${esc(_normSocialUrl('facebook', get('facebook')))}" target="_blank" rel="noopener" class="media-profile-link" aria-label="Facebook"><svg class="social-icon social-icon-fb" viewBox="0 0 24 24"><path d="M18 2h-3a5 5 0 0 0-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 0 1 1-1h3z"/></svg> Facebook</a>`);
  }
  if (want('strava') && get('strava')) {
    out.push(`<a href="${esc(_normSocialUrl('strava', get('strava')))}" target="_blank" rel="noopener" class="media-profile-link" aria-label="Strava"><svg class="social-icon social-icon-strava" viewBox="0 0 24 24"><path d="M15.387 17.944l-2.089-4.116h-3.065L15.387 24l5.15-10.172h-3.066m-7.008-5.599l2.836 5.598h4.172L10.463 0l-7 13.828h4.169"/></svg> Strava</a>`);
  }
  if (want('website') && get('website')) {
    out.push(`<a href="${esc(_normSocialUrl('website', get('website')))}" target="_blank" rel="noopener" class="media-profile-link" aria-label="Sito"><svg class="social-icon" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg> Sito</a>`);
  }
  if (!out.length) return '';
  return `<div class="media-profile-links profile-social-links">${out.join('')}</div>`;
}

// ── BANDIERE NAZIONALI ────────────────────────────────────────
// Mappa nome nazione (IT) → codice ISO a 2 lettere per generare l'emoji bandiera
const NATION_ISO = {
  'ITALIA':'IT','AUSTRIA':'AT','BELGIO':'BE','DANIMARCA':'DK','ESTONIA':'EE',
  'FINLANDIA':'FI','FRANCIA':'FR','GERMANIA':'DE','GRAN BRETAGNA':'GB','REGNO UNITO':'GB',
  'IRLANDA':'IE','LETTONIA':'LV','LITUANIA':'LT','LUSSEMBURGO':'LU','NORVEGIA':'NO',
  'OLANDA':'NL','PAESI BASSI':'NL','POLONIA':'PL','PORTOGALLO':'PT','REPUBBLICA CECA':'CZ',
  'ROMANIA':'RO','SLOVACCHIA':'SK','SLOVENIA':'SI','SPAGNA':'ES','SVEZIA':'SE',
  'SVIZZERA':'CH','UCRAINA':'UA','UNGHERIA':'HU','CROAZIA':'HR','SERBIA':'RS',
  'GRECIA':'GR','TURCHIA':'TR','SAN MARINO':'SM','STATI UNITI':'US','USA':'US',
  'COLOMBIA':'CO','AUSTRALIA':'AU','GIAPPONE':'JP','BIELORUSSIA':'BY','BULGARIA':'BG',
};
function _isoToFlag(iso) {
  return iso.toUpperCase().replace(/./g, c => String.fromCodePoint(0x1F1E6 + c.charCodeAt(0) - 65));
}
// Restituisce il codice ISO se il nome team è una nazionale, altrimenti null.
// Riconosce solo i nomi che SONO una nazione (evita falsi positivi tipo "ITALIA NUOVA BOLOGNA").
function nationIso(teamName) {
  if (!teamName) return null;
  let u = String(teamName).toUpperCase().trim();
  u = u.replace(/\s+NATIONAL\s+TEAM$/, '').replace(/^NAZIONALE\s+/, '').trim();
  if (u === 'PARALIMPICA') u = 'ITALIA'; // Nazionale Paralimpica Italiana
  return NATION_ISO[u] || null;
}
// Emoji bandiera (con spazio finale) da anteporre al nome di una nazionale, o '' se non è una nazionale.
function nationFlagPrefix(teamName) {
  const iso = nationIso(teamName);
  return iso ? _isoToFlag(iso) + ' ' : '';
}
// "LOMBARDIA", "LIGURIA", "NAZIONALE ROMANIA", ecc. non sono club reali: sono
// il nome sotto cui la FCI registra i risultati ai campionati italiani/
// internazionali (selezioni regionali/nazionali). Non devono avere una
// pagina /team/ propria né comparire come "squadra" in classifiche o elenchi
// — i risultati vanno sempre ricondotti al vero club dell'atleta (o restano
// visibili solo sulla sua pagina se un vero club non è determinabile).
function isSelectionTeamName(t) {
  if (!t) return false;
  if (nationIso(t)) return true;
  const u = t.toUpperCase().trim();
  if (ITALIAN_REGIONS.some(r => u === r)) return true;
  if (/^(SELEZIONE|NAZIONALE|CT ITALIA|UNDER|REGIONALE)/.test(u)) return true;
  return false;
}

window.triggerPhotoUpload = function(entityType, entityId) {
  document.getElementById(`photo-file-${entityId}`)?.click();
};

// Apre il cropper direttamente sulla foto esistente (fetch → dataUrl)
window.triggerPhotoCrop = function(entityType, entityId, photoPath) {
  // Carica la foto esistente tramite <img> (evita CORS su canvas usando crossOrigin anonymous)
  const img = new Image();
  img.crossOrigin = 'anonymous';
  img.onload = () => {
    // Converti in dataUrl tramite canvas temporaneo
    const tmp = document.createElement('canvas');
    tmp.width = img.naturalWidth; tmp.height = img.naturalHeight;
    try {
      tmp.getContext('2d').drawImage(img, 0, 0);
      const dataUrl = tmp.toDataURL('image/jpeg', 0.95);
      _openPhotoCropper(dataUrl, entityType, entityId, 'photo.jpg');
    } catch {
      // Canvas tainted (CORS non supportato): fallback al file picker
      document.getElementById(`photo-file-${entityId}`)?.click();
    }
  };
  img.onerror = () => document.getElementById(`photo-file-${entityId}`)?.click();
  img.src = mediaUrl(photoPath) + (photoPath.includes('?') ? '&' : '?') + '_t=' + Date.now();
};

// Avvio: legge il file scelto e apre l'editor di ritaglio invece di caricarlo subito.
window.handlePhotoUpload = function(evt, entityType, entityId) {
  const file = evt.target.files[0];
  if (evt.target) evt.target.value = ''; // consente di riselezionare lo stesso file
  if (!file) return;
  if (!/^image\//.test(file.type)) { alert('Seleziona un file immagine (JPG, PNG o WebP).'); return; }
  const reader = new FileReader();
  reader.onload = e => _openPhotoCropper(e.target.result, entityType, entityId, file.name);
  reader.readAsDataURL(file);
};

// Editor di ritaglio: zoom (slider/rotella) + trascinamento, anteprima live su canvas.
function _openPhotoCropper(dataUrl, entityType, entityId, filename, _entityIdForPicker) {
  const _pickerId = _entityIdForPicker || entityId;
  const isCircle = entityType !== 'team';
  const V = 300, OUT = 512; // viewport anteprima e dimensione esportata
  const img = new Image();
  img.onload = () => {
    const overlay = document.createElement('div');
    overlay.id = 'crop-overlay';
    overlay.className = 'crop-overlay';
    overlay.innerHTML = `
      <div class="crop-modal">
        <div class="crop-title">Ritaglia la foto</div>
        <div class="crop-stage" style="width:${V}px;height:${V}px">
          <canvas id="crop-canvas" width="${V}" height="${V}"></canvas>
          <div class="crop-frame ${isCircle ? 'crop-frame--circle' : ''}"></div>
        </div>
        <div class="crop-controls">
          <span class="crop-zoom-ico" aria-hidden="true">−</span>
          <input type="range" id="crop-zoom" min="1" max="4" step="0.01" value="1" aria-label="Zoom">
          <span class="crop-zoom-ico" aria-hidden="true">+</span>
        </div>
        <p class="crop-hint">Trascina per spostare · slider o rotella per lo zoom</p>
        <div class="crop-actions">
          <button class="auth-btn auth-btn-outline" id="crop-cancel">Annulla</button>
          <button class="auth-btn auth-btn-outline" id="crop-change" style="display:flex;align-items:center;gap:6px">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg>
            Cambia foto
          </button>
          <button class="auth-btn" id="crop-save">Salva</button>
        </div>
      </div>`;
    document.body.appendChild(overlay);

    const canvas = overlay.querySelector('#crop-canvas');
    const ctx = canvas.getContext('2d');
    const baseScale = Math.max(V / img.width, V / img.height); // "cover"
    let zoom = 1, scale = baseScale, ox = (V - img.width * scale) / 2, oy = (V - img.height * scale) / 2;

    function clamp() {
      const w = img.width * scale, h = img.height * scale;
      ox = Math.min(0, Math.max(V - w, ox));
      oy = Math.min(0, Math.max(V - h, oy));
    }
    function draw() {
      ctx.fillStyle = '#0c0c0c';
      ctx.fillRect(0, 0, V, V);
      ctx.drawImage(img, ox, oy, img.width * scale, img.height * scale);
    }
    function setZoom(z) {
      const prev = scale;
      zoom = z; scale = baseScale * zoom;
      ox = V / 2 - (V / 2 - ox) * (scale / prev);
      oy = V / 2 - (V / 2 - oy) * (scale / prev);
      clamp(); draw();
    }
    clamp(); draw();

    const zoomEl = overlay.querySelector('#crop-zoom');
    zoomEl.addEventListener('input', () => setZoom(parseFloat(zoomEl.value)));

    let dragging = false, lx = 0, ly = 0;
    const onMove = e => {
      if (!dragging) return;
      const p = e.touches ? e.touches[0] : e;
      ox += p.clientX - lx; oy += p.clientY - ly; lx = p.clientX; ly = p.clientY;
      clamp(); draw();
      if (e.cancelable) e.preventDefault();
    };
    const onUp = () => { dragging = false; };
    const onDown = e => { dragging = true; const p = e.touches ? e.touches[0] : e; lx = p.clientX; ly = p.clientY; };
    canvas.addEventListener('mousedown', onDown);
    canvas.addEventListener('touchstart', onDown, { passive: true });
    window.addEventListener('mousemove', onMove);
    window.addEventListener('touchmove', onMove, { passive: false });
    window.addEventListener('mouseup', onUp);
    window.addEventListener('touchend', onUp);
    const onWheel = e => {
      e.preventDefault();
      const nz = Math.min(4, Math.max(1, zoom + (e.deltaY < 0 ? 0.12 : -0.12)));
      zoomEl.value = nz; setZoom(nz);
    };
    canvas.addEventListener('wheel', onWheel, { passive: false });

    function close() {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('touchmove', onMove);
      window.removeEventListener('mouseup', onUp);
      window.removeEventListener('touchend', onUp);
      overlay.remove();
    }
    overlay.querySelector('#crop-cancel').addEventListener('click', close);
    overlay.querySelector('#crop-change').addEventListener('click', () => {
      close();
      document.getElementById(`photo-file-${_pickerId}`)?.click();
    });
    overlay.addEventListener('click', e => { if (e.target === overlay) close(); });
    overlay.querySelector('#crop-save').addEventListener('click', () => {
      const out = document.createElement('canvas');
      out.width = OUT; out.height = OUT;
      const octx = out.getContext('2d');
      octx.fillStyle = '#ffffff';
      octx.fillRect(0, 0, OUT, OUT);
      const r = OUT / V;
      octx.drawImage(img, ox * r, oy * r, img.width * scale * r, img.height * scale * r);
      out.toBlob(blob => {
        close();
        const name = (filename || 'photo').replace(/\.[^.]+$/, '') + '.jpg';
        _uploadPhotoBlob(blob, entityType, entityId, name);
      }, 'image/jpeg', 0.9);
    });
  };
  img.src = dataUrl;
}

// Carica l'immagine ritagliata sul server e aggiorna subito la UI.
async function _uploadPhotoBlob(blob, entityType, entityId, filename) {
  const btn = document.querySelector(`.photo-cam-btn`);
  if (btn) { btn.style.opacity = '0.5'; btn.style.pointerEvents = 'none'; }
  const fd = new FormData();
  // I campi testo devono venire PRIMA del file per essere disponibili in multer
  fd.append('entity_type', entityType);
  fd.append('entity_id', entityId);
  fd.append('photo', blob, filename || 'photo.jpg');
  try {
    const token = authToken();
    const res  = await fetch(`${API_BASE}/upload/photo`, {
      method: 'POST',
      headers: token ? { Authorization: `Bearer ${token}` } : {},
      body: fd,
    });
    let data;
    try { data = await res.json(); } catch { throw new Error('Risposta non valida dal server — è in esecuzione?'); }
    if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
    // Update cache and DOM without full re-render
    const key = `${entityType}:${entityId}`;
    // Salva URL con timestamp nel cache così anche le miniature ranking useranno la versione nuova
    const bustedUrl = data.photo_url + (data.photo_url.includes('?') ? '&' : '?') + '_v=' + Date.now();
    if (_ovCache[key]) _ovCache[key].photo_url = bustedUrl;
    else _ovCache[key] = { photo_url: bustedUrl };
    const target = document.querySelector(`[data-photo-id="${entityId}"]`);
    if (target) {
      const radius = entityType === 'team' ? '10px' : '50%';
      const newImg = document.createElement('img');
      newImg.src = `${MEDIA_BASE}${bustedUrl}`;
      newImg.setAttribute('data-photo-id', entityId);
      newImg.style.cssText = `width:100%;height:100%;object-fit:cover;object-position:top center;border-radius:${radius};display:block`;
      target.replaceWith(newImg);
    }
    const toast = document.createElement('div');
    toast.className = 'upload-toast';
    toast.textContent = 'Foto aggiornata ✓';
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2500);
  } catch (err) {
    alert('Errore upload: ' + err.message);
  } finally {
    if (btn) { btn.style.opacity = ''; btn.style.pointerEvents = ''; }
  }
}

async function apiCall(path, opts = {}) {
  const token = authToken();
  const res = await fetch(API_BASE + path, {
    ...opts,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(opts.headers || {}),
    },
    body: opts.body ? JSON.stringify(opts.body) : undefined,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
  return data;
}

// Estrae un messaggio d'errore leggibile da una Response (anche se il corpo è HTML)
async function _resErr(res) {
  let msg = `HTTP ${res.status}`;
  try {
    const ct = res.headers.get('content-type') || '';
    if (ct.includes('application/json')) {
      const j = await res.json();
      if (j && j.error) msg = j.error;
    } else if (res.status === 404) {
      msg = 'Endpoint non trovato sul server (404). La rotta potrebbe non essere ancora deployata su Render.';
    } else if (res.status === 405) {
      msg = 'Metodo non consentito sul server (405).';
    } else {
      msg = `Errore server (HTTP ${res.status}).`;
    }
  } catch { /* lascia il messaggio di default */ }
  return msg;
}

// Richiesta su /admin/users/:id con fallback automatico se PATCH non è gestito dal backend
async function _adminUserReq(userId, opts) {
  let res = await fetch(`${API_BASE}/admin/users/${userId}`, opts);
  // Se la rotta/metodo non esiste, prova convenzioni alternative comuni
  if (!res.ok && (res.status === 404 || res.status === 405) && opts.method === 'PATCH') {
    try { res = await fetch(`${API_BASE}/admin/users/${userId}/role`, { ...opts, method: 'POST' }); }
    catch { /* mantiene la prima response */ }
  }
  return res;
}

function updateNavLoginState() {
  const user = authUser();
  const link = document.getElementById('nav-login');
  const drawerLink = document.getElementById('drawer-login');
  const bell    = document.getElementById('notif-bell');
  const msgBell = document.getElementById('msg-bell');
  const navMsg  = document.getElementById('nav-msg');
  const drawerMsg = document.getElementById('drawer-msg');
  if (user) {
    const label = user.display_name?.split(' ')[0] || 'Profilo';
    if (link)       { link.textContent = label; link.href = '#/profilo'; link.id = 'nav-login'; }
    if (drawerLink) { drawerLink.textContent = label; drawerLink.href = '#/profilo'; }
    if (bell)    bell.style.display = 'flex';
    if (msgBell) msgBell.style.display = 'flex';
    // nav-msg (desktop) sempre nascosto: l'icona busta nel navbar gestisce i msg su desktop
    if (navMsg)  navMsg.style.display = 'none';
    if (drawerMsg) { drawerMsg.style.display = ''; }
    const drawerSectionMsg = document.getElementById('drawer-section-msg');
    if (drawerSectionMsg) drawerSectionMsg.style.display = '';
    startNotifPolling();
    startMsgPolling();
  } else {
    if (link)       { link.textContent = 'Login'; link.href = '#/login'; }
    if (drawerLink) { drawerLink.textContent = 'Login / Profilo'; drawerLink.href = '#/login'; }
    if (bell)    bell.style.display = 'none';
    if (msgBell) msgBell.style.display = 'none';
    if (navMsg)  navMsg.style.display = 'none';
    if (drawerMsg) drawerMsg.style.display = 'none';
    const drawerSectionMsg = document.getElementById('drawer-section-msg');
    if (drawerSectionMsg) drawerSectionMsg.style.display = 'none';
    stopNotifPolling();
    stopMsgPolling();
  }
}

// ── NOTIFICATION SYSTEM ────────────────────────────────────────────────────────
let _notifPollTimer = null;

function startNotifPolling() {
  if (_notifPollTimer) return; // già attivo
  refreshNotifCount(); // subito al login
  _notifPollTimer = setInterval(refreshNotifCount, 60_000); // ogni minuto
}
function stopNotifPolling() {
  if (_notifPollTimer) { clearInterval(_notifPollTimer); _notifPollTimer = null; }
  const badge = document.getElementById('notif-badge');
  if (badge) { badge.style.display = 'none'; badge.textContent = '0'; }
}

async function refreshNotifCount() {
  const token = authToken();
  if (!token) return;
  try {
    const d = await fetch(`${API_BASE}/notifications/count`, {
      headers: { Authorization: `Bearer ${token}` }
    }).then(r => r.json());
    const count = d.count || 0;
    const badge = document.getElementById('notif-badge');
    if (!badge) return;
    if (count > 0) {
      badge.textContent = count > 99 ? '99+' : count;
      badge.style.display = 'flex';
    } else {
      badge.style.display = 'none';
    }
  } catch { /* silenzioso */ }
}

window.toggleNotifPanel = function() {
  const existing = document.getElementById('notif-panel');
  if (existing) { existing.remove(); return; }
  renderNotifPanel();
  // Chiudi cliccando fuori
  setTimeout(() => {
    document.addEventListener('click', function handler(e) {
      const panel = document.getElementById('notif-panel');
      const bell  = document.getElementById('notif-bell');
      if (panel && !panel.contains(e.target) && !bell?.contains(e.target)) {
        panel.remove();
        document.removeEventListener('click', handler);
      }
    });
  }, 50);
};

async function renderNotifPanel() {
  const token = authToken();
  if (!token) return;
  const panel = document.createElement('div');
  panel.id = 'notif-panel';
  panel.className = 'notif-panel';
  panel.innerHTML = `
    <div class="notif-panel-head">
      <span>🔔 Notifiche</span>
      <button onclick="window._notifMarkAllRead()">Segna tutte come lette</button>
    </div>
    <div class="notif-list" id="notif-list"><div class="notif-empty">Caricamento…</div></div>`;
  document.body.appendChild(panel);

  try {
    // Carica e segna come lette in parallelo
    const [d] = await Promise.all([
      fetch(`${API_BASE}/notifications`, { headers: { Authorization: `Bearer ${token}` } }).then(r => r.json()),
      fetch(`${API_BASE}/notifications/read-all`, { method: 'PATCH', headers: { Authorization: `Bearer ${token}` } }).catch(() => {}),
    ]);
    // Azzera badge subito
    const badge = document.getElementById('notif-badge');
    if (badge) badge.style.display = 'none';

    const notifications = d.notifications || [];
    const listEl = document.getElementById('notif-list');
    if (!listEl) return;
    if (!notifications.length) {
      listEl.innerHTML = '<div class="notif-empty">Nessuna notifica</div>';
      return;
    }
    listEl.innerHTML = notifications.map(n => {
      const ago = formatTimeAgo(n.created_at);
      const cls = n.read ? 'notif-item read' : 'notif-item unread';
      return `<div class="${cls}" data-id="${n.id}">
        <div class="notif-dot"></div>
        <div class="notif-content">
          <div class="notif-title">${esc(n.title)}</div>
          ${n.body ? `<div class="notif-body">${esc(n.body)}</div>` : ''}
          <div class="notif-time">${ago}</div>
        </div>
        <button class="notif-del" onclick="window._notifDelete(${n.id},this)" title="Elimina">✕</button>
      </div>`;
    }).join('');
  } catch(e) {
    const listEl = document.getElementById('notif-list');
    if (listEl) listEl.innerHTML = `<div class="notif-empty">Errore: ${esc(e.message)}</div>`;
  }
}

window._notifMarkAllRead = async function() {
  const token = authToken();
  if (!token) return;
  await fetch(`${API_BASE}/notifications/read-all`, { method: 'PATCH', headers: { Authorization: `Bearer ${token}` } }).catch(() => {});
  document.querySelectorAll('.notif-item.unread').forEach(el => el.classList.replace('unread', 'read'));
  const badge = document.getElementById('notif-badge');
  if (badge) badge.style.display = 'none';
};

window._notifDelete = async function(id, btn) {
  const token = authToken();
  if (!token) return;
  btn.closest('.notif-item')?.remove();
  await fetch(`${API_BASE}/notifications/${id}`, { method: 'DELETE', headers: { Authorization: `Bearer ${token}` } }).catch(() => {});
  // Se non ci sono più items, mostra empty state
  const list = document.getElementById('notif-list');
  if (list && !list.querySelector('.notif-item')) {
    list.innerHTML = '<div class="notif-empty">Nessuna notifica</div>';
  }
};

function formatTimeAgo(isoStr) {
  const diff = Math.floor((Date.now() - new Date(isoStr).getTime()) / 1000);
  if (diff < 60)   return 'adesso';
  if (diff < 3600) return `${Math.floor(diff/60)} min fa`;
  if (diff < 86400) return `${Math.floor(diff/3600)} ore fa`;
  return `${Math.floor(diff/86400)} giorni fa`;
}

// ── MESSAGE POLLING ────────────────────────────────────────────────────────────
let _msgPollTimer = null;

function startMsgPolling() {
  if (_msgPollTimer) return;
  refreshMsgCount();
  _msgPollTimer = setInterval(refreshMsgCount, 30_000); // ogni 30s
}
function stopMsgPolling() {
  if (_msgPollTimer) { clearInterval(_msgPollTimer); _msgPollTimer = null; }
  const badge = document.getElementById('msg-badge');
  if (badge) { badge.style.display = 'none'; badge.textContent = '0'; }
  const drawerBadge = document.getElementById('drawer-msg-badge');
  if (drawerBadge) { drawerBadge.style.display = 'none'; drawerBadge.textContent = '0'; }
}

async function refreshMsgCount() {
  const token = authToken();
  if (!token) return;
  try {
    const d = await fetch(`${API_BASE}/messages/unread-count`, {
      headers: { Authorization: `Bearer ${token}` }
    }).then(r => r.json());
    const count = d.count || 0;
    // Badge icona busta desktop
    const badge = document.getElementById('msg-badge');
    if (badge) {
      if (count > 0) {
        badge.textContent = count > 99 ? '99+' : count;
        badge.style.display = 'flex';
      } else {
        badge.style.display = 'none';
      }
    }
    // Badge link Messaggi nel drawer mobile
    const drawerBadge = document.getElementById('drawer-msg-badge');
    if (drawerBadge) {
      if (count > 0) {
        drawerBadge.textContent = count > 99 ? '99+' : count;
        drawerBadge.style.display = 'inline-flex';
      } else {
        drawerBadge.style.display = 'none';
      }
    }
  } catch { /* silenzioso */ }
}

// ── INBOX & MESSAGING ─────────────────────────────────────────────────────────
async function renderInbox(activeConvId) {
  const user = authUser();
  if (!user) { window.location.hash = '#/login'; return; }

  setPage(`<div class="loading-bar"></div>`);

  // Carica conversazioni
  let conversations = [];
  try {
    const d = await apiCall('/messages/conversations');
    conversations = d.conversations || [];
  } catch(e) {
    setPage(`<div class="error-msg">Errore caricamento: ${esc(e.message)}</div>`);
    return;
  }

  // Se non c'è una convo attiva ma ce n'è una, apri la prima (solo desktop)
  if (!activeConvId && conversations.length > 0 && window.innerWidth > 700) {
    activeConvId = conversations[0].id;
  }

  const convListHtml = conversations.length
    ? conversations.map(c => {
        const initial = (c.other_display_name || '?')[0].toUpperCase();
        const unreadHtml = c.unread_count > 0
          ? `<span class="msg-conv-badge">${c.unread_count}</span>` : '';
        const isActive = String(c.id) === String(activeConvId);
        const isUnread = c.unread_count > 0;
        const cls = `msg-conv-item${isActive?' active':''}${isUnread?' unread':''}`;
        const roleIcon = { atleta: '🚴', team: '👥', media: '📷', admin: '⚙' }[c.other_role] || '👤';
        return `<div class="${cls}" onclick="window._msgOpenConv(${c.id})" data-conv-id="${c.id}">
          <div class="msg-conv-avatar">${initial}</div>
          <div class="msg-conv-info">
            <div class="msg-conv-name">
              <span>${roleIcon} ${esc(c.other_display_name || 'Utente')}</span>
              <span class="msg-conv-time">${c.last_at ? formatTimeAgo(c.last_at) : ''}</span>
            </div>
            <div class="msg-conv-preview">${esc(c.last_msg || 'Nessun messaggio')}</div>
          </div>
          ${unreadHtml}
        </div>`;
      }).join('')
    : `<div class="msg-inbox-empty">📭 Nessuna conversazione<br/><span style="font-size:.75rem">Avvia una chat dal profilo di un atleta, team o fotografo</span></div>`;

  setPage(`
    <div class="comp-section" style="padding:0;max-width:1100px;margin:20px auto">
      <div class="msg-layout" id="msg-layout">
        <div class="msg-inbox-panel">
          <div class="msg-inbox-head">
            <span>✉ Messaggi</span>
          </div>
          <div class="msg-new-search">
            <svg class="search-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
            <input type="search" id="msg-user-search" placeholder="Cerca utente per inviare un messaggio…" autocomplete="off"
              oninput="window._msgUserSearch(this.value)" onfocus="window._msgUserSearch(this.value)" />
            <div class="msg-user-results" id="msg-user-results" style="display:none"></div>
          </div>
          <div class="msg-conv-list" id="msg-conv-list">${convListHtml}</div>
        </div>
        <div class="msg-thread-panel" id="msg-thread-panel">
          <div class="msg-thread-empty" id="msg-thread-empty">
            ${activeConvId ? '<div class="loading-bar"></div>' : '← Seleziona una conversazione'}
          </div>
        </div>
      </div>
    </div>`);

  if (activeConvId) {
    await _msgLoadThread(activeConvId);
  }

  // Ricerca utente per nuova conversazione
  let _msgSearchTimer = null;
  window._msgUserSearch = function(q) {
    clearTimeout(_msgSearchTimer);
    const box = document.getElementById('msg-user-results');
    if (!box) return;
    if (!q || q.trim().length < 2) { box.style.display = 'none'; return; }
    _msgSearchTimer = setTimeout(async () => {
      try {
        const d = await apiCall(`/users/search?q=${encodeURIComponent(q.trim())}`);
        const users = d.users || [];
        if (!users.length) { box.innerHTML = '<div style="padding:12px 14px;font-size:.8rem;color:var(--text-muted)">Nessun utente trovato</div>'; box.style.display = 'block'; return; }
        const roleIcon = { atleta:'🚴', team:'👥', media:'📷', admin:'⚙️' };
        box.innerHTML = users.map(u => `
          <div class="msg-user-result-item" onclick="window._msgStartFromSearch(${u.id},'${esc(u.display_name||'Utente')}')">
            <div class="msg-user-result-avatar">${(u.display_name||'?')[0].toUpperCase()}</div>
            <div>
              <div class="msg-user-result-name">${esc(u.display_name||'Utente')}</div>
              <div class="msg-user-result-role">${roleIcon[u.role]||'👤'} ${u.role}</div>
            </div>
          </div>`).join('');
        box.style.display = 'block';
      } catch { box.style.display = 'none'; }
    }, 280);
  };
  window._msgStartFromSearch = async function(userId, userName) {
    const box = document.getElementById('msg-user-results');
    const inp = document.getElementById('msg-user-search');
    if (box) box.style.display = 'none';
    if (inp) inp.value = '';
    await window.startConversation(userId, userName);
  };
  // Chiudi risultati se clicchi fuori
  document.addEventListener('click', function(e) {
    const box = document.getElementById('msg-user-results');
    const wrap = document.querySelector('.msg-new-search');
    if (box && wrap && !wrap.contains(e.target)) box.style.display = 'none';
  }, { capture: true });

  window._msgOpenConv = async (convId) => {
    // Aggiorna attivo nella lista
    document.querySelectorAll('.msg-conv-item').forEach(el => {
      el.classList.toggle('active', String(el.dataset.convId) === String(convId));
    });
    // Mobile: mostra thread
    document.getElementById('msg-layout')?.classList.add('thread-open');
    window.history.replaceState(null, '', `#/messaggi/${convId}`);
    await _msgLoadThread(convId);
  };
}

async function _msgLoadThread(convId) {
  const threadPanel = document.getElementById('msg-thread-panel');
  if (!threadPanel) return;
  const user = authUser();

  // Spinner
  threadPanel.innerHTML = `<div class="msg-thread-empty"><div class="loading-bar" style="width:60%"></div></div>`;

  try {
    const d = await apiCall(`/messages/conversations/${convId}`);
    const { conversation: conv, messages } = d;
    const other_user_id = conv.user_a === user.id ? conv.user_b : conv.user_a;

    // Aggrega per data
    let lastDate = '';
    const msgsHtml = messages.map(m => {
      const isSent = m.sender_id === user.id;
      const msgDate = new Date(m.created_at).toLocaleDateString('it-IT', { day:'numeric', month:'long' });
      const dateSep = msgDate !== lastDate
        ? `<div class="msg-date-sep">${msgDate}</div>`
        : '';
      lastDate = msgDate;
      const timeStr = new Date(m.created_at).toLocaleTimeString('it-IT', { hour:'2-digit', minute:'2-digit' });
      return `${dateSep}
        <div class="msg-bubble-wrap ${isSent ? 'sent' : 'received'}">
          <div class="msg-bubble">${_msgRenderBody(m.body)}</div>
          <div class="msg-bubble-time">${timeStr}</div>
        </div>`;
    }).join('');

    // Ottieni nome dell'altro utente (già nella convo se caricata dall'inbox)
    const convItem = document.querySelector(`[data-conv-id="${convId}"]`);
    const otherName = convItem?.querySelector('.msg-conv-name span')?.textContent || 'Utente';

    threadPanel.innerHTML = `
      <div class="msg-thread-head">
        <button class="msg-back-btn" onclick="document.getElementById('msg-layout')?.classList.remove('thread-open');window.history.replaceState(null,'','#/messaggi')">←</button>
        <div class="msg-conv-avatar">${otherName.replace(/^[^ ]+ /,'')[0]?.toUpperCase() || '?'}</div>
        <div class="msg-thread-head-info">
          <span>${otherName}</span>
          <span class="msg-thread-head-sub">Attivo ora</span>
        </div>
      </div>
      <div class="msg-thread-body" id="msg-thread-body">
        ${msgsHtml || '<div style="text-align:center;color:var(--text-muted);padding:40px;font-size:.85rem">Scrivi il primo messaggio 👇</div>'}
      </div>
      <div class="msg-input-area">
        <div class="msg-attach-wrap">
          <button class="msg-attach-btn" onclick="window._msgToggleAttach(${convId})" title="Allega foto, video o link" aria-label="Allega">＋</button>
          <div class="msg-attach-menu" id="msg-attach-menu" style="display:none">
            <button onclick="window._msgAttachUrl(${convId},'foto')">🖼️ Foto (link)</button>
            <button onclick="window._msgAttachUrl(${convId},'video')">🎬 Video (link)</button>
            <button onclick="window._msgAttachUrl(${convId},'link')">🔗 Link</button>
            <button onclick="window._msgAttachFromCollection(${convId})">📸 Dalla raccolta</button>
          </div>
        </div>
        <textarea id="msg-input" placeholder="Scrivi un messaggio…" rows="1"
          onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();window._msgSend(${convId})}"
          oninput="this.style.height='auto';this.style.height=this.scrollHeight+'px'"></textarea>
        <button class="msg-send-btn" onclick="window._msgSend(${convId})" title="Invia">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/>
          </svg>
        </button>
      </div>`;

    // Scroll all fondo
    const body = document.getElementById('msg-thread-body');
    if (body) body.scrollTop = body.scrollHeight;

    // Azzera badge unread per questa convo nella lista
    const convItem2 = document.querySelector(`[data-conv-id="${convId}"]`);
    if (convItem2) {
      convItem2.classList.remove('unread');
      convItem2.querySelector('.msg-conv-badge')?.remove();
    }
    // Rifresca conteggio globale
    refreshMsgCount();

  } catch(e) {
    threadPanel.innerHTML = `<div class="msg-thread-empty">Errore: ${esc(e.message)}</div>`;
  }

  // Polling auto ogni 8s per nuovi messaggi mentre la chat è aperta
  clearInterval(window._msgThreadPoll);
  window._msgThreadPoll = setInterval(async () => {
    if (!document.getElementById('msg-thread-body')) { clearInterval(window._msgThreadPoll); return; }
    try {
      const d = await apiCall(`/messages/conversations/${convId}`);
      const body = document.getElementById('msg-thread-body');
      if (!body) return;
      const { messages } = d;
      const user = authUser();
      let lastDate = '';
      const msgsHtml = messages.map(m => {
        const isSent = m.sender_id === user.id;
        const msgDate = new Date(m.created_at).toLocaleDateString('it-IT', { day:'numeric', month:'long' });
        const dateSep = msgDate !== lastDate ? `<div class="msg-date-sep">${msgDate}</div>` : '';
        lastDate = msgDate;
        const timeStr = new Date(m.created_at).toLocaleTimeString('it-IT', { hour:'2-digit', minute:'2-digit' });
        return `${dateSep}<div class="msg-bubble-wrap ${isSent?'sent':'received'}"><div class="msg-bubble">${_msgRenderBody(m.body)}</div><div class="msg-bubble-time">${timeStr}</div></div>`;
      }).join('');
      const wasAtBottom = body.scrollHeight - body.scrollTop - body.clientHeight < 60;
      body.innerHTML = msgsHtml;
      if (wasAtBottom) body.scrollTop = body.scrollHeight;
      refreshMsgCount();
    } catch {}
  }, 8000);
}

// Renderizza il corpo di un messaggio rilevando URL → foto / video / link
function _msgRenderBody(body) {
  if (!body) return '';
  const urlRe = /(https?:\/\/[^\s]+)/g;
  let out = '', last = 0, m;
  while ((m = urlRe.exec(body)) !== null) {
    out += esc(body.slice(last, m.index));
    const raw = m[0];
    const clean = raw.replace(/[)\].,;!?'"]+$/, '');
    const lower = clean.toLowerCase().split('?')[0].split('#')[0];
    if (/\.(jpe?g|png|gif|webp|avif|bmp|svg)$/.test(lower)) {
      out += `<a href="${esc(clean)}" target="_blank" rel="noopener"><img class="msg-media" src="${esc(clean)}" loading="lazy" alt="foto condivisa"/></a>`;
    } else if (/\.(mp4|webm|mov|m4v|ogg)$/.test(lower)) {
      out += `<video class="msg-media" src="${esc(clean)}" controls preload="metadata"></video>`;
    } else if (/(youtube\.com\/watch|youtu\.be\/|vimeo\.com\/)/.test(lower)) {
      out += `<a class="msg-link" href="${esc(clean)}" target="_blank" rel="noopener">▶ ${esc(clean)}</a>`;
    } else {
      out += `<a class="msg-link" href="${esc(clean)}" target="_blank" rel="noopener">🔗 ${esc(clean)}</a>`;
    }
    last = m.index + raw.length;
  }
  out += esc(body.slice(last));
  return out;
}

// Invio generico (riusabile da allegati e raccolta)
window._msgSendBody = async function(convId, text) {
  const body = (text || '').trim();
  if (!body) return;
  try {
    await apiCall(`/messages/conversations/${convId}/send`, { method: 'POST', body: { body } });
    await _msgLoadThread(convId);
  } catch(e) {
    showToast('Errore invio: ' + e.message, 'error');
  }
};

window._msgSend = async function(convId) {
  const input = document.getElementById('msg-input');
  const body = input?.value.trim();
  if (!body) return;
  input.value = '';
  input.style.height = 'auto';
  try {
    await apiCall(`/messages/conversations/${convId}/send`, {
      method: 'POST',
      body: { body },
    });
    // Ricarica thread
    await _msgLoadThread(convId);
  } catch(e) {
    showToast('Errore invio: ' + e.message, 'error');
    if (input) input.value = body; // rimetti il testo
  }
};

// ── Allegati: foto / video / link / raccolta ──────────────────
window._msgToggleAttach = function() {
  const menu = document.getElementById('msg-attach-menu');
  if (menu) menu.style.display = menu.style.display === 'none' ? 'flex' : 'none';
};
window._msgAttachUrl = function(convId, kind) {
  const menu = document.getElementById('msg-attach-menu');
  if (menu) menu.style.display = 'none';
  const label = kind === 'foto' ? 'Incolla il link della foto (jpg, png, webp…)'
            : kind === 'video' ? 'Incolla il link del video (mp4, YouTube, Vimeo…)'
            : 'Incolla il link da condividere';
  const url = prompt(label, '');
  if (!url || !url.trim()) return;
  const u = url.trim();
  if (!/^https?:\/\//i.test(u)) { showToast('Inserisci un link valido (http/https)', 'error'); return; }
  const caption = prompt('Aggiungi un commento (opzionale):', '') || '';
  const body = caption.trim() ? `${caption.trim()}\n${u}` : u;
  window._msgSendBody(convId, body);
};
window._msgAttachFromCollection = function(convId) {
  const menu = document.getElementById('msg-attach-menu');
  if (menu) menu.style.display = 'none';
  const items = (typeof getMediaCollection === 'function') ? getMediaCollection() : [];
  if (!items.length) { showToast('La tua raccolta è vuota. Salva foto/video con ＋ nelle gallery.', 'info'); return; }
  window._msgPickerItems = items;
  const grid = items.map((it, i) => `
    <div class="msg-pick-item" onclick="window._msgSendCollItem(${convId}, ${i})" title="${esc(it.title || '')}">
      ${it.type === 'video'
        ? '<div class="msg-pick-vid">🎬</div>'
        : `<img src="${esc(it.url)}" loading="lazy" alt=""/>`}
      <span class="msg-pick-type">${it.type === 'video' ? '🎬' : '📷'}</span>
    </div>`).join('');
  const ov = document.createElement('div');
  ov.className = 'msg-picker-overlay';
  ov.id = 'msg-picker-overlay';
  ov.onclick = (e) => { if (e.target === ov) window._msgClosePicker(); };
  ov.innerHTML = `
    <div class="msg-picker-box">
      <div class="msg-picker-head">
        <span>📸 Condividi dalla raccolta</span>
        <button onclick="window._msgClosePicker()" aria-label="Chiudi">✕</button>
      </div>
      <div class="msg-picker-grid">${grid}</div>
    </div>`;
  document.body.appendChild(ov);
};
window._msgSendCollItem = function(convId, idx) {
  const it = (window._msgPickerItems || [])[idx];
  window._msgClosePicker();
  if (it && it.url) {
    const body = it.title ? `${it.title}\n${it.url}` : it.url;
    window._msgSendBody(convId, body);
  }
};
window._msgClosePicker = function() {
  document.getElementById('msg-picker-overlay')?.remove();
};

// Avvia conversazione da bottone su profilo esterno
window.startConversation = async function(otherUserId, otherName) {
  const user = authUser();
  if (!user) { showToast('Accedi per inviare messaggi', 'info'); window.location.hash = '#/login'; return; }
  if (otherUserId === user.id) { showToast('Non puoi scrivere a te stesso 😅', 'info'); return; }
  try {
    showToast('Apertura chat…', 'info');
    const d = await apiCall('/messages/conversations', { method: 'POST', body: { other_user_id: otherUserId } });
    window.location.hash = `#/messaggi/${d.conversation_id}`;
  } catch(e) {
    showToast('Errore: ' + e.message, 'error');
  }
};

// ── REGION NORMALIZATION ───────────────────────────────────────
const ITALIAN_REGIONS = [
  "TRENTINO ALTO ADIGE", "FRIULI VENEZIA GIULIA", "VALLE D AOSTA", "EMILIA ROMAGNA",
  "ABRUZZO","BASILICATA","CALABRIA","CAMPANIA","LAZIO","LIGURIA","LOMBARDIA",
  "MARCHE","MOLISE","PIEMONTE","PUGLIA","SARDEGNA","SICILIA","TOSCANA",
  "UMBRIA","VENETO","BOLZANO","TRENTO"
];
// Il calendario (Excel curato a mano) usa a volte una grafia abbreviata
// diversa da quella canonica sopra (es. "VAL D AOSTA" invece di "VALLE D
// AOSTA") — senza normalizzarle, filtri/mappa le trattano come due regioni
// diverse per lo stesso posto.
const REGION_ALIASES = { "VAL D AOSTA": "VALLE D AOSTA", "VAL DAOSTA": "VALLE D AOSTA" };
function normalizeRegion(s) {
  if (!s) return '';
  const t = s.toUpperCase().trim().replace(/'/g, '');
  if (REGION_ALIASES[t]) return REGION_ALIASES[t];
  // Ordina per lunghezza discendente: le più lunghe prima (EMILIA ROMAGNA prima di EMILIA)
  for (const reg of ITALIAN_REGIONS) {
    if (t.startsWith(reg)) return reg;
  }
  return t;
}

// ── DATA CACHE ────────────────────────────────────────────────
const cache = {};
async function loadJson(path) {
  if (cache[path]) return cache[path];
  try {
    // Niente più cache-busting (?_t=timestamp) né cache:'no-store': la
    // freschezza dei dati è già garantita dal service worker, che applica
    // "network-first" a ogni richiesta /data/*.json (fetch reale ogni volta,
    // cache solo come fallback offline) — vedi sw.js. Un URL con querystring
    // variabile però NON termina in ".json", quindi bypassava proprio quella
    // logica dedicata E impediva a Cloudflare/GitHub Pages di servire una
    // risposta cache condivisa fra utenti, obbligando ogni caricamento a
    // riscaricare da zero fino a ~19MB di JSON (results_raw + athletes +
    // teams + race_details) — la causa principale della lentezza iniziale.
    const r = await fetch(path);
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    const data = await r.json();
    cache[path] = data;
    return data;
  } catch (e) {
    console.warn(`loadJson(${path}):`, e);
    return null;
  }
}

// ── Esclusione gare estere finite per errore nei dati FCI ──────────────────
// Lo scraper FCI a volte importa gare disputate all'estero (es. E3 Saxo
// Classic, Corsa della Pace Juniores) dentro i risultati/punti di atleti che
// non sono nemmeno tesserati italiani. Non possiamo correggere la fonte (i
// file data/*.json sono generati da una pipeline esterna che non gestiamo
// qui), quindi li filtriamo qui al caricamento: rimossi da risultati/punti
// dell'atleta E, separatamente, sottratti dalla classifica precalcolata
// (data/rankings/*.json), che è un file indipendente con i propri totali.
let _excludedGaraIdsPromise = null;
async function getExcludedGaraIds() {
  if (!_excludedGaraIdsPromise) {
    _excludedGaraIdsPromise = (async () => {
      try {
        const r = await fetch(`${API_BASE}/gara-overrides/excluded`);
        if (!r.ok) throw new Error('HTTP ' + r.status);
        const d = await r.json();
        return new Set(d.excluded || []);
      } catch (e) {
        console.warn('getExcludedGaraIds:', e);
        return new Set();
      }
    })();
  }
  return _excludedGaraIdsPromise;
}

// atleta_id -> { punti, gare, vittorie, p1, p2, p3, pout } rimossi dalla
// classifica precalcolata (rankings/*.json), calcolato una volta dal
// filtraggio di athletes.json e riusato da loadRanking per ogni categoria.
let _garaExclusionAthDelta = new Map();

function _addExclusionDelta(atletaId, r) {
  let d = _garaExclusionAthDelta.get(atletaId);
  if (!d) { d = { punti: 0, gare: 0, vittorie: 0, p1: 0, p2: 0, p3: 0, pout: 0 }; _garaExclusionAthDelta.set(atletaId, d); }
  d.punti += r.punti_effettivi || 0;
  d.gare  += 1;
  const pos = r.posizione;
  if (pos === 1) { d.vittorie++; d.p1++; }
  else if (pos === 2) d.p2++;
  else if (pos === 3) d.p3++;
  else if (pos >= 4 && pos <= 10) d.pout++;
}

// Filtra in-place calendar/resultsRaw/athletes rimuovendo le gare escluse e
// ricalcolando punti_totali degli atleti coinvolti. Va chiamata PRIMA di
// processLoadedData, che copia risultati/punti_totali di athletes.json così
// come sono (non li ricalcola da resultsRaw).
function sanitizeExcludedGare(calendar, resultsRaw, athletes, excludedIds) {
  _garaExclusionAthDelta = new Map();
  if (!excludedIds || !excludedIds.size) return { calendar, resultsRaw, athletes };

  const filteredCalendar = Array.isArray(calendar) ? calendar.filter(e => !excludedIds.has(e.id)) : calendar;
  const filteredResultsRaw = Array.isArray(resultsRaw) ? resultsRaw.filter(r => !excludedIds.has(r.gara_id)) : resultsRaw;

  if (athletes) {
    for (const id in athletes) {
      const ath = athletes[id];
      if (!ath || !Array.isArray(ath.risultati) || !ath.risultati.length) continue;
      let changed = false;
      const kept = ath.risultati.filter(r => {
        if (!excludedIds.has(r.gara_id)) return true;
        _addExclusionDelta(id, r);
        changed = true;
        return false;
      });
      if (changed) {
        ath.risultati = kept;
        ath.punti_totali = kept.reduce((s, x) => s + (x.punti_effettivi || 0), 0);
      }
    }
  }

  return { calendar: filteredCalendar, resultsRaw: filteredResultsRaw, athletes };
}

// Correzioni manuali a singoli campi di una gara (es. regione sbagliata nei
// dati FCI sorgente: capita quando la federazione tiene un record separato
// per ogni categoria della stessa manifestazione e la regione viene
// inserita male solo su una sotto-gara — la stessa gara "vera" può quindi
// avere regioni diverse a seconda della categoria). new_value viaggia
// sempre come stringa (stessa tabella/route delle esclusioni); i campi
// numerici (km) restano stringa qui e vengono interpretati dove servono.
let _garaCorrectionsPromise = null;
async function getGaraCorrections() {
  if (!_garaCorrectionsPromise) {
    _garaCorrectionsPromise = (async () => {
      try {
        const r = await fetch(`${API_BASE}/gara-overrides/corrections`);
        if (!r.ok) throw new Error('HTTP ' + r.status);
        const d = await r.json();
        return d.corrections || {};
      } catch (e) {
        console.warn('getGaraCorrections:', e);
        return {};
      }
    })();
  }
  return _garaCorrectionsPromise;
}

// Campi noti applicabili: 'nome' → nome_gara/gara, 'cat' → categoria,
// gli altri hanno lo stesso nome sia lato correzione che lato dato grezzo.
const _GARA_FIELD_ALIASES = { nome: ['nome_gara', 'gara'], cat: ['categoria', 'cat'] };
function _applyGaraCorrection(row, fields) {
  for (const [field, value] of Object.entries(fields)) {
    const targets = _GARA_FIELD_ALIASES[field] || [field];
    for (const t of targets) if (t in row) row[t] = value;
  }
}

function applyGaraCorrections(calendar, resultsRaw, athletes, corrections) {
  if (!corrections || !Object.keys(corrections).length) return;
  if (Array.isArray(calendar)) {
    for (const e of calendar) if (corrections[e.id]) _applyGaraCorrection(e, corrections[e.id]);
  }
  if (Array.isArray(resultsRaw)) {
    for (const r of resultsRaw) if (r.gara_id && corrections[r.gara_id]) _applyGaraCorrection(r, corrections[r.gara_id]);
  }
  if (athletes) {
    for (const id in athletes) {
      const risultati = athletes[id]?.risultati;
      if (!Array.isArray(risultati)) continue;
      for (const r of risultati) if (r.gara_id && corrections[r.gara_id]) _applyGaraCorrection(r, corrections[r.gara_id]);
    }
  }
}

// Correzioni manuali a UNA SINGOLA riga risultato (non a tutta la gara):
// serve quando la FCI mischia categorie/generi diversi nella stessa pagina
// e solo un atleta specifico risulta scrapato nel posto sbagliato (es.
// un'Allieva finita per errore tra i risultati Esordienti 2° Anno maschile
// di quella singola gara) — correggere per gara_id cambierebbe anche gli
// altri atleti correttamente scrapati nella stessa gara, quindi qui si
// aggancia per "atleta_id|data" invece che per gara_id.
let _risultatoCorrectionsPromise = null;
async function getRisultatoCorrections() {
  if (!_risultatoCorrectionsPromise) {
    _risultatoCorrectionsPromise = (async () => {
      try {
        const r = await fetch(`${API_BASE}/risultato-overrides/corrections`);
        if (!r.ok) throw new Error('HTTP ' + r.status);
        const d = await r.json();
        return d.corrections || {};
      } catch (e) {
        console.warn('getRisultatoCorrections:', e);
        return {};
      }
    })();
  }
  return _risultatoCorrectionsPromise;
}

function applyRisultatoCorrections(resultsRaw, athletes, corrections) {
  if (!corrections || !Object.keys(corrections).length) return;
  if (Array.isArray(resultsRaw)) {
    for (const r of resultsRaw) {
      const key = `${r.atleta_id}|${r.data}`;
      if (corrections[key]) _applyGaraCorrection(r, corrections[key]);
    }
  }
  if (athletes) {
    for (const id in athletes) {
      const risultati = athletes[id]?.risultati;
      if (!Array.isArray(risultati)) continue;
      for (const r of risultati) {
        const key = `${id}|${r.data}`;
        if (corrections[key]) _applyGaraCorrection(r, corrections[key]);
      }
    }
  }
}

// Correzione manuale del nome team dal pannello admin ("Modifica team").
// L'override finiva salvato in entity_overrides ma nessuna pagina lo
// rileggeva mai: il team restava sempre col nome grezzo di teams.json
// (rigenerato ogni 30 min dallo scraper FCI). Applicata subito dopo il
// caricamento dati, su tutte le strutture dove il nome team compare come
// stringa libera — non solo teams[id].nome — altrimenti classifiche e
// risultati per riga mostrerebbero comunque il nome vecchio.
let _teamNomeCorrectionsPromise = null;
async function getTeamNomeCorrections() {
  if (!_teamNomeCorrectionsPromise) {
    _teamNomeCorrectionsPromise = (async () => {
      try {
        const r = await fetch(`${API_BASE}/team-overrides/corrections`);
        if (!r.ok) throw new Error('HTTP ' + r.status);
        const d = await r.json();
        return d.corrections || {};
      } catch (e) {
        console.warn('getTeamNomeCorrections:', e);
        return {};
      }
    })();
  }
  return _teamNomeCorrectionsPromise;
}

function applyTeamNomeCorrections(teams, resultsRaw, athletes, corrections) {
  if (!corrections || !Object.keys(corrections).length) return;
  if (teams) {
    for (const tid in corrections) if (teams[tid]) teams[tid].nome = corrections[tid];
  }
  if (Array.isArray(resultsRaw)) {
    for (const r of resultsRaw) if (r.team_id && corrections[r.team_id]) r.team = corrections[r.team_id];
  }
  if (athletes) {
    for (const id in athletes) {
      const a = athletes[id];
      if (a?.team_id && corrections[a.team_id]) a.team_attuale = corrections[a.team_id];
      if (Array.isArray(a?.risultati)) {
        for (const r of a.risultati) if (r.team && a.team_id && corrections[a.team_id]) r.team = corrections[a.team_id];
      }
    }
  }
}

// Correzioni genere/categoria per atlete classificate erroneamente. Capita
// soprattutto in gare Esordienti/Allievi "promiscue" (uomini e donne nella
// stessa classifica FCI): tutta la gara viene scrapata con un unico
// genere/categoria, quindi le atlete finiscono segnate come uomini in quella
// riga anche se altrove (altre gare) risultano correttamente donne.
const ATHLETE_GENDER_FIXES = {
  'ANDREOLI_ALICE':       { genere:'F', categoria:'ES1_F' },
  'DELOGU_GIULIA':        { genere:'F', categoria:'ES2_F' },
  'RENZULLI_GIULIA':      { genere:'F', categoria:'ES1_F' },
  'ABRIONI_ALESSIA':      { genere:'F', categoria:'ES1_F' },
  'CINQUEGRANI_FEDERICA': { genere:'F', categoria:'ES1_F' },
  'POIDOMANI_ELENA':      { genere:'F', categoria:'ES1_F' },
  'FONTANA_GIULIA_MARIA': { genere:'F', categoria:'ES1_F' },
  'SGROI_GIADA':          { genere:'F', categoria:'ES1_F' },
  'DI_PARDO_BEATRICE':    { genere:'F', categoria:'ES1_F' },
  'MANNELLI_MATILDE':     { genere:'F', categoria:'ES1_F' },
  'NARDELLI_GIORGIA':     { genere:'F', categoria:'ES1_F' },
  'LOMBARDI_ELEONORA':    { genere:'F', categoria:'ES1_F' },
  'SFERRAGATTA_EMANUELA': { genere:'F', categoria:'ES2_F' },
  'CIANTI_NOEMI':         { genere:'F', categoria:'ES1_F' },
  'PODDA_MATILDE':        { genere:'F', categoria:'ES1_F' },
  'RICCIARDI_ELISABETTA': { genere:'F', categoria:'AL_F' },
  'BALESTRA_MELISSA':     { genere:'F', categoria:'AL_F' },
  'GEROLI_MAIRA':         { genere:'F', categoria:'ES2_F' },
  'VOLLERO_SUSANNA':      { genere:'F', categoria:'ES1_F' },
  'CANCEDDA_SORAYA':      { genere:'F', categoria:'AL_F' },
};

// ── Cognomi composti ──────────────────────────────────────────────
// Lo scraper FCI a volte spezza i cognomi composti mettendo solo la
// particella in `cognome` e il resto in `nome` (es. cognome="DI",
// nome="PARDO BEATRICE"). Nel profilo/team il problema non si vede perché
// cognome+nome vengono concatenati, ma in tutte le altre funzioni che
// mostrano solo il cognome compare "DI". Qui ricostruiamo il cognome.
const SURNAME_PARTICLES = new Set([
  'DI','DE','DA','DEL','DELL','DELLA','DELLE','DELLO','DELLI','DEI','DEGLI',
  'DAL','DALL','DALLA','DALLE','DALLO','DAGLI','DALLI','LO','LA','LE','LI',
  'DU','DES','SAN','SANTA','SANTO','SANT','MC','MAC','VAN','VON','DER','TEN','TER'
]);
function fixCompoundSurname(cognome, nome) {
  let c = (cognome == null ? '' : String(cognome)).trim();
  let n = (nome    == null ? '' : String(nome)).trim();
  if (!c || !n) return { cognome: c, nome: n };
  const cWords = c.split(/\s+/);
  const nWords = n.split(/\s+/);
  const isParticle = w => SURNAME_PARTICLES.has(w.replace(/['’]/g, '').toUpperCase());
  let guard = 0;
  // Finché il "cognome" è composto SOLO da particelle, sposta la prima
  // parola del nome dentro al cognome (lasciando almeno una parola al nome).
  while (nWords.length >= 2 && cWords.every(isParticle) && guard < 4) {
    cWords.push(nWords.shift());
    guard++;
  }
  return { cognome: cWords.join(' '), nome: nWords.join(' ') };
}

// Chiamate dirette a Render (senza un file statico equivalente nel repo da
// usare come fallback, a differenza di /videos che ha data/videos.json):
// timeout breve + valore vuoto come fallback, così un cold-start di Render
// (anche 10-15s sul piano gratuito) non blocca l'intero avvio dell'app —
// vedi _scheduleBackendRetry per il riallineamento in background.
function _apiCallWithTimeout(path, timeoutMs, fallbackValue) {
  return (async () => {
    try {
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), timeoutMs);
      const r = await fetch(`${API_BASE}${path}`, { signal: ctrl.signal });
      clearTimeout(timer);
      if (!r.ok) throw new Error('status ' + r.status);
      return await r.json();
    } catch {
      _scheduleBackendRetry();
      return fallbackValue;
    }
  })();
}
let _pendingBackendRetry = false;
function _scheduleBackendRetry() {
  if (_pendingBackendRetry) return;
  _pendingBackendRetry = true;
  // Render si sveglia in genere entro 10-15s dal primo hit "a freddo": riprova
  // l'intero caricamento in background (l'utente vede già la pagina coi dati
  // core, niente attesa) e sostituisce silenziosamente globalData quando
  // pronto — stesso pattern già usato dall'auto-polling su meta.json.
  setTimeout(async () => {
    try {
      globalData = await loadAll();
      updateMetaUI();
      route();
      console.log('[loadAll] dati extra aggiornati dopo wake-up Render');
    } catch (e) { console.warn('[loadAll] retry fallito:', e); }
    finally { _pendingBackendRetry = false; }
  }, 9000);
}

// Preload tutto in parallelo
async function loadAll() {
  _pcsRosterRetried = false;   // permetti un nuovo tentativo on-demand dopo ogni load
  // Strategia video:
  // 1. In locale → file statico (immediato)
  // 2. In produzione → prova l'API Render con timeout 5s
  //    Se Render è in sleep (free tier) → fallback al file statico nel repo
  //    Dopo il caricamento iniziale, riprova in background e aggiorna globalData
  const videosPromise = IS_LOCAL
    ? loadJson('data/videos.json')
    : (async () => {
        try {
          const ctrl = new AbortController();
          const timer = setTimeout(() => ctrl.abort(), 5000); // 5s timeout
          const r = await fetch(`${API_BASE}/videos`, { signal: ctrl.signal });
          clearTimeout(timer);
          if (!r.ok) throw new Error('status ' + r.status);
          return await r.json();
        } catch {
          // Render in sleep o irraggiungibile: usa il file statico come fallback
          const fallback = await loadJson('data/videos.json');
          // Riprova in background dopo 8s (Render si sveglia in ~10-15s)
          setTimeout(async () => {
            try {
              const r2 = await fetch(`${API_BASE}/videos`);
              if (!r2.ok) return;
              const fresh = await r2.json();
              if (globalData) {
                globalData.videos = fresh;
                console.log('[videos] aggiornati da API dopo wake-up Render');
              }
            } catch { /* ignora */ }
          }, 8000);
          return fallback || {};
        }
      })();

  const [calendarRaw, resultsRawRaw, athletesRaw, teams, meta, raceDetails, videos, extraRoster, pcsExtraRoster, manualAthletesRoster, atletaTeamOv, manualResults, excludedGaraIds, garaCorrections, teamNomeCorrections, risultatoCorrections] = await Promise.all([
    loadJson('data/calendar.json'),
    loadJson('data/results_raw.json'),
    loadJson('data/athletes.json'),
    loadJson('data/teams.json'),
    loadJson('data/meta.json'),
    loadJson('data/race_details.json'),
    videosPromise,
    loadJson('data/extra_roster.json').catch(() => ({})),
    IS_LOCAL ? apiCall('/data/pcs-extra-roster').catch(() => ({}))     : _apiCallWithTimeout('/data/pcs-extra-roster', 4000, {}),
    // Corridori aggiunti da un team o auto-registrati senza corrispondenza FCI
    // (vedi POST /api/team/add-athlete e /api/profile/link-athlete) — stessa
    // forma di pcs-extra-roster, unito allo stesso modo sotto.
    IS_LOCAL ? apiCall('/data/manual-athletes').catch(() => ({}))      : _apiCallWithTimeout('/data/manual-athletes', 4000, {}),
    IS_LOCAL ? apiCall('/data/atleta-team-overrides').catch(() => ({})) : _apiCallWithTimeout('/data/atleta-team-overrides', 4000, {}),
    IS_LOCAL ? apiCall('/data/manual-results').catch(() => [])         : _apiCallWithTimeout('/data/manual-results', 4000, []),
    getExcludedGaraIds(),
    getGaraCorrections(),
    getTeamNomeCorrections(),
    getRisultatoCorrections(),
  ]);
  const { calendar, resultsRaw, athletes } = sanitizeExcludedGare(calendarRaw, resultsRawRaw, athletesRaw, excludedGaraIds);
  applyGaraCorrections(calendar, resultsRaw, athletes, garaCorrections);
  applyRisultatoCorrections(resultsRaw, athletes, risultatoCorrections);
  applyTeamNomeCorrections(teams, resultsRaw, athletes, teamNomeCorrections);

  // Unisci extra_roster statico con atleti PCS da Supabase. Il roster LIVE
  // (Supabase, via /data/pcs-extra-roster) è sempre più aggiornato del file
  // statico extra_roster.json — quest'ultimo si scrive solo alla PRIMA
  // creazione del profilo e poi resta congelato, anche dopo una correzione
  // (categoria/genere sbagliati sistemati a mano, cambio squadra…). La
  // versione precedente di questo merge dava sempre la precedenza al file
  // statico quando un atleta compariva in entrambi sotto lo stesso team,
  // scartando silenziosamente ogni correzione fatta lato Supabase — e se
  // l'atleta nel frattempo era stato spostato in un ALTRO team, restava
  // pure duplicato sotto due squadre diverse. Qui si esclude dal roster
  // statico ogni atleta già noto al roster live (ovunque si trovi), poi si
  // sovrappone il roster live: la versione corretta vince sempre.
  const liveAthleteIds = new Set();
  for (const bucket of Object.values(pcsExtraRoster || {})) {
    for (const a of (bucket.atleti || [])) if (a.atleta_id) liveAthleteIds.add(a.atleta_id);
  }
  for (const bucket of Object.values(manualAthletesRoster || {})) {
    for (const a of (bucket.atleti || [])) if (a.atleta_id) liveAthleteIds.add(a.atleta_id);
  }
  const mergedExtraRoster = {};
  for (const [tid, bucket] of Object.entries(extraRoster || {})) {
    const filteredAtleti = (bucket.atleti || []).filter(a => !liveAthleteIds.has(a.atleta_id));
    mergedExtraRoster[tid] = { ...bucket, atleti: filteredAtleti };
  }
  // Corridori aggiunti da un team/auto-registrati (manualAthletesRoster) si
  // uniscono come il roster PCS live — stessa forma, stessa logica.
  for (const [tid, bucket] of Object.entries({ ...pcsExtraRoster, ...manualAthletesRoster })) {
    const combinedAtleti = [
      ...((pcsExtraRoster?.[tid]?.atleti) || []),
      ...((manualAthletesRoster?.[tid]?.atleti) || []),
    ];
    mergedExtraRoster[tid] = mergedExtraRoster[tid]
      ? { ...mergedExtraRoster[tid], nome: bucket.nome || mergedExtraRoster[tid].nome, atleti: [...mergedExtraRoster[tid].atleti, ...combinedAtleti] }
      : { ...bucket, atleti: combinedAtleti };
  }

  // Scarta le righe manuali "superate": l'admin le inserisce PRIMA che lo
  // scraper FCI pubblichi il risultato reale, usando il gara_id del calendario
  // (senza suffisso categoria/genere). Quando lo scraper passa, crea una riga
  // reale con un gara_id diverso (suffissato) per lo stesso atleta nella
  // stessa data — senza questo filtro resterebbero ENTRAMBE le righe e
  // l'atleta/team risulterebbe con il risultato duplicato. Il confronto è su
  // (atleta_id, data) e non sul gara_id esatto proprio per questo motivo.
  const _realManualKeys = new Set((resultsRaw || []).filter(r => r.atleta_id && r.data).map(r => `${r.atleta_id}|${r.data}`));
  let activeManualResults = (manualResults || []).filter(r => !(r.atleta_id && r.data && _realManualKeys.has(`${r.atleta_id}|${r.data}`)));

  // tipo:'pista' (pista vera/velodromo) è ancora in lavorazione (classificatore
  // eventi/import incompleto) — visibile ovunque (risultati, profili, future
  // classifiche) SOLO per l'admin finché non è a posto, ma il database
  // continua a popolarsi normalmente per tutti: filtro solo qui, un unico
  // punto, non sul lato server, così quando sarà pronta basta togliere
  // questo blocco per renderla pubblica senza toccare altro.
  if (authUser()?.role !== 'admin') {
    activeManualResults = activeManualResults.filter(r => r.tipo !== 'pista');
  }

  // I risultati manuali vanno uniti PRIMA di processLoadedData: quella funzione
  // calcola anche il rank_dopo_gara (classifica) scorrendo resultsRaw una volta
  // sola. Se il merge avvenisse dopo, le righe manuali non passerebbero mai da
  // quel calcolo e resterebbero senza posizione in classifica.
  const mergedResultsRaw = _mergeManualIntoRaw(resultsRaw, activeManualResults);

  const gd = processLoadedData({ calendar, resultsRaw: mergedResultsRaw, athletes, teams, meta, raceDetails, videos, extraRoster: mergedExtraRoster });
  // Aggiorna le schede atleta/team coi risultati manuali PRIMA dell'override di
  // team: _applyAtletaTeamOverrides sposta i risultati già presenti nella scheda
  // del team vecchio a quella del nuovo. Se girasse prima, per un atleta appena
  // creato da un risultato manuale non ci sarebbe ancora nessun risultato da
  // spostare (il cambio-team sembrerebbe applicato sul profilo ma il risultato
  // resterebbe agganciato al team originale nella pagina team).
  _applyManualResults(gd, activeManualResults);
  // Applica gli override manuali di team agli atleti FCI (sposta atleta + risultati nel team scelto)
  _applyAtletaTeamOverrides(gd, atletaTeamOv);
  return gd;
}

// Unisce i risultati manuali (admin) dentro l'array raw dei risultati, PRIMA che
// processLoadedData lo elabori: se esiste già una riga scrapata con la stessa
// (gara_id, posizione) viene sostituita (correzione), altrimenti la riga manuale
// viene aggiunta (nuovo corridore non ancora scrapato).
function _mergeManualIntoRaw(resultsRaw, manualResults) {
  if (!Array.isArray(manualResults) || !manualResults.length) return resultsRaw || [];
  const byKey = new Map();
  for (const r of manualResults) byKey.set(`${r.gara_id}|${r.posizione}`, r);
  const merged = (resultsRaw || []).filter(r => !byKey.has(`${r.gara_id}|${r.posizione}`));
  for (const r of manualResults) {
    merged.push({
      gara_id: r.gara_id, nome_gara: r.nome_gara || '', data: r.data || '',
      categoria: r.categoria || '', genere: r.genere || '', tipo: r.tipo || 'regionale',
      moltiplicatore: r.moltiplicatore || 1,
      campionato_regionale: !!r.campionato_regionale, campionato_italiano: !!r.campionato_italiano,
      regione: r.regione || '', posizione: r.posizione, cognome: r.cognome, nome: r.nome || '',
      atleta_id: r.atleta_id, team: r.team || '', team_id: r.team_id || '',
      tempo: r.tempo || '', km: r.km || '', media: r.media || '',
      punti_base: r.punti_base || 0, punti_effettivi: r.punti_effettivi || 0,
      _manual: true, _manualId: r.id,
    });
  }
  return merged;
}

// Aggiorna le schede atleta/team coi risultati manuali (admin). resultsRaw è
// già stato unito PRIMA di processLoadedData (vedi _mergeManualIntoRaw) così il
// rank_dopo_gara/gli indici sono corretti; qui invece si aggiornano
// athletes.json/teams.json IN MEMORIA, che hanno risultati/punti PRE-CALCOLATI
// dallo scraper Python — un atleta con risultati solo in resultsRaw non compare
// nella sua scheda profilo o in quella del team senza aggiornare anche .risultati qui.
function _applyManualResults(gd, manualResults) {
  if (!gd || !Array.isArray(manualResults) || !manualResults.length) return;
  for (const r of manualResults) {
    const row = {
      gara_id: r.gara_id, nome_gara: r.nome_gara || '', data: r.data || '',
      categoria: r.categoria || '', genere: r.genere || '', tipo: r.tipo || 'regionale',
      moltiplicatore: r.moltiplicatore || 1,
      campionato_regionale: !!r.campionato_regionale, campionato_italiano: !!r.campionato_italiano,
      regione: r.regione || '', posizione: r.posizione, cognome: r.cognome, nome: r.nome || '',
      atleta_id: r.atleta_id, team: r.team || '', team_id: r.team_id || '',
      tempo: r.tempo || '', km: r.km || '', media: r.media || '',
      punti_base: r.punti_base || 0, punti_effettivi: r.punti_effettivi || 0,
      _manual: true, _manualId: r.id,
    };
    _patchAthleteTeamForManualRow(gd, row);
  }
}

// Applica UNA riga manuale alle schede atleta/team in memoria (crea l'atleta/team
// se mancano, aggiorna la lista risultati e il totale punti). Condiviso fra il
// caricamento iniziale (_applyManualResults) e il patch locale dopo un submit
// dal form (_mrPatchLocal), così un atleta appena aggiunto ha subito la scheda
// popolata senza dover ricaricare tutta la pagina.
function _patchAthleteTeamForManualRow(gd, row) {
  if (!gd) return;
  // Riga "solo squadra" (gara a squadre corretta a livello di posizione/team
  // prima — o senza — indicare i singoli corridori): niente atleta_id, quindi
  // nessuna scheda atleta va creata. Il risultato conta SOLO per il team,
  // sotto: niente early-return come prima, che saltava anche quella parte.
  const hasAthlete = !!row.atleta_id;

  let ath = hasAthlete ? gd.athletes[row.atleta_id] : null;
  if (hasAthlete && !ath) {
    ath = gd.athletes[row.atleta_id] = {
      atleta_id: row.atleta_id, nome: row.nome, cognome: row.cognome,
      team_attuale: row.team, team_id: row.team_id,
      categoria: row.categoria, genere: row.genere,
      punti_totali: 0, risultati: [], roster_only: true,
    };
  }
  // Il team a cui attribuire il risultato è quello ATTUALE dell'atleta (che può
  // già riflettere un override applicato prima che questo risultato esistesse,
  // es. un profilo PCS risolto da _resolvePcsAthlete lato server), non quello
  // grezzo salvato sulla riga manuale — altrimenti un risultato aggiunto DOPO un
  // cambio-team finirebbe comunque sotto il team originale (es. la squadra
  // regionale di un campionato) invece che sotto il club vero dell'atleta.
  const targetTeamId   = (ath && ath.team_id)      || row.team_id;
  const targetTeamNome = (ath && ath.team_attuale) || row.team;

  const athEntry = {
    gara_id: row.gara_id, nome_gara: row.nome_gara, data: row.data, posizione: row.posizione,
    punti_effettivi: row.punti_effettivi, team: targetTeamNome, moltiplicatore: row.moltiplicatore,
    tipo: row.tipo, regione: row.regione, km: row.km, media: row.media,
  };
  if (hasAthlete) {
    if (!Array.isArray(ath.risultati)) ath.risultati = [];
    ath.risultati = ath.risultati.filter(x => x.gara_id !== row.gara_id); // rimuovi eventuale versione precedente
    ath.risultati.push(athEntry);
    // tipo 'pista' (velodromo) ha una classifica a sé: non entra nel totale
    // stagione mostrato in testa al profilo, che resta solo "strada".
    ath.punti_totali = (ath.risultati || []).reduce((s, x) => s + (x.tipo === 'pista' ? 0 : (x.punti_effettivi || 0)), 0);
  }

  // Scheda team: stesso trattamento, così risultati/punti/roster restano coerenti
  if (targetTeamId) {
    let team = gd.teams[targetTeamId];
    if (!team) team = gd.teams[targetTeamId] = { id: targetTeamId, nome: targetTeamNome || targetTeamId, atleti: [], risultati: [], punti_totali: 0 };
    if (!Array.isArray(team.atleti)) team.atleti = [];
    if (row.atleta_id && !team.atleti.includes(row.atleta_id)) team.atleti.push(row.atleta_id);
    if (!Array.isArray(team.risultati)) team.risultati = [];
    // Rimuove: (a) l'eventuale riga precedente di QUESTO stesso corridore per
    // questa gara (la stiamo aggiornando), oppure — per una riga "solo
    // squadra" senza atleta_id — (b) la riga fittizia originale dello
    // scraper alla stessa posizione (il "finto atleta" col nome squadra
    // spezzato) e (c) un eventuale placeholder "solo squadra" precedente
    // alla stessa posizione, MA senza toccare i corridori reali già
    // aggiunti a quella posizione (hanno un proprio atleta_id).
    team.risultati = team.risultati.filter(x => {
      if (x.gara_id !== row.gara_id) return true;
      if (row.atleta_id) return x.atleta_id !== row.atleta_id;
      if (x.posizione !== row.posizione) return true;
      return !!(x.atleta_id && x._manual); // tieni solo i corridori veri già inseriti
    });
    // I risultati team "veri" (da teams.json, scraper) usano atleta_cognome/
    // atleta_nome (vedi renderTeam, che legge r.atleta_cognome/r.atleta_nome) —
    // qui si usava cognome/nome, campi diversi: un risultato manuale mostrava
    // quindi nome atleta vuoto nella tabella "RISULTATI TEAM", facendo
    // sembrare la riga "senza proprietario" e facilmente attribuita per
    // errore all'atleta sbagliato nella riga sopra/sotto.
    team.risultati.push({ ...athEntry, atleta_id: row.atleta_id, atleta_cognome: row.cognome, atleta_nome: row.nome, _manual: true });
    // Il PUNTEGGIO SQUADRA non è la somma dei punti di ogni corridore: nelle
    // gare a squadre (più righe/corridori possono condividere la stessa
    // gara+posizione) il team prende i punti di quella posizione UNA SOLA
    // volta, non una volta per ogni corridore che ha condiviso il risultato
    // — ogni singolo atleta continua comunque a ricevere per intero il
    // proprio punteggio personale (ath.punti_totali sopra, non toccato qui).
    const _seenGaraPos = new Set();
    team.punti_totali = (team.risultati || []).reduce((s, x) => {
      if (x.tipo === 'pista') return s; // classifica pista separata
      const key = `${x.gara_id}|${x.posizione}`;
      if (_seenGaraPos.has(key)) return s;
      _seenGaraPos.add(key);
      return s + (x.punti_effettivi || 0);
    }, 0);
  }
}

// Ricalcola punti_per_cat (punti squadra per categoria, usato dalla classifica
// squadre) dai risultati ATTUALI del team — necessario dopo aver spostato
// risultati tra team via override, altrimenti la classifica squadre resta
// agganciata al vecchio team_id (bug osservato: un team con override che
// unisce due squadre in una aveva risultati/punti_totali corretti ma
// spariva dalla classifica squadre, mentre il vecchio team_id ormai vuoto
// vi restava con punti fantasma).
function _recomputePuntiPerCat(team) {
  const byCat = {};
  for (const r of (team.risultati || [])) {
    const cat = (r.gara_id || '').match(/_([A-Z0-9]+_[MF])$/)?.[1];
    if (!cat) continue;
    byCat[cat] = (byCat[cat] || 0) + (r.punti_effettivi || 0);
  }
  team.punti_per_cat = byCat;
}

// Sposta un atleta (e i suoi risultati) dal vecchio team al nuovo, secondo gli override.
// Aggiorna globalData: atleta.team_id/team_attuale, risultati (team_id/team), roster e
// risultati dei team. Così la pagina team mostra i risultati e i punti sotto il team giusto.
function _applyAtletaTeamOverrides(gd, overrides) {
  if (!gd || !overrides) return;
  for (const [aid, ov] of Object.entries(overrides)) {
    const newTeamId   = (ov.team_id || '').trim();
    const newTeamNome = (ov.team || '').trim();
    if (!newTeamId) continue;
    const ath = gd.athletes?.[aid];
    if (!ath) continue;                 // gli atleti PCS-only sono già gestiti dal roster
    const oldTeamId = ath.team_id || '';
    if (oldTeamId === newTeamId) continue;
    // crea il team nuovo se non esiste
    if (!gd.teams[newTeamId]) {
      gd.teams[newTeamId] = { id: newTeamId, nome: newTeamNome || newTeamId, atleti: [], risultati: [], punti_totali: 0 };
    }
    const newT = gd.teams[newTeamId];
    const newNome = newT.nome || newTeamNome || newTeamId;
    // sposta dal vecchio team
    const oldT = gd.teams[oldTeamId];
    if (!Array.isArray(newT.risultati)) newT.risultati = [];
    if (oldT) {
      if (Array.isArray(oldT.atleti)) oldT.atleti = oldT.atleti.filter(id => id !== aid);
      if (Array.isArray(oldT.risultati)) {
        const moved = oldT.risultati.filter(r => r.atleta_id === aid);
        oldT.risultati = oldT.risultati.filter(r => r.atleta_id !== aid);
        moved.forEach(r => { r.team_id = newTeamId; r.team = newNome; });
        newT.risultati.push(...moved);
        oldT.punti_totali = (oldT.punti_totali || 0) - moved.reduce((s, r) => s + (r.punti_effettivi || 0), 0);
      }
    } else if (Array.isArray(ath.risultati) && ath.risultati.length) {
      // Il "vecchio team" non ha mai avuto una propria scheda (es. il nome di
      // una nazionale/selezione come "UCRAINA": la FCI registra così i
      // risultati di un atleta straniero, ma quel nome non diventa mai un
      // team_id/oggetto team reale) — non c'è nulla da cui "spostare" i
      // risultati, ma esistono già sulla scheda dell'atleta stesso. Li
      // copiamo da lì, invece di lasciarli per sempre assenti dai punti
      // stagionali e dalla tabella risultati del vero club assegnato a mano.
      for (const r of ath.risultati) {
        if (newT.risultati.some(x => x.gara_id === r.gara_id && x.atleta_id === aid)) continue;
        newT.risultati.push({
          gara_id: r.gara_id, nome_gara: r.nome_gara, data: r.data, posizione: r.posizione,
          punti_effettivi: r.punti_effettivi, team: newNome, team_id: newTeamId, moltiplicatore: r.moltiplicatore,
          tipo: r.tipo, regione: r.regione, km: r.km, media: r.media,
          atleta_id: aid, atleta_cognome: ath.cognome, atleta_nome: ath.nome,
        });
      }
    }
    newT.punti_totali = newT.risultati.reduce((s, r) => s + (r.punti_effettivi || 0), 0);
    _recomputePuntiPerCat(newT);
    if (oldT) _recomputePuntiPerCat(oldT);
    if (!Array.isArray(newT.atleti)) newT.atleti = [];
    if (!newT.atleti.includes(aid)) newT.atleti.push(aid);
    // riassegna anche le righe in resultsRaw (usate da varie viste, incl. media)
    for (const r of (gd.resultsRaw || [])) {
      if (r.atleta_id === aid) { r.team_id = newTeamId; r.team = newNome; }
    }
    ath.team_attuale = newNome; ath.team_id = newTeamId;
  }
}

// Processa i dati grezzi (stagione live o archivio data/seasons/{anno}/) in un
// oggetto globalData. Riusato sia da loadAll sia dallo switch di stagione, così
// le stagioni passate ricevono ESATTAMENTE lo stesso trattamento (fix genere,
// cognomi composti, rank_dopo_gara, indici, garaToCalId, merge roster).
function processLoadedData({ calendar, resultsRaw, athletes, teams, meta, raceDetails, videos, extraRoster }) {

  // Applica correzioni genere
  if (athletes) {
    for (const [id, fix] of Object.entries(ATHLETE_GENDER_FIXES)) {
      if (athletes[id]) Object.assign(athletes[id], fix);
    }
    // Ricostruisci i cognomi composti spezzati dallo scraper.
    for (const id in athletes) {
      const ath = athletes[id];
      if (!ath) continue;
      const fixed = fixCompoundSurname(ath.cognome, ath.nome);
      ath.cognome = fixed.cognome;
      ath.nome    = fixed.nome;
    }
  }
  if (resultsRaw) {
    for (const r of resultsRaw) {
      const fix = ATHLETE_GENDER_FIXES[r.atleta_id];
      if (fix) { r.genere = fix.genere; if (r.categoria?.endsWith('_M')) r.categoria = r.categoria.replace('_M','_F'); }
    }
  }

  // ── Split gare "gara unica" con generi misti sotto lo stesso gara_id ──────
  // In alcune gare Esordienti/Allievi uomini e donne corrono insieme; la FCI
  // (e quindi lo scraper) assegna un unico gara_id (suffisso _M) all'intera
  // tabella E marca il genere 'M' per TUTTE le righe, comprese le atlete —
  // spesso senza NESSUN segnale F da cui partire (a differenza di un errore
  // isolato, qui manca proprio il dato). Serve quindi anche un riconoscimento
  // per nome (solo nomi italiani inequivocabilmente femminili) per scovare le
  // atlete che altrimenti resterebbero invisibili come tali.
  const _FEMALE_GIVEN_NAMES = new Set([
    'SOFIA','GIULIA','AURORA','GINEVRA','ALICE','EMMA','GIORGIA','GRETA','BEATRICE','VITTORIA',
    'MATILDE','NICOLE','ANNA','SARA','MARTINA','CHIARA','REBECCA','ALESSIA','BIANCA','CAMILLA',
    'ELENA','LUDOVICA','GAIA','ARIANNA','VIOLA','NOEMI','RACHELE','EMILY','ELISA','CARLOTTA',
    'FEDERICA','ALESSANDRA','ELISABETTA','LUCIA','VALENTINA','SILVIA','FRANCESCA','MARTA','ILARIA',
    'IRENE','SERENA','LAURA','ANGELA','ROBERTA','CRISTINA','SIMONA','PAOLA','MICHELA',
    'BARBARA','DANIELA','ELEONORA','MELISSA','JASMINE','ASIA','DILETTA','MIRIAM','ERIKA','VERONICA',
    'SABRINA','DEBORA','SAMUELA','SAMANTHA','VANESSA','AMBRA','AZZURRA','CELESTE','IRIS','PERLA',
    'STELLA','LUNA','NINA','CECILIA','COSTANZA','DIANA','ILENIA','ISABEL','ISABELLA','KATIA',
    'LETIZIA','LIVIA','MANUELA','MARGHERITA','MARIKA','MIA','NADIA','OTTAVIA','PRISCILLA','RAFFAELLA',
    'ROSA','ROSSELLA','SABINA','SELENE','TANIA','TIZIANA','ZOE','CARMEN','EMANUELA','SORAYA','GIADA',
    'SONIA','MILENA','LOREDANA','GIOIA','LAVINIA','ANITA','EVA','ALMA',
  ]);
  // "MARIA" da sola NON è nell'elenco (usata anche come secondo nome
  // devozionale maschile, es. "GIAN MARIA") — basta che comparse insieme a un
  // altro nome femminile inequivocabile (es. "MARIA VITTORIA") perché quel
  // secondo token venga comunque riconosciuto.
  const _isLikelyFemaleGivenName = (nomeStr) =>
    !!nomeStr && String(nomeStr).toUpperCase().split(/\s+/).some(tok => _FEMALE_GIVEN_NAMES.has(tok));

  // In alcune gare "gara unica" uomini e donne corrono insieme; una donna
  // arrivata davanti a qualche uomo mostrava la sua posizione assoluta invece
  // di essere 1ª nella sua categoria, e gli uomini dietro di lei restavano
  // "spostati" nella loro classifica. Qui si individua il genere effettivo
  // (già corretto sopra da ATHLETE_GENDER_FIXES, oppure dedotto dal nome), si
  // spostano le righe femminili su un gara_id sintetico distinto (suffisso
  // _F) e si riassegna posizione + punti separatamente per genere,
  // mantenendo l'ordine di arrivo relativo originale — così l'intera UI
  // esistente (tab categoria, pagina gara, albo d'oro, classifiche) tratta le
  // due classifiche come gare separate, esattamente come le gare non miste.
  if (resultsRaw) {
    const _byGara = {};
    for (const r of resultsRaw) { if (!r.gara_id) continue; (_byGara[r.gara_id] ||= []).push(r); }
    // Il cognome/nome grezzo scrapato può avere un cognome composto ancora da
    // spezzare (es. "DI" / "LUCIA NICCOLO'" invece di "DI LUCIA" / "NICCOLO'")
    // — la normalizzazione vera avviene più sotto, DOPO questo blocco. Senza
    // ri-applicarla qui prima del controllo nome-femminile, un pezzo di
    // cognome finito nel campo nome (es. "LUCIA", frammento di "DI LUCIA")
    // veniva scambiato per un nome proprio femminile, spostando un atleta
    // uomo in una classifica femminile sintetica con posizione 1 inventata.
    const _effGenere = (r) => {
      if (r.genere === 'F') return 'F';
      const { nome: fixedNome } = fixCompoundSurname(r.cognome, r.nome);
      return _isLikelyFemaleGivenName(fixedNome) ? 'F' : 'M';
    };
    for (const [gid, rows] of Object.entries(_byGara)) {
      if (!/_M$/.test(gid)) continue; // solo gruppi col suffisso maschile condiviso
      if (!rows.some(r => _effGenere(r) === 'F') || !rows.some(r => _effGenere(r) === 'M')) continue; // non misto
      const fGaraId = gid.replace(/_M$/, '_F');
      for (const r of rows) if (_effGenere(r) === 'F') { r.genere = 'F'; r.gara_id = fGaraId; }
      // Riassegna posizione/punti SOLO alle righe con una posizione originale
      // valida (non tocca DNF/DNS o righe senza piazzamento), preservando
      // l'ordine di arrivo relativo originale.
      const ranked = rows.filter(r => Number.isFinite(r.posizione)).sort((a, b) => a.posizione - b.posizione);
      let posM = 0, posF = 0;
      for (const r of ranked) {
        const mult = r.moltiplicatore || 1;
        if (r.genere === 'F') { posF++; r.posizione = posF; r.punti_effettivi = (BASEPTS[posF] || 0) * mult; }
        else                  { posM++; r.posizione = posM; r.punti_effettivi = (BASEPTS[posM] || 0) * mult; }
      }
    }
  }

  // Normalizza cognome/nome in resultsRaw con i dati completi da athletes
  // (già corretti sopra). Per gli atleti non presenti in athletes.json
  // applichiamo comunque la ricostruzione dei cognomi composti.
  if (resultsRaw) {
    for (const r of resultsRaw) {
      const ath = athletes && athletes[r.atleta_id];
      if (ath) {
        if (ath.cognome) r.cognome = ath.cognome;
        if (ath.nome != null) r.nome = ath.nome;
      } else {
        const fixed = fixCompoundSurname(r.cognome, r.nome);
        r.cognome = fixed.cognome;
        r.nome    = fixed.nome;
      }
    }
  }

  // ── Calcolo rank_dopo_gara client-side ────────────────────────
  // Il campo non è scritto dallo scraper, quindi lo calcoliamo qui:
  // per ogni categoria, processiamo i risultati in ordine cronologico,
  // accumuliamo i punti_effettivi e dopo ogni gara assegniamo il rank.
  // Così ogni risultato porta il rank dell'atleta DOPO quella specifica gara.
  if (resultsRaw) {
    // Raggruppa per catCode
    const _byCode = {};
    for (const r of resultsRaw) {
      const code = getRankingFileCode(r);
      if (!code || !r.data || !r.atleta_id) continue;
      if (!_byCode[code]) _byCode[code] = [];
      _byCode[code].push(r);
    }
    for (const catRes of Object.values(_byCode)) {
      // Ordine crescente per data, poi per gara_id (più gare lo stesso giorno)
      catRes.sort((a, b) => a.data.localeCompare(b.data) || (a.gara_id||'').localeCompare(b.gara_id||''));
      const cumPts = {}; // atleta_id → punti cumulati
      let i = 0;
      while (i < catRes.length) {
        // Raggruppa tutti i risultati della stessa gara (stesso gara_id)
        const garaId = catRes[i].gara_id;
        let j = i;
        while (j < catRes.length && catRes[j].gara_id === garaId) j++;
        const raceSlice = catRes.slice(i, j);
        // Accumula punti di questa gara
        for (const r of raceSlice) {
          cumPts[r.atleta_id] = (cumPts[r.atleta_id] || 0) + (r.punti_effettivi || 0);
        }
        // Rank dopo questa gara: sort decrescente per punti cumulati
        const sorted = Object.entries(cumPts).sort(([, a], [, b]) => b - a);
        const rankMap = {};
        sorted.forEach(([id], idx) => { rankMap[id] = idx + 1; });
        // Assegna rank_dopo_gara a tutti i risultati di questa gara
        for (const r of raceSlice) r.rank_dopo_gara = rankMap[r.atleta_id] || null;
        i = j;
      }
    }
  }

  // Indicizzazione per calcolo trend rapidi
  const resultsByAtleta = {};
  const resultsByTeam = {};
  (resultsRaw || []).forEach(r => {
    if (r.atleta_id) {
      if (!resultsByAtleta[r.atleta_id]) resultsByAtleta[r.atleta_id] = [];
      resultsByAtleta[r.atleta_id].push(r);
    }
    if (r.team_id) {
      if (!resultsByTeam[r.team_id]) resultsByTeam[r.team_id] = [];
      resultsByTeam[r.team_id].push(r);
    }
  });
  // Ordina per data decrescente
  Object.values(resultsByAtleta).forEach(list => {
    list.sort((a,b) => (b.data||'').localeCompare(a.data||''));
  });
  Object.values(resultsByTeam).forEach(list => {
    list.sort((a,b) => (b.data||'').localeCompare(a.data||''));
  });

  // Set IDs atlete — usato per filtrare ranking pre-costruiti
  const _femaleIds = new Set((resultsRaw || []).filter(r => r.genere === 'F').map(r => r.atleta_id));

  // Mappa gara_id (risultati) → calendar_id — necessaria perché i gara_id
  // dei risultati hanno suffissi extra rispetto agli id del calendario
  const garaToCalId = {};
  // Conta quante voci di calendario condividono (data, numero di edizione) —
  // usato per bloccare il fallback debole "solo edizione" sotto quando due
  // gare COMPLETAMENTE diverse coincidono per puro caso (es. "53 Trofeo
  // della Liberazione" e "53 Edizione Circuito San Giuseppe", entrambe il
  // 19/4 con edizione "53"): senza questo controllo la seconda gara elaborata
  // sovrascrive il match corretto della prima, rubandole regione e dettagli.
  const _editionDateCount = {};
  for (const cal of (calendar || [])) {
    if (!cal.id || !cal.data) continue;
    const ed = (cal.id.replace(/_\d{4}-\d{2}-\d{2}$/, '').match(/^(\d+)_/) || [])[1];
    if (!ed) continue;
    const k = cal.data + '|' + ed;
    _editionDateCount[k] = (_editionDateCount[k] || 0) + 1;
  }
  // Gare "a tappe" (giri multi-giorno): il calendario ha una sola voce con la
  // data della PRIMA tappa, ma ogni tappa successiva è scrapata con la sua
  // data reale e un suffisso diverso (es. "..._SECONDA_TAPPA_2026-07-17...").
  // Per queste, il confronto sul nome vale su QUALSIASI data (non solo quella
  // di partenza) — altrimenti solo la prima tappa risultava mai collegata al
  // calendario, e un video/diretta caricato in anticipo su una tappa
  // successiva (prima che la FCI pubblichi i risultati) non aveva alcun modo
  // di essere ritrovato. Per le gare normali (un solo giorno) il confronto
  // resta rigorosamente sulla stessa data, per non rischiare falsi
  // incroci fra gare diverse con nomi simili.
  for (const cal of (calendar || [])) {
    if (!cal.id || !cal.data) continue;
    const isStageRace = /tappe/i.test(cal.categoria || '');
    const calBase = cal.id.replace(/_\d{4}-\d{2}-\d{2}$/, '');
    // "ED" (edizione) a volte resta incollato al numero nell'id calendario
    // (es. "4ED_LA_PIERI_ALIGI_..." invece di "4_LA_PIERI_ALIGI_...", come
    // genera lo scraper FCI per i risultati) — senza tollerarlo qui lo strip
    // del prefisso numerico falliva, calNorm2 restava con "4ED_" davanti e
    // non combaciava mai con nessun gara_id scrapato: un video/diretta
    // caricato su quella gara prima dei risultati restava "orfano" per
    // sempre, anche dopo che i risultati venivano pubblicati.
    const calBaseNoEd = calBase.replace(/^\d+(?:ED)?_/i, '');
    const _nm2 = s => s
      .replace(/(?<![A-Z0-9])G_P(?![A-Z0-9])/g,'GRAN_PREMIO')
      .replace(/(?<![A-Z0-9])GP(?![A-Z0-9])/g,'GRAN_PREMIO')
      .replace(/(?<![A-Z0-9])GRANPREMIO(?![A-Z0-9])/g,'GRAN_PREMIO')
      .replace(/(?<![A-Z0-9])M_O(?![A-Z0-9])/g,'MEDAGLIA_ORO')
      .replace(/(?<![A-Z0-9])A_M(?![A-Z0-9])/g,'')
      .replace(/_+/g,'_').replace(/^_|_$/g,'');
    const calNorm2 = _nm2(calBaseNoEd);
    const calEd2   = calBase !== calBaseNoEd ? (calBase.match(/^(\d+)(?:ED)?_/i)||[])[1] : null;
    for (const r of (resultsRaw || [])) {
      if (!r.gara_id) continue;
      if (!isStageRace && r.data !== cal.data) continue;
      if (r.gara_id.startsWith(calBase)) { garaToCalId[r.gara_id] = cal.id; continue; }
      const garaBase = r.gara_id.replace(/^\d+_/,'').replace(/_\d{4}-\d{2}-\d{2}.*$/,'');
      if (garaBase === calBaseNoEd) { garaToCalId[r.gara_id] = cal.id; continue; }
      const garaNorm = _nm2(garaBase);
      if (calNorm2 === garaNorm) { garaToCalId[r.gara_id] = cal.id; continue; }
      if (garaNorm.length >= 8 && calNorm2.startsWith(garaNorm + '_')) { garaToCalId[r.gara_id] = cal.id; continue; }
      // Fallback debole (solo numero di edizione, es. entrambe "62_..."): va
      // bene per le gare normali, dove il filtro data qui sopra ha già
      // escluso ogni altra gara con edizione coincidente per puro caso. Per
      // le gare a tappe quel filtro NON c'è (date diverse per ogni tappa),
      // quindi lo stesso numero di edizione da solo può far incrociare due
      // giri COMPLETAMENTE diversi (es. "62° Valle d'Aosta" vs "62° Giro
      // della Regione Friuli Venezia Giulia") — per queste va escluso.
      const garaEd = (r.gara_id.match(/^(\d+)_/)||[])[1];
      const _edUnique = calEd2 && (_editionDateCount[cal.data + '|' + calEd2] || 0) <= 1;
      if (!isStageRace && _edUnique && garaEd && calEd2 === garaEd) { garaToCalId[r.gara_id] = cal.id; continue; }
      { let i=0; while(i<calNorm2.length&&i<garaNorm.length&&calNorm2[i]===garaNorm[i]) i++;
        if (i>=18 && calNorm2.slice(0,i).endsWith('_')) garaToCalId[r.gara_id] = cal.id; }
    }
  }

  // Video/dirette caricati IN ANTICIPO su una tappa specifica (prima che la
  // FCI pubblichi i risultati di quella tappa, quindi senza ancora un
  // gara_id reale): salvati con chiave sintetica "{calendar_id}::{data
  // tappa}" (vedi window._maddSubmitStageVideo). Appena la tappa viene
  // scrapata, il suo gara_id reale finisce in garaToCalId con la data giusta
  // — qui basta ricopiare il video sotto quel gara_id reale, così tutte le
  // pagine che leggono globalData.videos[gara_id] lo trovano senza bisogno
  // di nessuna modifica altrove.
  if (videos) {
    for (const [realGaraId, calId] of Object.entries(garaToCalId)) {
      const r0 = (resultsRaw || []).find(x => x.gara_id === realGaraId);
      if (!r0 || !r0.data) continue;
      const stageKey = `${calId}::${r0.data}`;
      const stageVideos = videos[stageKey];
      if (!stageVideos || !stageVideos.length) continue;
      videos[realGaraId] = [...(videos[realGaraId] || []), ...stageVideos];
      // Senza questo delete, la chiave sintetica restava nell'oggetto videos
      // anche dopo il merge: la pagina Media itera Object.entries(videos)
      // e mostrava sia la voce "in attesa" (chiave sintetica) sia quella
      // appena ricollegata alla gara reale — un doppione esatto della
      // stessa diretta/video.
      delete videos[stageKey];
    }
  }

  // ── Correzione regione errata sui risultati ────────────────────
  // Lo scraper Python assegna la regione a un risultato tramite fuzzy-match
  // sul NOME della gara contro un elenco di candidati (non per data/id): un
  // nome simile a quello di un'altra gara può quindi "rubare" la regione
  // sbagliata (es. una gara in Toscana segnata come Campania). Il calendario
  // (importato da un Excel curato manualmente) è la fonte più affidabile —
  // qui si allinea la regione dei risultati a quella del calendario ogni
  // volta che esiste una corrispondenza gara_id → calendar id, così tutti i
  // punti dell'app che leggono r.regione (filtri Risultati/Gare/Calendario,
  // badge, mappa) ricevono automaticamente il valore corretto.
  if (resultsRaw) {
    const calById = {};
    for (const cal of (calendar || [])) if (cal.id) calById[cal.id] = cal;
    for (const r of resultsRaw) {
      // Se lo scraper ha già una regione italiana valida (estratta dalla
      // sigla provincia FCI, molto più affidabile del fuzzy-match sul nome
      // gara — vedi scraper/_regions.py), NON sovrascriverla col calendario:
      // un garaToCalId sbagliato (es. due gare diverse con stessa edizione e
      // stessa data, puro caso) altrimenti ruberebbe la regione corretta.
      // Il calendario resta il fallback solo quando lo scraper non è
      // riuscito a determinare una regione reale (gara estera, ecc.).
      if (r.regione && ITALIAN_REGIONS.includes(normalizeRegion(r.regione))) continue;
      const calEntry = calById[garaToCalId[r.gara_id]];
      // normalizeRegion() qui canonicalizza grafie alternative del calendario
      // (es. "VAL D AOSTA" -> "VALLE D AOSTA") così risultati corretti dalla
      // provincia FCI e risultati corretti dal calendario finiscono sempre
      // sotto lo stesso identico valore, senza sdoppiare i filtri.
      if (calEntry && calEntry.regione) r.regione = normalizeRegion(calEntry.regione);
    }
  }

  // ── Merge roster manuali (data/extra_roster.json) ─────────────
  // Aggiunge atleti senza risultati (0 punti) ai team, per dare
  // continuità anche a chi non ha ancora gareggiato o non è nei dati FCI.
  // Non sovrascrive MAI chi esiste già.
  const athletesMerged = athletes ? { ...athletes } : {};
  const teamsMerged    = teams    ? { ...teams }    : {};
  for (const tid in (extraRoster || {})) {
    const entry = extraRoster[tid];
    if (!entry || !Array.isArray(entry.atleti)) continue;
    // Bucket "senza team" (atleta manuale senza team_id): NON va trattato
    // come una squadra reale — raggruppava per sbaglio centinaia di atleti
    // di categorie/fonti diverse sotto un'unica pagina team fasulla e
    // navigabile (bug osservato dal vivo). L'atleta resta comunque visibile
    // col proprio profilo, solo senza team_id/team_attuale assegnato.
    const isSenzaTeam = tid === '_SENZA_TEAM_' || entry.senzaTeam;
    // Crea il team se non esiste (solo per bucket reali)
    if (!isSenzaTeam && !teamsMerged[tid]) {
      teamsMerged[tid] = { id: tid, nome: entry.nome || tid, atleti: [], punti_totali: 0, risultati: [] };
    }
    // Se il team esiste già in ICS, usa il suo nome ufficiale
    const teamNome = isSenzaTeam ? '' : (teamsMerged[tid].nome || entry.nome || tid);
    const teamAtleti = (!isSenzaTeam && Array.isArray(teamsMerged[tid].atleti)) ? [...teamsMerged[tid].atleti] : [];
    for (const p of entry.atleti) {
      if (!p || (!p.cognome && !p.nome)) continue;
      // ID atleta: preferisci quello esplicito, altrimenti genera da cognome+nome
      const aid = p.atleta_id
        ? String(p.atleta_id).toUpperCase()
        : (slug((p.cognome||'') + '_' + (p.nome||'')) || '').toUpperCase();
      if (!aid) continue;
      if (!athletesMerged[aid]) {
        athletesMerged[aid] = {
          atleta_id: aid,
          nome: (p.nome || '').toUpperCase(),
          cognome: (p.cognome || '').toUpperCase(),
          team_attuale: teamNome,
          team_id: isSenzaTeam ? '' : tid,
          categoria: p.categoria || '',
          genere: p.genere || 'M',
          punti_totali: 0,
          risultati: [],
          roster_only: true,
        };
      }
      // Gli atleti importati da ciclismo.info portano il team dell'ULTIMA
      // stagione in cui hanno gareggiato (spesso passata) — vanno nel
      // proprio profilo/nella storia dell'anno giusto (vedi
      // _loadTeamCiclismoStorico), ma non nel roster ATTUALE del team: senza
      // questo filtro chiunque avesse mai corso per quella squadra restava
      // per sempre nella rosa corrente, anche anni dopo aver cambiato team
      // (bug osservato dal vivo sulla Zalf).
      if (!isSenzaTeam && p.fonte !== 'ciclismo_info' && !teamAtleti.includes(aid)) teamAtleti.push(aid);
    }
    if (!isSenzaTeam) teamsMerged[tid].atleti = teamAtleti;
  }

  // ── Team priority: il team con più risultati vince sulle nazionali/selezioni ──
  // Se team_attuale è una nazionale o selezione regionale, sostituiscilo col
  // team reale più frequente tra i risultati dell'atleta.
  for (const aid in athletesMerged) {
    const a = athletesMerged[aid];
    if (!a.risultati?.length) continue;
    let matchedT;
    if (isSelectionTeamName(a.team_attuale)) {
      const teamCounts = {};
      for (const r of a.risultati) {
        if (r.team && !isSelectionTeamName(r.team)) {
          teamCounts[r.team] = (teamCounts[r.team] || 0) + 1;
        }
      }
      const best = Object.entries(teamCounts).sort((x, y) => y[1] - x[1])[0];
      if (!best) continue;
      a.team_attuale = best[0];
      matchedT = Object.values(teamsMerged).find(t => t.nome === best[0]);
      if (matchedT) a.team_id = matchedT.id;
    } else {
      // team_attuale è GIÀ un club reale (assegnato a mano dall'admin,
      // fusione team, roster PCS, ecc.) — ma i risultati grezzi scrapati
      // possono comunque riportare ancora il nome della selezione con cui
      // l'atleta ha gareggiato in quella gara specifica (es. un corridore
      // straniero il cui club reale è stato assegnato dopo, mentre la FCI
      // lo aveva registrato sotto "UCRAINA"/nazionale). Senza questo ramo,
      // quei risultati restavano orfani per sempre: non finivano né nel
      // team selezione (niente pagina) né in quello reale (non c'era più
      // nessun controllo, perché team_attuale non era più una selezione).
      matchedT = teamsMerged[a.team_id];
    }
    if (!matchedT) continue;
    // I risultati ottenuti sotto la selezione (es. "LIGURIA" ai campionati
    // italiani) restano scritti con quel nome squadra nei dati grezzi — il
    // team.risultati del vero club (teams.json, calcolato dallo scraper)
    // non li conterrà MAI, perché lì la gara è attribuita letteralmente a
    // "LIGURIA". Risultato: la vittoria di un atleta compariva sulla SUA
    // pagina (che legge ath.risultati, già corretto sopra) ma non su
    // quella del suo team. Li aggiungiamo qui esplicitamente.
    if (!Array.isArray(matchedT.risultati)) matchedT.risultati = [];
    if (!Array.isArray(matchedT.atleti)) matchedT.atleti = [];
    if (!matchedT.atleti.includes(aid)) matchedT.atleti.push(aid);
    for (const r of a.risultati) {
      if (!r.team || !isSelectionTeamName(r.team)) continue;
      if (matchedT.risultati.some(x => x.gara_id === r.gara_id && x.atleta_id === aid)) continue;
      matchedT.risultati.push({
        gara_id: r.gara_id, nome_gara: r.nome_gara, data: r.data, posizione: r.posizione,
        punti_effettivi: r.punti_effettivi, team: a.team_attuale, moltiplicatore: r.moltiplicatore,
        tipo: r.tipo, regione: r.regione, km: r.km, media: r.media,
        atleta_id: aid, atleta_cognome: a.cognome, atleta_nome: a.nome,
      });
    }
    matchedT.punti_totali = (matchedT.risultati || []).reduce((s, x) => s + (x.punti_effettivi || 0), 0);
  }

  // ── Nessuna pagina team per selezioni/nazionali ────────────────
  // "LOMBARDIA", "LIGURIA", "NAZIONALE ROMANIA", ecc. non sono club reali:
  // sono il nome sotto cui la FCI registra i risultati ai campionati
  // italiani/internazionali. I risultati dei singoli atleti sono già stati
  // ricollegati sopra al loro vero club (o restano comunque visibili sulla
  // pagina dell'atleta anche quando un vero club non è determinabile) — le
  // squadre "selezione" non devono avere una propria pagina /team/.
  for (const tid of Object.keys(teamsMerged)) {
    if (isSelectionTeamName(teamsMerged[tid].nome)) delete teamsMerged[tid];
  }

  return {
    calendar: calendar || [],
    resultsRaw: resultsRaw || [],
    athletes: athletesMerged,
    teams: teamsMerged,
    meta: meta || {},
    raceDetails: raceDetails || {},
    videos: videos || {},
    resultsByAtleta,
    resultsByTeam,
    _femaleIds,
    garaToCalId
  };
}

const RANKING_CODES = [
  'ES1_M','ES2_M','AL_M','JUN_M','ELI_M',
  'ES1_F','ES2_F','AL_F','JUN_F','ELI_F'
];

async function loadRanking(code) {
  const _rbase = activeSeason ? `data/seasons/${activeSeason}/rankings` : 'data/rankings';
  const data = await loadJson(`${_rbase}/${code}.json`) || [];
  // Correggi i cognomi composti spezzati dallo scraper, allineandoli ai
  // dati già normalizzati in athletes (fallback: ricostruzione particelle).
  const athMap = globalData && globalData.athletes;
  for (const a of data) {
    const ath = athMap && athMap[a.atleta_id];
    if (ath) {
      if (ath.cognome) a.cognome = ath.cognome;
      if (ath.nome != null) a.nome = ath.nome;
    } else {
      const fixed = fixCompoundSurname(a.cognome, a.nome);
      a.cognome = fixed.cognome;
      a.nome    = fixed.nome;
    }
  }
  // rankings/*.json è precalcolato indipendentemente da athletes.json (stessa
  // pipeline esterna, stessi punti "sporchi" da gare estere) — sottrai qui il
  // delta già calcolato in sanitizeExcludedGare e riordina/riassegna pos.
  // `data` è l'array in cache di loadJson: guardia contro doppia sottrazione
  // se loadRanking(code) viene chiamata più volte (succede normalmente,
  // es. widget classifica + pagina classifica) sullo stesso array cachato.
  if (_garaExclusionAthDelta.size && !data._exclusionApplied) {
    data._exclusionApplied = true;
    let touched = false;
    for (const a of data) {
      const d = _garaExclusionAthDelta.get(a.atleta_id);
      if (!d) continue;
      touched = true;
      a.punti    = Math.max(0, (a.punti || 0) - d.punti);
      a.gare     = Math.max(0, (a.gare || 0) - d.gare);
      a.vittorie = Math.max(0, (a.vittorie || 0) - d.vittorie);
      a.p1       = Math.max(0, (a.p1 || 0) - d.p1);
      a.p2       = Math.max(0, (a.p2 || 0) - d.p2);
      a.p3       = Math.max(0, (a.p3 || 0) - d.p3);
      a.pout     = Math.max(0, (a.pout || 0) - d.pout);
    }
    if (touched) {
      data.sort((a, b) => (b.punti || 0) - (a.punti || 0));
      data.forEach((a, i) => { a.pos = i + 1; });
    }
  }
  // Protezione: filtra atleti del genere sbagliato (possibile errore scraper)
  if (!globalData) return data;
  const isFemale = code.endsWith('_F');
  const femaleSet = globalData._femaleIds;
  if (!femaleSet) return data;
  return data.filter(a => isFemale ? femaleSet.has(a.atleta_id) : !femaleSet.has(a.atleta_id));
}

async function loadTeamRanking(code) {
  const _tbase = activeSeason ? `data/seasons/${activeSeason}/team_rankings` : 'data/team_rankings';
  const data = await loadJson(`${_tbase}/${code}.json`);
  return data || [];
}

// ── UTILITY ───────────────────────────────────────────────────
function esc(s) {
  if (s == null) return '';
  return String(s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

// ── Home navigation — va all'hub salvato o alla home ─────────────
window.goHome = function(e) {
  if (e) e.preventDefault();
  let target = '/';
  try {
    const saved = localStorage.getItem('itcContext');
    if (saved && HUB_CONFIG[saved]) target = '/hub/' + saved;
  } catch {}
  // navTo() invece di location.hash diretto: se l'URL corrente è già pulito
  // (es. /risultati/JUN_M dopo un cambio categoria), assegnare solo l'hash
  // lascerebbe il vecchio pathname intatto producendo un URL rotto tipo
  // "/risultati/JUN_M#/" invece di navigare davvero alla home.
  navTo(target);
};

// ── Athlete view tracking (Popular Today / Trending) ──────────────
function trackAthleteView(atleta_id, cognome, nome) {
  try {
    const today = new Date().toISOString().split('T')[0];
    const key   = 'itc_views_' + today;
    const views = JSON.parse(localStorage.getItem(key) || '{}');
    if (!views[atleta_id]) views[atleta_id] = { cognome, nome, count: 0 };
    views[atleta_id].count++;
    localStorage.setItem(key, JSON.stringify(views));
    // Pulisci chiavi vecchie (tieni solo ultimi 7gg)
    for (const k of Object.keys(localStorage)) {
      if (k.startsWith('itc_views_') && k !== key) {
        const d = k.replace('itc_views_', '');
        if (d < new Date(Date.now() - 7*86400000).toISOString().split('T')[0])
          localStorage.removeItem(k);
      }
    }
  } catch {}
}

function getPopularAthletes(limit = 10) {
  try {
    const agg = {};
    for (let i = 0; i < 7; i++) {
      const d = new Date(); d.setDate(d.getDate() - i);
      const key = 'itc_views_' + d.toISOString().split('T')[0];
      const views = JSON.parse(localStorage.getItem(key) || '{}');
      for (const [id, v] of Object.entries(views)) {
        if (!agg[id]) agg[id] = { cognome: v.cognome, nome: v.nome, count: 0 };
        agg[id].count += v.count * (i === 0 ? 2 : 1); // oggi vale doppio
      }
    }
    return Object.entries(agg)
      .map(([id, v]) => ({ atleta_id: id, ...v }))
      .sort((a, b) => b.count - a.count)
      .slice(0, limit);
  } catch { return []; }
}

function fmtDate(iso) {
  if (!iso) return '—';
  const [y,m,d] = iso.split('-');
  const months = ['GEN','FEB','MAR','APR','MAG','GIU','LUG','AGO','SET','OTT','NOV','DIC'];
  return `${parseInt(d)} ${months[parseInt(m)-1]} ${y}`;
}

function fmtDateShort(iso) {
  if (!iso) return '—';
  const [,m,d] = iso.split('-');
  const months = ['GEN','FEB','MAR','APR','MAG','GIU','LUG','AGO','SET','OTT','NOV','DIC'];
  return `${parseInt(d)} ${months[parseInt(m)-1]}`;
}

function badgeCat(code) {
  const label = catLabel(code);
  const cls = code.replace(/[^a-zA-Z]/g, '').toLowerCase(); // as a safe class name
  return `<span class="badge-cat badge-${cls}">${esc(label)}</span>`;
}

// Piccola etichetta accanto al NOME della gara nelle liste risultati (non
// solo nella colonna moltiplicatore, spesso lontana o nascosta su mobile):
// l'utente vuole che sia chiaro a colpo d'occhio, leggendo solo il nome
// gara, che si tratta di un "tipo pista" e non di una gara normale.
function tipoPistaTag(tipo) {
  if (tipo !== 'tipo_pista') return '';
  return ' <span class="res-badge gray-badge" style="font-size:.62rem;padding:1px 6px;margin-left:4px;white-space:nowrap;vertical-align:1px">Tipo Pista</span>';
}

// Come tipoPistaTag, ma per i risultati PCS "extra" (gare estere non
// abbinate al circuito) che sono in realtà prove A SQUADRE (cronometro a
// squadre, "TTT"/"Team Time Trial" nel nome PCS, "ploegentijdrit" in
// olandese) — stesso trattamento concettuale del nostro Campionato Italiano
// Cronometro a Squadre: la posizione è del TEAM, non di un singolo, quindi
// più corridori la condividono legittimamente. Va segnalato per non far
// sembrare un errore/doppione quando più compagni hanno lo stesso piazzamento.
function squadreExtraTag(nomeGara) {
  if (!/\bTTT\b|team time trial|a squadre|ploegentijdrit|contre.la.montre.par.équipes/i.test(nomeGara || '')) return '';
  return ' <span class="res-badge gray-badge" style="font-size:.62rem;padding:1px 6px;margin-left:4px;white-space:nowrap;vertical-align:1px">Squadre</span>';
}

function badgeMult(m, tipo, isCR = false, isCI = false) {
  isCR = isCR || (tipo === 'campionato_regionale');
  isCI = isCI || (tipo === 'campionato_italiano');
  const isNat = (m === 2 || tipo === 'nazionale');
  const isInt = (m === 3 || tipo === 'internazionale');

  if (isCI) return `<span class="res-badge blue-badge">Campionato Italiano (x3)</span>`;
  if (isCR) return `<span class="res-badge orange-badge">Campionato Regionale (x2)</span>`;
  // Formati "tipo pista" (criterium in circuito chiuso, stile pista ma su
  // strada): poca partecipazione, non rappresentativi come una gara
  // normale — punteggio dimezzato rispetto allo standard, etichetta
  // separata invece di "Reg.le (x1)" per non farli sembrare gare piene.
  if (tipo === 'tipo_pista') return `<span class="res-badge gray-badge">Tip. Pist. (0,5)</span>`;
  // Pista vera (velodromo): classifica separata dalla strada, etichetta
  // dedicata invece di "Reg.le (x1)" per non farla sembrare una gara strada.
  if (tipo === 'pista') return `<span class="res-badge gray-badge">Pista</span>`;

  const cls = isInt ? 'blue-badge' : (isNat ? 'orange-badge' : 'gray-badge');
  const label = isInt ? 'Int.le' : (isNat ? 'Naz.le' : 'Reg.le');
  return `<span class="res-badge ${cls}">${label} (x${m})</span>`;
}

function catLabel(code) {
  const map = {
    ES_M: 'Esordienti M',
    ES1_M:'Esordienti 1° Anno', 
    ES2_M:'Esordienti 2° Anno', 
    AL_M: 'Allievi', 
    AL1_M:'Allievi 1° Anno', 
    AL2_M:'Allievi 2° Anno',
    JUN_M:'Juniores',        
    ELI_M:'Elite - U23',
    ES_F: 'Donne Esordienti', 
    ES1_F:'Donne Esordienti 1° Anno', 
    ES2_F:'Donne Esordienti 2° Anno', 
    AL_F: 'Donne Allieve', 
    AL1_F:'Donne Allieve 1° Anno', 
    AL2_F:'Donne Allieve 2° Anno',
    JUN_F:'Donne Juniores',      
    ELI_F:'Donne Elite - U23'
  };
  return map[code] || code;
}

function getRankingFileCode(obj) {
  if (!obj) return null;
  if (typeof obj === 'string') {
    if (obj.startsWith('AL')) return 'AL_' + (obj.endsWith('_F') ? 'F' : 'M');
    return obj;
  }
  // r.genere è autorevole — già corretto da ATHLETE_GENDER_FIXES in loadAll()
  // Se genere non è disponibile (es. team results), lo ricaviamo dal suffisso gara_id
  if (obj.gara_id) {
    const m = obj.gara_id.match(/_([A-Z0-9]+)_([MF])$/);
    if (m) {
      let base = m[1];
      if (base.startsWith('AL')) base = 'AL';
      const gender = obj.genere === 'F' ? 'F' : obj.genere === 'M' ? 'M' : m[2];
      // Se questa RIGA è già correttamente femminile ci si fida di lei: la
      // sorgente ora divide per genere le gare "miste" alla radice, per
      // singola gara — un'atleta può correttamente avere categorie diverse
      // in gare diverse (es. passa da 1° a 2° anno a stagione in corso), e
      // sovrascriverla con una categoria fissa uguale per tutte le sue righe
      // (sotto) romperebbe quelle già corrette. Bug reale osservato:
      // RENZULLI_GIULIA forzata a ES1_F anche sulla riga "TROFEO ROSA...
      // SECONDO ANNO", dove il suo gara_id (ES2_F) era già giusto.
      if (gender === 'F') return `${base}_${gender}`;
      // gender è 'M': possibile gara mista non ancora ri-scrapata dopo il
      // fix — ATHLETE_GENDER_FIXES sotto fa da rete di sicurezza SOLO in
      // questo caso (gara_id ancora maschile per una nota atleta donna).
      if (obj.atleta_id && ATHLETE_GENDER_FIXES[obj.atleta_id]) return ATHLETE_GENDER_FIXES[obj.atleta_id].categoria;
      return `${base}_${gender}`;
    }
  }
  if (obj.atleta_id && ATHLETE_GENDER_FIXES[obj.atleta_id]) return ATHLETE_GENDER_FIXES[obj.atleta_id].categoria;
  const gender = obj.genere === 'F' ? 'F' : 'M';
  // Fallback: usa categoria (già corretta al caricamento)
  if (obj.categoria && /^[A-Z0-9]+_[MF]$/.test(obj.categoria)) return obj.categoria;
  return null;
}

// ── Weekend key: returns the Saturday ISO date for Sa+Su grouping ──
function weekendKey(dateStr) {
  const d = new Date(dateStr + 'T00:00:00');
  const day = d.getDay(); // 0=Sun, 6=Sat
  const offset = day === 0 ? -1 : (6 - day);
  const sat = new Date(d);
  sat.setDate(d.getDate() + offset);
  return sat.toISOString().split('T')[0];
}

function renderTrend(r, showNew = true) {
  if (!r) return '';
  const t = r.trend;
  if (t === undefined || t === null) {
    return showNew ? `<span class="trend-indicator trend-new">NEW</span>` : '';
  }
  if (t > 0) return `<span class="trend-indicator trend-up">▲${t}</span>`;
  if (t < 0) return `<span class="trend-indicator trend-down">▼${Math.abs(t)}</span>`;
  return `<span class="trend-indicator trend-stable">●</span>`;
}

function posClass(p) {
  if (p === 1) return 'p1';
  if (p === 2) return 'p2';
  if (p === 3) return 'p3';
  return '';
}

function flameSvg() {
  return `<svg class="flame-svg" viewBox="0 0 14 18" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
    <path d="M7 1C7 1 11 5 11 9C11 11.7614 9.20914 14 7 14C4.79086 14 3 11.7614 3 9C3 7 4 5.5 4 5.5C4 5.5 4.5 8 6 8C6 8 5 6 7 1Z" fill="#e8001d"/>
    <path d="M7 10C7 10 8.5 11.5 8.5 13C8.5 14.3807 7.82843 15.5 7 15.5C6.17157 15.5 5.5 14.3807 5.5 13C5.5 11.5 7 10 7 10Z" fill="#f5c400"/>
  </svg>`;
}

function multFromType(tipo, isCR, isCI) {
  if (isCI || tipo === 'internazionale') return 3;
  if (isCR || tipo === 'nazionale') return 2;
  return 1;
}

// ── ADMIN EDIT SYSTEM ─────────────────────────────────────────
