        '<div class="itc-pk-section">' +
          '<div class="itc-pk-shdr itc-pk-F">&#9792; DONNE</div>' +
          _buildPickerRows('F') +
        '</div>' +
      '</div>' +
      '<button class="itc-pk-all" onclick="window._itcPickCat(null)">Esplora tutto il ciclismo &#8594;</button>' +
    '</div>';

  document.body.appendChild(el);
