// ── SEARCH GLOBALE ────────────────────────────────────────────
window.closeAllSearchDropdowns = () => {
  ['search-results-dropdown','drawer-search-dropdown','m-search-dropdown'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = 'none';
  });
};

function bindSearch(inputId, dropdownId) {
  const input = document.getElementById(inputId);
  const dropdown = document.getElementById(dropdownId);
  if (!input || !dropdown) return;
  let timer;
  input.addEventListener('input', () => {
    clearTimeout(timer);
    timer = setTimeout(() => doSearch(input.value, dropdown), 250);
  });
  input.addEventListener('blur', () => {
    setTimeout(() => { dropdown.style.display = 'none'; }, 200);
  });
}

function initSearch() {
  bindSearch('nav-search', 'search-results-dropdown');
  bindSearch('drawer-search', 'drawer-search-dropdown');
  bindSearch('m-search', 'm-search-dropdown');
}

// Cache profili media per la ricerca
let _mediaProfilesCache = null;
async function _loadMediaProfiles() {
  if (_mediaProfilesCache) return _mediaProfilesCache;
  try {
    const d = await fetch(`${API_BASE}/media/profiles`).then(r => r.json());
    _mediaProfilesCache = d.profiles || [];
  } catch { _mediaProfilesCache = []; }
  return _mediaProfilesCache;
}

// Indice gare (eventi) della stagione caricata, per la ricerca. Una voce per
// edizione (le categorie della stessa gara sono raggruppate). In cache per anno.
let _racesIndexCache = null, _racesIndexYear = null;
function getRacesIndex() {
  const y = _loadedSeasonYear();
  if (_racesIndexCache && _racesIndexYear === y) return _racesIndexCache;
  const map = {};
  for (const r of (globalData.resultsRaw || [])) {
    if (!r.gara_id || !r.nome_gara) continue;
    const ekey = r.gara_id.replace(/_[A-Z0-9]+_[MF]$/, ''); // togli categoria → raggruppa l'edizione
    if (!map[ekey]) {
      map[ekey] = { nome: r.nome_gara, data: r.data || '', regione: r.regione || '', gara_id: r.gara_id, _nl: (r.nome_gara || '').toLowerCase() };
    }
  }
  _racesIndexCache = Object.values(map).sort((a, b) => (b.data || '').localeCompare(a.data || ''));
  _racesIndexYear = y;
  return _racesIndexCache;
}

function doSearch(q, dropdown) {
  if (!dropdown) dropdown = document.getElementById('search-results-dropdown');
  if (!q.trim() || !globalData) {
    dropdown.style.display = 'none';
    return;
  }

  const { athletes, teams } = globalData;
  const ql = q.toLowerCase();
  const results = [];

  // Fuzzy match: ogni token >= 4 chars prova anche senza l'ultima lettera
  // es. "loren" → prova "loren" poi "lore" → trova "lorello"
  function fuzzyIncludes(haystack, queryStr) {
    return queryStr.split(/\s+/).filter(Boolean).every(t => {
      if (haystack.includes(t)) return true;
      return t.length >= 4 && haystack.includes(t.slice(0, -1));
    });
  }

  // Cerca atleti (fuzzy)
  for (const [id, a] of Object.entries(athletes)) {
    const name = `${a.cognome||''} ${a.nome||''}`.toLowerCase();
    if (fuzzyIncludes(name, ql)) {
      results.push({ type: 'atleta', id, display: `${a.cognome} ${a.nome}`, sub: a.team_attuale||'' });
    }
    if (results.length >= 6) break;
  }

  // Cerca team
  for (const [id, t] of Object.entries(teams)) {
    if ((t.nome||'').toLowerCase().includes(ql)) {
      results.push({ type: 'team', id, display: t.nome, sub: `${t.atleti?.length||0} atleti` });
    }
    if (results.length >= 8) break;
  }

  // Cerca gare: una sola voce per NOME gara (niente edizione). Match per token
  // (come il filtro Risultati): basta scrivere una parte qualsiasi del nome.
  const _qTokens = ql.split(/\s+/).filter(Boolean);
  const _seenBase = new Set();
  let _gc = 0;
  for (const ev of getRacesIndex()) {
    const base = _raceBaseName(ev.nome);
    if (!base || _seenBase.has(base)) continue;
    const hay = (base + ' ' + ev.nome + ' ' + (ev.regione || '')).toLowerCase();
    if (_qTokens.every(t => hay.includes(t))) {
      _seenBase.add(base);
      results.push({ type: 'gara', id: ev.gara_id, display: base, sub: '' });
      if (++_gc >= 10) break;
    }
  }

  // Mostra subito quello che abbiamo, poi aggiunge media in async
  const renderDropdown = (list) => {
    if (!list.length) {
      dropdown.innerHTML = '<div class="search-result-item"><span class="search-result-sub">Nessun risultato</span></div>';
    } else {
      dropdown.innerHTML = list.map(r => {
        const lbl = r.type === 'atleta' ? 'ATLETA' : r.type === 'media' ? '📷 FOTOGRAFO' : r.type === 'gara' ? '🏁 GARA' : 'TEAM';
        return `
        <div class="search-result-item" onclick="goTo('#/${r.type === 'media' ? 'media' : r.type}/${encodeURIComponent(r.id)}'); window.closeAllSearchDropdowns()">
          <div>
            <div class="search-result-label">${lbl}</div>
            <div class="search-result-name">${esc(r.display)}</div>
            <div class="search-result-sub">${esc(r.sub)}</div>
          </div>
        </div>`;
      }).join('');
    }
    dropdown.style.display = 'block';
  };

  renderDropdown(results);

  // Arricchisci con fotografer (async, non blocca)
  _loadMediaProfiles().then(profiles => {
    const mediaResults = profiles
      .filter(p => (p.display_name||'').toLowerCase().includes(ql))
      .slice(0, 3)
      .map(p => ({ type: 'media', id: p.id, display: p.display_name, sub: p.bio || 'Fotografo' }));
    if (mediaResults.length) renderDropdown([...results, ...mediaResults]);
  });
}

window.goTo = (hash) => { window.location.hash = hash; };

// ── SELETTORE LINGUA (traduzione automatica Google) ──────────────
// Pilota il widget Google Translate tramite il cookie `googtrans`, così la
// scelta resta persistente tra le pagine. 'it' = lingua originale.
window.setLang = (lang) => {
  lang = lang || 'it';
  try { localStorage.setItem('ics-lang', lang); } catch {}
  // Tieni allineati i due selettori (navbar + drawer)
  ['lang-select', 'lang-select-m'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = lang;
  });
  // Cookie per persistenza tra ricariche/sessioni (host + dominio padre)
  const val = lang === 'it' ? '' : '/it/' + lang;
  const host = location.hostname;
  document.cookie = 'googtrans=' + val + ';path=/';
  if (host && host.indexOf('.') !== -1) {
    document.cookie = 'googtrans=' + val + ';path=/;domain=.' + host;
  }
  // Tornare all'originale (italiano) in modo pulito richiede il reload
  if (lang === 'it') { location.reload(); return; }
  // Altrimenti traduci in-page via il combo nascosto del widget Google:
  // niente reload, niente banner (nascosto via CSS).
  _applyGoogleLang(lang, 0);
};

// Applica la lingua pilotando il <select> nascosto creato dal widget Google.
// Riprova finché il widget non è pronto (caricamento async).
function _applyGoogleLang(lang, tries) {
  tries = tries || 0;
  const combo = document.querySelector('.goog-te-combo');
  if (!combo) {
    if (tries < 30) setTimeout(() => _applyGoogleLang(lang, tries + 1), 300);
    return;
  }
  const target = lang === 'it' ? '' : lang;
  if (combo.value !== target) {
    combo.value = target;
    combo.dispatchEvent(new Event('change'));
  }
}

// Allinea i selettori alla lingua salvata e ri-applica la traduzione al load
function initLang() {
  let lang = 'it';
  try { lang = localStorage.getItem('ics-lang') || 'it'; } catch {}
  ['lang-select', 'lang-select-m'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = lang;
  });
  if (lang && lang !== 'it') _applyGoogleLang(lang, 0);
}

// Rimuove il suffisso categoria (_AL_M, _ES1_F…) per ottenere il calendario ID
function toCalId(garaId) {
  return (garaId || '').replace(/_[A-Z0-9]+_[MF]$/, '');
}

// ── Modal player unificato (YouTube + podcast), con coda per l'avanzamento
// automatico dal più vecchio al più recente ────────────────────────────────
// window._mvCurrentQueueSource: impostato da _loadMediaCreatorArea/
// renderMediaProfile all'elenco video attualmente mostrato (ordine più
// recente→più vecchio, come si vede in pagina) PRIMA di costruire le card,
// così un click su una card sa recuperare tutti i "fratelli" per l'avanzamento
// automatico — costruito qui in ordine INVERTITO (più vecchio→più recente),
// come richiesto per l'ascolto in sequenza.
window._mvCurrentQueueSource = [];
window._mvQueue = [];
window._mvQueueIndex = 0;
let _mvYtMessageListener = null;

function _mvBuildQueueFromSource(clickedId) {
  const src = window._mvCurrentQueueSource || [];
  const oldestFirst = [...src].reverse(); // la lista sorgente è più recente→più vecchio
  const queue = oldestFirst.map(v => {
    const yt = ytId(v.url || '');
    const isPodcast = v.palinsesto === 'podcast' && /\.(mp3|m4a|wav|ogg)(\?|$)/i.test(v.url || '');
    return yt
      ? { id: v.id, kind: 'yt', ytId: yt, title: v.title }
      : isPodcast
        ? { id: v.id, kind: 'podcast', url: v.url, title: v.title, cover: v.thumbnail_url || '' }
        : null;
  }).filter(Boolean);
  const index = queue.findIndex(q => String(q.id) === String(clickedId));
  return { queue, index: index >= 0 ? index : 0 };
}

function _mvModalInnerHtml(item) {
  if (item.kind === 'yt') {
    return `<iframe id="mv-modal-frame" src="https://www.youtube.com/embed/${item.ytId}?autoplay=1&rel=0&enablejsapi=1&origin=${encodeURIComponent(window.location.origin)}"
              frameborder="0" allowfullscreen
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture">
            </iframe>`;
  }
  return `<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;background:var(--bg-elevated);padding:24px;box-sizing:border-box">
    ${item.cover ? `<img src="${esc(item.cover)}" alt="" style="width:180px;height:180px;object-fit:cover;border-radius:14px;box-shadow:0 4px 24px rgba(0,0,0,.35)"/>` : ''}
    <audio id="mv-modal-audio" controls autoplay style="width:100%;max-width:460px" src="${esc(item.url)}"></audio>
  </div>`;
}

function _mvCloseModal() {
  if (_mvYtMessageListener) { window.removeEventListener('message', _mvYtMessageListener); _mvYtMessageListener = null; }
  document.querySelector('.video-modal-overlay')?.remove();
}

function _mvRenderModal() {
  let overlay = document.querySelector('.video-modal-overlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.className = 'video-modal-overlay';
    overlay.addEventListener('click', e => { if (e.target === overlay) _mvCloseModal(); });
    document.body.appendChild(overlay);
  }
  if (_mvYtMessageListener) { window.removeEventListener('message', _mvYtMessageListener); _mvYtMessageListener = null; }
  const queue = window._mvQueue, idx = window._mvQueueIndex;
  const item = queue[idx];
  if (!item) { _mvCloseModal(); return; }
  const hasPrev = idx > 0, hasNext = idx < queue.length - 1;
  overlay.innerHTML = `
    <div class="video-modal-box">
      <button class="video-modal-close" onclick="window._mvCloseModal()">✕</button>
      <div class="video-modal-title">${esc(item.title)}</div>
      ${queue.length > 1 ? `<div style="text-align:center;font-size:.75rem;color:var(--text-muted);margin:-6px 0 6px">Puntata ${idx + 1} di ${queue.length}</div>` : ''}
      <div class="video-modal-player">${_mvModalInnerHtml(item)}</div>
      ${queue.length > 1 ? `
      <div style="display:flex;justify-content:space-between;gap:8px;margin-top:10px">
        <button class="yt-chip" ${hasPrev ? '' : 'disabled style="opacity:.35;cursor:default"'} onclick="window._mvQueueStep(-1)">← Precedente</button>
        <button class="yt-chip" ${hasNext ? '' : 'disabled style="opacity:.35;cursor:default"'} onclick="window._mvQueueStep(1)">Successiva →</button>
      </div>` : ''}
    </div>`;
  if (item.kind === 'podcast') {
    document.getElementById('mv-modal-audio')?.addEventListener('ended', () => window._mvQueueStep(1, true));
  } else {
    // L'iframe YouTube con enablejsapi=1 manda messaggi postMessage anche
    // senza caricare l'API JS ufficiale — playerState 0 = video concluso.
    _mvYtMessageListener = (e) => {
      if (e.origin !== 'https://www.youtube.com') return;
      let data;
      try { data = typeof e.data === 'string' ? JSON.parse(e.data) : e.data; } catch { return; }
      if (data?.event === 'infoDelivery' && data?.info?.playerState === 0) window._mvQueueStep(1, true);
    };
    window.addEventListener('message', _mvYtMessageListener);
  }
}

window._mvQueueStep = (delta, isAutoAdvance) => {
  const next = window._mvQueueIndex + delta;
  if (next < 0 || next >= window._mvQueue.length) {
    if (isAutoAdvance) _mvCloseModal(); // fine coda: chiudi invece di restare bloccati
    return;
  }
  const item = window._mvQueue[next];
  if (item) window._mvIncrView(item.id);
  window._mvQueueIndex = next;
  _mvRenderModal();
};
window._mvCloseModal = _mvCloseModal;

// Apre un video/podcast in coda (avanzamento automatico dal più vecchio al
// più recente, vedi window._mvCurrentQueueSource) — usata dai click sulle
// card dentro un profilo creator. clickedId = v.id del video cliccato.
window.openMediaQueueFromSource = (clickedId) => {
  const { queue, index } = _mvBuildQueueFromSource(clickedId);
  window._mvQueue = queue.length ? queue : [];
  window._mvQueueIndex = index;
  if (!window._mvQueue.length) return;
  window._mvIncrView(window._mvQueue[index].id);
  _mvRenderModal();
};

// Apertura "singola" (nessuna coda) — usata da tutti gli altri punti del
// sito che aprono un video isolato (pagina gara, dirette, presentazioni…),
// invariati rispetto a prima.
window.openVideoModal = (videoId, title) => {
  window._mvQueue = [{ id: null, kind: 'yt', ytId: videoId, title }];
  window._mvQueueIndex = 0;
  _mvRenderModal();
};
window.openPodcastModal = (url, title, cover) => {
  window._mvQueue = [{ id: null, kind: 'podcast', url, title, cover }];
  window._mvQueueIndex = 0;
  _mvRenderModal();
};

// Player delle dirette, due stati sullo stesso elemento (appeso a
// document.body, fuori da #app: setPage()/route() lo ridimensionano ma non
// lo distruggono mai da soli):
//  - schermo intero, centrato, con sfondo scurito — stato di apertura;
//  - mini-player in basso a destra — quando l'utente naviga altrove
//    (vedi route()) o clicca "riduci"; ricliccandolo torna a schermo intero.
// Nota: la riproduzione in background a schermo spento del telefono dipende
// dal browser/OS (comportamento standard per un embed YouTube in una pagina
// web, non forzabile via codice) — qui ci limitiamo a non metterlo mai in
// pausa noi quando cambia la visibilità della pagina.
window.openLivePlayer = (videoId, title, garaId) => {
  if (!videoId) return;
  const existing = document.getElementById('live-player');
  if (existing && existing.dataset.videoId === videoId) {
    existing.classList.remove('live-player-mini');
    return;
  }
  existing?.remove();
  const lp = document.createElement('div');
  lp.id = 'live-player';
  lp.dataset.videoId = videoId;
  lp.innerHTML = `
    <div class="live-player-backdrop" onclick="window.minimizeLivePlayer()"></div>
    <div class="live-player-box">
      <div class="live-player-hdr">
        <span class="live-player-title">${esc(title || 'Diretta')}</span>
        <div class="live-player-actions">
          ${garaId && !String(garaId).includes('::') ? `<a href="#/gara/${esc(garaId)}" title="Vai alla gara" class="live-player-expand">⤢</a>` : ''}
          <button onclick="event.stopPropagation();window.minimizeLivePlayer()" title="Riduci" class="live-player-min">▁</button>
          <button onclick="event.stopPropagation();window.closeLivePlayer()" title="Chiudi" class="live-player-close">✕</button>
        </div>
      </div>
      <div class="live-player-frame">
        <iframe src="https://www.youtube.com/embed/${videoId}?autoplay=1&rel=0"
                frameborder="0" allowfullscreen
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture">
        </iframe>
      </div>
    </div>`;
  lp.addEventListener('click', () => { if (lp.classList.contains('live-player-mini')) window.restoreLivePlayer(); });
  document.body.appendChild(lp);
};
window.minimizeLivePlayer = () => { document.getElementById('live-player')?.classList.add('live-player-mini'); };
window.restoreLivePlayer  = () => { document.getElementById('live-player')?.classList.remove('live-player-mini'); };
window.closeLivePlayer    = () => { document.getElementById('live-player')?.remove(); };

// ── NAV DROPDOWNS (click-based) ───────────────────────────────
function initNavDropdowns() {
  // Chiudi tutti i gruppi aperti
  function closeAll() {
    document.querySelectorAll('.nav-group.open').forEach(g => {
      g.classList.remove('open');
      g.querySelector('.nav-group-btn')?.setAttribute('aria-expanded', 'false');
    });
  }

  // Click sul bottone del gruppo → toggle open
  document.querySelectorAll('.nav-group-btn').forEach(btn => {
    btn.addEventListener('click', function(e) {
      e.stopPropagation();
      const group = this.closest('.nav-group');
      const wasOpen = group.classList.contains('open');
      closeAll();
      if (!wasOpen) {
        group.classList.add('open');
        this.setAttribute('aria-expanded', 'true');
      }
    });
  });

  // Click su una voce del menu → chiudi il dropdown
  document.querySelectorAll('.nav-group-item').forEach(item => {
    item.addEventListener('click', () => closeAll());
  });

  // Click fuori dal nav-group → chiudi
  document.addEventListener('click', function(e) {
    if (!e.target.closest('.nav-group')) closeAll();
  });

  // Escape → chiudi
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') closeAll();
  });
}

// ── MOBILE MENU ───────────────────────────────────────────────
function initMobileMenu() {
  const hamburger = document.getElementById('nav-hamburger');
  const drawer    = document.getElementById('nav-drawer');
  if (!hamburger || !drawer) return;

  hamburger.addEventListener('click', () => {
    const isOpen = drawer.classList.toggle('open');
    hamburger.setAttribute('aria-expanded', isOpen);
  });

  // Chiudi drawer al click su link
  drawer.querySelectorAll('a').forEach(a => {
    a.addEventListener('click', () => {
      drawer.classList.remove('open');
      hamburger.setAttribute('aria-expanded', 'false');
    });
  });
}

// ── CONSTANTS ─────────────────────────────────────────────────
// Spostato in alto

// ── RISULTATI FEED ──────────────────────────────────────────
let risQueryGenere = '';
let risQueryCat = '';
let risQueryMonth = '';
let risQueryRegion = '';
let risQueryTipo = '';
let risSearchQuery = '';
let _risSearchTimer = null;
// Paginazione "carica altro": il primo batch è piccolo per un caricamento
// veloce della pagina (poche card pesanti da costruire/dipingere), i batch
// successivi sono più larghi visto che l'utente ha già scelto di andare
// avanti. Si resetta ogni volta che cambia un filtro (vedi filterSig sotto),
// non quando si preme "Vedi di più".
const RIS_PAGE_INITIAL = 20;
const RIS_PAGE_STEP = 30;
let risVisibleCount = RIS_PAGE_INITIAL;
let _risLastFilterSig = null;

// Sincronizza la barra indirizzi con la categoria filtrata (URL riconosciuto
// dal router: #/risultati/:cat) — replaceState per non intasare "indietro"
// con ogni singolo cambio filtro, solo la vera navigazione crea history.
function _syncRisultatiUrl() {
  const path = risQueryCat ? '/risultati/' + encodeURIComponent(risQueryCat) : '/risultati';
  if (location.pathname !== path) history.replaceState(null, '', path);
}
// Un contesto "hub" (es. sezione Allievi Uomini) resta attivo tra una
// pagina e l'altra (persistito in localStorage, riapplicato ad ogni
// navigazione da _softRestoreContext) e filtra silenziosamente le gare per
// genere/categoria — SENZA che sia visibile su questa pagina. Se l'utente
// sceglie a mano un genere o una categoria che il contesto hub esclude (es.
// arrivato da "Allievi Uomini" e ora seleziona "Donne"), quel filtro
// invisibile azzerava i risultati senza spiegazione. La scelta esplicita
// qui deve sempre vincere sul contesto ereditato.
// Anni storici (ciclismo.info): i filtri restano SEMPRE visibili e attivi
// (richiesta esplicita) — quando è selezionato un anno storico, ogni
// setter richiama renderRisultatiStorico invece di renderRisultati.
let _risHistoricalYear = null;
window.risSetGenere = (v) => {
  // clearHubFilter() azzera anche risQueryGenere/risQueryCat (e richiama
  // route()) — va chiamata PRIMA di impostare il valore scelto qui, non
  // dopo, altrimenti lo sovrascriverebbe di nuovo a vuoto.
  if (activeHub && v && activeHub.gender !== v) window.clearHubFilter();
  risQueryGenere = v;
  _risHistoricalYear ? renderRisultatiStorico(_risHistoricalYear) : renderRisultati();
};
window.risSetCat = (v) => {
  // Sugli anni storici (ciclismo.info) il menu categoria usa i codici GREZZI
  // della fonte (es. "JUNIORES"), non i codici nativi (es. "JUN_M") con cui
  // è espresso activeHub.catCodes — vanno tradotti prima del confronto,
  // altrimenti la select storica azzererebbe SEMPRE l'hub attivo in alto
  // (mismatch garantito tra "JUNIORES" e "JUN_M").
  const vNative = _risHistoricalYear ? CICLISMO_CAT_TO_NATIVE[v] : v;
  if (activeHub && v && activeHub.catCodes && !activeHub.catCodes.includes(vNative)) window.clearHubFilter();
  risQueryCat = v;
  _syncRisultatiUrl();
  _risHistoricalYear ? renderRisultatiStorico(_risHistoricalYear) : renderRisultati();
};
window.risSetMonth  = (v) => { risQueryMonth = v; _risHistoricalYear ? renderRisultatiStorico(_risHistoricalYear) : renderRisultati(); };
window.risSetRegion = (v) => { risQueryRegion = v; _risHistoricalYear ? renderRisultatiStorico(_risHistoricalYear) : renderRisultati(); };
window.risSetTipo   = (v) => { risQueryTipo = v; _risHistoricalYear ? renderRisultatiStorico(_risHistoricalYear) : renderRisultati(); };
window.risSetSearch = (v) => {
  clearTimeout(_risSearchTimer);
  _risSearchTimer = setTimeout(() => { risSearchQuery = v; _risHistoricalYear ? renderRisultatiStorico(_risHistoricalYear) : renderRisultati(); }, 300);
};
window.risLoadMore = () => { risVisibleCount += RIS_PAGE_STEP; _risHistoricalYear ? renderRisultatiStorico(_risHistoricalYear) : renderRisultati(); };

// Anni storici (ciclismo.info, fino al 2007): il pulsante nativo resta
// "reale" solo per la stagione caricata — ogni anno precedente mostra le
// gare importate da ciclismo.info al posto dei dati nativi FCI (che non
// coprono quegli anni). I filtri restano visibili e funzionanti su
// entrambi (richiesta esplicita), applicati lato client per gli anni storici.
window.risSetYear = (y) => {
  document.querySelectorAll('#ris-year-row .year-pill, #ris-year-row button').forEach(b => {
    const on = Number(b.dataset.year) === Number(y);
    b.style.background = on ? 'var(--accent,#e8001d)' : 'var(--bg-elevated)';
    b.style.color = on ? '#fff' : 'var(--text-secondary)';
  });
  if (Number(y) === Number(_loadedSeasonYear())) {
    _risHistoricalYear = null;
    renderRisultati();
    return;
  }
  _risHistoricalYear = y;
  renderRisultatiStorico(y);
};

window._risStoricoCache = window._risStoricoCache || {};
// Mappa best-effort categorie ciclismo.info -> codici nativi (stessa di
// server/ciclismo-create-profiles.js) — serve per applicare il filtro hub
// del menu in alto (es. "Juniores") anche agli anni storici, che usano
// le categorie grezze della fonte (JUNIORES) invece dei codici nativi (JUN_M).
const CICLISMO_CAT_TO_NATIVE = {
  ESORDIENTI1: 'ES1_M', ESORDIENTI2: 'ES2_M', ALLIEVI: 'AL_M', JUNIORES: 'JUN_M', ELITE_UNDER23: 'ELI_M',
  DONNE_ESORDIENTI: 'AL_F', DONNE_ALLIEVE: 'AL_F', DONNE_JUNIORES: 'JUN_F',
};
async function renderRisultatiStorico(anno) {
  // I filtri restano SEMPRE visibili (richiesta esplicita) — niente/tipo
  // moltiplicatore/campionato non esiste per ciclismo.info, quindi "Tutti i
  // tipi" resta l'unica scelta sensata lì, ma il resto (ricerca, mese,
  // genere, regione, categoria) funziona per davvero, applicato qui lato
  // client sull'elenco già scaricato.
  const cardsEl = document.getElementById('ris-cards');
  const countEl = document.getElementById('ris-count');
  if (!cardsEl) return;

  let allRaces = window._risStoricoCache[anno];
  if (!allRaces) {
    cardsEl.innerHTML = '<div class="empty-state">Caricamento…</div>';
    let payload;
    try { payload = await apiCall(`/ciclismo-results/races?anno=${encodeURIComponent(anno)}`); }
    catch { cardsEl.innerHTML = '<div class="empty-state">Errore di caricamento</div>'; return; }
    allRaces = payload?.races || [];
    window._risStoricoCache[anno] = allRaces;
  }

  // Popola il filtro categoria con le categorie REALI di quest'anno (codici
  // ciclismo.info, es. DONNE_ALLIEVE) — diverse dai codici nativi (AL_F).
  const selCat = document.getElementById('ris-sel-cat');
  if (selCat && selCat.dataset.histYear !== String(anno)) {
    const catSet = new Set();
    allRaces.forEach(r => Object.keys(r.categorie || {}).forEach(c => catSet.add(c)));
    const cats = [...catSet].sort();
    selCat.innerHTML = `<option value="">Tutte le categorie</option>` +
      cats.map(c => `<option value="${esc(c)}"${c === risQueryCat ? ' selected' : ''}>${esc(String(c).replace(/_/g, ' '))}</option>`).join('');
    selCat.dataset.histYear = String(anno);
  }

  let races = allRaces;
  if (risSearchQuery) {
    const q = risSearchQuery.toLowerCase();
    races = races.filter(r => r.nome.toLowerCase().includes(q) || (r.regione || '').toLowerCase().includes(q));
  }
  if (risQueryMonth) races = races.filter(r => r.data && r.data.split('-')[1] === risQueryMonth);
  if (risQueryRegion) races = races.filter(r => r.regione === risQueryRegion);
  if (risQueryGenere) races = races.filter(r => Object.keys(r.categorie || {}).some(c => /^DONNE/i.test(c) === (risQueryGenere === 'F')));
  if (risQueryCat) races = races.filter(r => r.categorie && r.categorie[risQueryCat]);
  // Filtro hub (menu in alto, es. "Juniores") — mancava del tutto sugli
  // anni storici: si vedevano sempre tutte le categorie mescolate anche
  // con un hub selezionato. Le categorie qui sono i codici GREZZI di
  // ciclismo.info, si mappano ai codici nativi per il confronto.
  if (activeHub && activeHub.catCodes && activeHub.catCodes.length) {
    races = races.filter(ev => Object.keys(ev.categorie || {}).some(c => activeHub.catCodes.includes(CICLISMO_CAT_TO_NATIVE[c])));
  }

  const filterSig = JSON.stringify([anno, risSearchQuery, risQueryMonth, risQueryRegion, risQueryGenere, risQueryCat, activeHub && activeHub.catCodes]);
  if (filterSig !== window._risStoricoLastFilterSig) {
    risVisibleCount = RIS_PAGE_INITIAL;
    window._risStoricoLastFilterSig = filterSig;
  }
  const totalRaces = races.length;
  const visibleRaces = races.slice(0, risVisibleCount);

  if (countEl) countEl.textContent = totalRaces > visibleRaces.length ? `${visibleRaces.length} di ${totalRaces} gare` : `${totalRaces} gare`;
  if (!totalRaces) { cardsEl.innerHTML = '<div class="empty-state">Nessuna gara trovata</div>'; return; }

  const posColorHero = ['p1', 'p2', 'p3'];
  cardsEl.innerHTML = visibleRaces.map(ev => {
    const catEntries = Object.entries(ev.categorie || {}).filter(([, top3]) => top3.length);

    const catSections = catEntries.map(([catName, top3]) => {
      const podioRows = top3.map((r, i) => {
        const pClass = posColorHero[i] || 'pout';
        const nomeLink = r.atleta_id ? `<a href="#/atleta/${esc(r.atleta_id)}">${esc(r.nome_completo)}</a>` : esc(r.nome_completo || '');
        return `<div class="hero-podio-row ris-podio-row" style="animation-delay:${i * 60}ms">
          <div class="hero-pos ${pClass}">${r.posizione}°</div>
          <div class="ris-podio-info">
            <div class="hero-name">${nomeLink}</div>
            <div class="hero-team" style="color:var(--text-secondary)">${esc(r.team || '')}</div>
          </div>
        </div>`;
      }).join('');
      return `<div class="ris-cat-section">
        <div class="ris-cat-label">${esc(String(catName).replace(/_/g, ' '))}</div>
        ${podioRows}
        <div class="ris-full-link">
          <a href="#/gara/CIC_${esc(ev.id)}" class="btn-action full" style="font-size:0.75rem;text-align:center;flex:1">CLASSIFICA COMPLETA &rarr;</a>
        </div>
      </div>`;
    }).join(catEntries.length > 1 ? '<div class="ris-cat-divider"></div>' : '');

    const winner = catEntries[0]?.[1]?.[0];
    const second = catEntries[0]?.[1]?.[1];
    const winLine = winner ? `Vince ${esc(winner.nome_completo)}${second ? ` davanti a ${esc(second.nome_completo)}` : ''}.` : '';

    const photoEl = ev.photo_url
      ? `<a href="#/gara/CIC_${esc(ev.id)}" class="ris-card-photo"><img src="${esc(mediaUrl(ev.photo_url))}" alt="Foto gara" loading="lazy"/></a>`
      : '';

    return `<div class="hero-band ris-card">
      ${photoEl ? `<div class="ris-card-media">${photoEl}</div>` : ''}
      <div class="ris-card-body">
        <div class="hero-race-name"><a href="#/gara/CIC_${esc(ev.id)}">${esc(ev.nome)}</a></div>
        ${winLine ? `<div class="ris-race-narrative">${winLine}</div>` : ''}
        <div class="hero-race-meta" style="margin-bottom:14px;">
          <span>${fmtDateShort(ev.data)}</span>
          ${ev.regione ? `<span class="ris-region-tag">${esc(ev.regione)}</span>` : ''}
        </div>
        <div class="hero-divider" style="margin-bottom:12px;"></div>
        <div class="hero-podio">${catSections}</div>
      </div>
    </div>`;
  }).join('');

  if (totalRaces > visibleRaces.length) {
    cardsEl.insertAdjacentHTML('beforeend',
      `<button onclick="window.risLoadMore()" style="margin:28px auto;display:flex;align-items:center;justify-content:center;gap:8px;width:100%;max-width:360px;padding:16px 24px;background:var(--red-hot);color:#fff;border:none;border-radius:var(--r-md,10px);font-weight:800;font-size:1rem;letter-spacing:.02em;cursor:pointer;box-shadow:0 4px 14px rgba(255,107,0,0.35)">
        VEDI DI PIÙ <span style="opacity:.85;font-weight:600">(${totalRaces - visibleRaces.length})</span>
        <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="6 9 12 15 18 9"/></svg>
      </button>`);
  }
}

let _risPhotosMap = null;
let _risPhotosByAtleta = null; // atleta_id → [photoObj,...] (foto taggate)
let _risExtPhotosMap = null;   // SOLO album esterni (xpix/IC), non sovrascritti dalle foto caricate
async function loadRisPhotos() {
  if (_risPhotosMap) return _risPhotosMap;
  try {
    const [d1, d2, d3] = await Promise.all([
      fetch(`${API_BASE}/race-photos`).then(r => r.json()).catch(() => ({ photos: [] })),
      fetch(`${API_BASE}/xpix-photos`).then(r => r.json()).catch(() => ({ photos: [] })),
      fetch(`${API_BASE}/ic-photos`).then(r => r.json()).catch(() => ({ photos: [] })),
    ]);
    // Indice foto → atleta taggato (solo race-photos caricate hanno tag)
    _risPhotosByAtleta = {};
    (d1.photos || []).forEach(p => {
      const ids = String(p.atleta_ids || '').split(',').map(s => s.trim()).filter(Boolean);
      for (const aid of ids) {
        if (!_risPhotosByAtleta[aid]) _risPhotosByAtleta[aid] = [];
        _risPhotosByAtleta[aid].push(p);
      }
    });
    // Foto esterne taggate a un corridore (xpix + ciclismo.info):
    // mappa photoUrl → CSV atleti, per gara → indice per profilo atleta.
    const _indexExtTags = (arr, src) => (arr || []).forEach(p => {
      if (!p.tags) return;
      for (const [photoUrl, csv] of Object.entries(p.tags)) {
        const ids = String(csv || '').split(',').map(s => s.trim()).filter(Boolean);
        for (const aid of ids) {
          if (!_risPhotosByAtleta[aid]) _risPhotosByAtleta[aid] = [];
          _risPhotosByAtleta[aid].push({ url: photoUrl, gara_id: p.gara_id, caption: p.album_name || p.name || '', source: src });
        }
      }
    });
    _indexExtTags(d2.photos, 'xpix');  // xpix
    _indexExtTags(d3.photos, 'italiaciclismo');  // ciclismo.info
    // Mappa SOLO album esterni (xpix/IC) — NON sovrascritta dalle foto caricate,
    // così un album resta accessibile anche se c'è già una foto manuale.
    _risExtPhotosMap = {};
    const _extAlias = p => {
      if (!p.gara_id) return;
      if (!_risExtPhotosMap[p.gara_id]) _risExtPhotosMap[p.gara_id] = p;
      const noNum = p.gara_id.replace(/^\d+_/, '');
      if (noNum !== p.gara_id && !_risExtPhotosMap[noNum]) _risExtPhotosMap[noNum] = p;
      const noSuffix = p.gara_id.replace(/_[A-Z0-9]+_[MF]$/, '');
      if (noSuffix !== p.gara_id && !_risExtPhotosMap[noSuffix]) _risExtPhotosMap[noSuffix] = p;
    };
    (d3.photos || []).forEach(_extAlias); // ic
    (d2.photos || []).forEach(_extAlias); // xpix (non sovrascrive ic per stessa chiave)

    _risPhotosMap = {};
    // Priorità: italiaciclismo < xpix < uploaded
    (d3.photos || []).forEach(p => { if (p.gara_id && !_risPhotosMap[p.gara_id]) _risPhotosMap[p.gara_id] = p; });
    (d2.photos || []).forEach(p => { if (p.gara_id && !_risPhotosMap[p.gara_id]) _risPhotosMap[p.gara_id] = p; });
    (d1.photos || []).forEach(p => { if (p.gara_id) _risPhotosMap[p.gara_id] = p; });
    // Fuzzy alias: per ogni foto xpix crea alias senza prefisso numerico e senza suffisso categoria
    // es: "72_TROFEO_MATTEOTTI_2026-05-17_ELI_M" → alias senza "72_"
    (d2.photos || []).forEach(p => {
      if (!p.gara_id) return;
      const noNum = p.gara_id.replace(/^\d+_/, '');
      if (noNum !== p.gara_id && !_risPhotosMap[noNum]) _risPhotosMap[noNum] = p;
      // alias senza _ELI_M / _JUN_M ecc.
      const noSuffix = p.gara_id.replace(/_[A-Z0-9]+_[MF]$/, '');
      if (noSuffix !== p.gara_id && !_risPhotosMap[noSuffix]) _risPhotosMap[noSuffix] = p;
    });
  } catch { _risPhotosMap = {}; }
  return _risPhotosMap;
}

async function renderRisultati() {
  if (!globalData) return;
  const { resultsRaw, calendar } = globalData;
  const photosMap = await loadRisPhotos();

  // Raggruppa per gara_id — ogni categoria ha il proprio card separato,
  // Esordienti 1° e 2° Anno inclusi: prima venivano fusi in un'unica card
  // con due sezioni interne (stesso gara_id normalizzato), ma l'utente vuole
  // vederli come card distinte nell'elenco — proprio come Allievi/Juniores/
  // Elite — con la possibilità di filtrarli separatamente dal menu categoria.
  // La pagina della singola gara (renderGara) continua comunque a mostrare
  // 1° e 2° anno insieme quando si apre "classifica completa", quello non
  // cambia: qui cambia solo come appaiono nell'elenco Risultati.
  const eventMap = {};
  for (const r of resultsRaw) {
    const eventKey = r.gara_id || (r.nome_gara.trim().toUpperCase() + '|' + r.data + '|' + (r.genere||'M'));
    if (!eventMap[eventKey]) {
      eventMap[eventKey] = {
        id: r.gara_id,
        nome: r.nome_gara,
        data: r.data,
        genere: r.genere,
        tipo: r.tipo,
        regione: r.regione,
        byCategory: {}
      };
    }
    // Chiave di raggruppamento normalizzata: le righe scrapate dalla FCI hanno
    // categoria come etichetta testuale ("Allievi"), quelle inserite a mano
    // come codice ("AL_M", vedi _mrDeriveMeta) — usare r.categoria grezzo le
    // separava in due gruppi diversi per la stessa categoria, e lo slice
    // "primi 3" finiva applicato al gruppetto sbagliato (solo le righe
    // manuali, es. posizioni 11-13 invece del vero podio).
    const cat = getRankingFileCode(r) || r.categoria || 'N/D';
    if (!eventMap[eventKey].byCategory[cat]) {
      eventMap[eventKey].byCategory[cat] = { gara_id: r.gara_id, results: [] };
    }
    eventMap[eventKey].byCategory[cat].results.push(r);
  }

  for (const ev of Object.values(eventMap)) {
    const firstCat = Object.values(ev.byCategory)[0];
    const firstRes = firstCat ? firstCat.results[0] : null;
    ev.mult = firstRes?.moltiplicatore || 1;
    ev.tipo = firstRes?.tipo || 'regionale';
    ev.campionato_regionale = firstRes?.campionato_regionale || false;
    ev.campionato_italiano = firstRes?.campionato_italiano || false;
  }

  let races = Object.values(eventMap).sort((a,b) => (b.data||'').localeCompare(a.data||''));
  
  // Extract all regions, filtering out category false positives
  const badRegions = ['JUNIORES', 'ALLIEVE', 'ESORDIENTI', 'UNDER', 'ELITE', 'DONNE', 'UOMINI', 'ITALIA', 'PROVA', 'CAMPIONATO'];
  const allRegions = [...new Set(races.map(r => r.regione).filter(Boolean))].filter(r => !badRegions.includes(r.toUpperCase())).sort();

  // Apply filters
  if (risSearchQuery) {
    const q = risSearchQuery.toLowerCase();
    races = races.filter(r => r.nome.toLowerCase().includes(q) || (r.regione || '').toLowerCase().includes(q));
  }
  if (risQueryGenere) races = races.filter(r => r.genere === risQueryGenere);
  // Filtro hub (top-nav, es. "Elite / U23"): confronta i CODICI categoria
  // esatti (activeHub.catCodes, es. ['ELI_M']) contro le chiavi di byCategory
  // — che ora sono sempre codici (getRankingFileCode), mai etichette testuali.
  // Prima usava activeHub.catFilter (sottostringa tipo "Elite") confrontata
  // contro le chiavi: funzionava quando le chiavi erano ancora etichette
  // umane ("Elite - U23"), ma con le chiavi diventate codici ("ELI_M") la
  // sottostringa non c'entrava più nulla ed escludeva TUTTE le gare.
  if (activeHub && activeHub.catCodes && activeHub.catCodes.length) {
    races = races.filter(function(ev) {
      return Object.keys(ev.byCategory || {}).some(function(c) {
        return activeHub.catCodes.includes(c);
      });
    });
  }
  if (risQueryMonth)  races = races.filter(r => r.data && r.data.split('-')[1] === risQueryMonth);
  if (risQueryRegion) races = races.filter(r => r.regione === risQueryRegion);
  if (risQueryTipo) races = races.filter(ev => {
    if (risQueryTipo === 'campionato_regionale') return ev.campionato_regionale;
    if (risQueryTipo === 'campionato_italiano') return ev.campionato_italiano;
    return ev.tipo === risQueryTipo;
  });
  const allCatsSet = new Set();
  races.forEach(r => Object.keys(r.byCategory||{}).forEach(c => allCatsSet.add(c)));
  const allCats = [...allCatsSet].sort();
  if (risQueryCat) races = races.filter(r => r.byCategory && r.byCategory[risQueryCat]);

  // Un cambio filtro deve ripartire dal primo batch (altrimenti si vedrebbe
  // "0 di 20" o card residue del filtro precedente); il click su "Vedi di
  // più" invece NON deve passare da qui — richiama renderRisultati() dopo
  // aver già incrementato risVisibleCount, quindi la firma resta identica.
  const filterSig = JSON.stringify([risSearchQuery, risQueryGenere, risQueryMonth, risQueryRegion, risQueryTipo, risQueryCat, activeHub && activeHub.catCodes]);
  if (filterSig !== _risLastFilterSig) {
    risVisibleCount = RIS_PAGE_INITIAL;
    _risLastFilterSig = filterSig;
  }
  const totalRaces = races.length;
  const visibleRaces = races.slice(0, risVisibleCount);

  // Meta/canonical dinamici a ogni render (non solo al primo) — necessario
  // perché il cambio categoria non ricrea il DOM shell (isFirstRender resta
  // false), ma deve comunque aggiornare titolo/URL indicizzabile.
  setPageMeta(
    risQueryCat ? `Risultati ${catLabel(risQueryCat)}` : 'Risultati Gare',
    risQueryCat
      ? `Tutti i risultati delle gare di ciclismo agonistico italiano nella categoria ${catLabel(risQueryCat)}.`
      : 'Tutti i risultati delle gare di ciclismo agonistico italiano: Esordienti, Allievi, Juniores, Under23, Elite — uomini e donne.'
  );

  // ── First render: build the persistent shell ──────────────────
  const appEl = document.getElementById('app');
  if (!appEl) return;
  const isFirstRender = !document.getElementById('ris-cards');
  if (isFirstRender) {
    const selectsHtml = `
      <select class="cal-filter-select" id="ris-sel-month" onchange="window.risSetMonth(this.value)" aria-label="Filtra per mese">
        <option value="">Tutti i mesi</option>
        ${['01','02','03','04','05','06','07','08','09','10','11','12'].map((m,i) =>
          `<option value="${m}">${['Gennaio','Febbraio','Marzo','Aprile','Maggio','Giugno','Luglio','Agosto','Settembre','Ottobre','Novembre','Dicembre'][i]}</option>`
        ).join('')}
      </select>
      <select class="cal-filter-select" id="ris-sel-genere" onchange="window.risSetGenere(this.value)" aria-label="Filtra per genere">
        <option value="">Tutti i generi</option>
        <option value="M">Uomini</option>
        <option value="F">Donne</option>
      </select>
      <select class="cal-filter-select" id="ris-sel-region" onchange="window.risSetRegion(this.value)" aria-label="Filtra per regione">
        <option value="">Tutte le regioni</option>
        ${allRegions.map(r => `<option value="${r}">${esc(r)}</option>`).join('')}
      </select>
      <select class="cal-filter-select" id="ris-sel-cat" onchange="window.risSetCat(this.value)" aria-label="Filtra per categoria">
        <option value="">Tutte le categorie</option>
      </select>
      <select class="cal-filter-select" id="ris-sel-tipo" onchange="window.risSetTipo(this.value)" aria-label="Filtra per tipologia">
        <option value="">Tutti i tipi</option>
        <option value="regionale">Regionali ×1</option>
        <option value="nazionale">Nazionali ×2</option>
        <option value="internazionale">Internazionali ×3</option>
        <option value="campionato_regionale">Campionati Regionali</option>
        <option value="campionato_italiano">Campionati Italiani</option>
        <option value="tipo_pista">Tipo Pista</option>
      </select>`;

    const _risCurYear = Number(_loadedSeasonYear());
    const _risYearPills = [];
    for (let y = _risCurYear; y >= 2007; y--) _risYearPills.push(y);
    const risYearPillsHtml = `<div id="ris-year-row" style="display:flex;gap:8px;overflow-x:auto;flex-wrap:nowrap;margin:12px 0 4px;padding-bottom:4px;scrollbar-width:thin">
      ${_risYearPills.map(y => `<button class="year-pill" data-year="${y}" onclick="window.risSetYear(${y})"
        style="flex:0 0 auto;padding:5px 13px;border-radius:14px;border:1px solid var(--border-subtle);cursor:pointer;font-size:.82rem;font-weight:700;
        background:${y === _risCurYear ? 'var(--accent,#e8001d)' : 'var(--bg-elevated)'};color:${y === _risCurYear ? '#fff' : 'var(--text-secondary)'}">${y}</button>`).join('')}
    </div>`;

    setPage(`
      <div class="content-wrapper">
        <div class="section-header">
          <h1 style="font-family:var(--font-display);font-size:var(--size-h1);margin-bottom:0">Risultati</h1>
          <span class="section-line"></span>
        </div>
        ${risYearPillsHtml}
        <div class="calendar-controls" id="ris-native-controls">
          <input type="text" id="ris-search-input" class="cal-filter-select" placeholder="Cerca gara o regione..."
            style="width:100%;box-sizing:border-box;padding:12px 16px;margin-bottom:12px;"
            oninput="window.risSetSearch(this.value)" autocomplete="off">
          <div id="ris-selects">${selectsHtml}</div>
          <span class="ranking-count" id="ris-count"></span>
        </div>
        <div class="risultati-feed" style="margin-top:20px" id="ris-cards"></div>
      </div>
    `);
  }

  // ── Always: update selects state ──────────────────────────────
  const selMonth  = document.getElementById('ris-sel-month');
  const selGenere = document.getElementById('ris-sel-genere');
  const selRegion = document.getElementById('ris-sel-region');
  const selCat    = document.getElementById('ris-sel-cat');
  const selTipo   = document.getElementById('ris-sel-tipo');
  const countEl   = document.getElementById('ris-count');
  const cardsEl   = document.getElementById('ris-cards');

  if (selMonth)  selMonth.value  = risQueryMonth  || '';
  if (selGenere) selGenere.value = risQueryGenere || '';
  if (selTipo)   selTipo.value   = risQueryTipo   || '';
  if (selRegion) {
    // Rebuild region options (they can change with filters)
    selRegion.innerHTML = `<option value="">Tutte le regioni</option>` +
      allRegions.map(r => `<option value="${r}"${r === risQueryRegion ? ' selected' : ''}>${esc(r)}</option>`).join('');
  }
  if (selCat) {
    selCat.innerHTML = `<option value="">Tutte le categorie</option>` +
      allCats.map(c => `<option value="${c}"${c === risQueryCat ? ' selected' : ''}>${catLabel(c)}</option>`).join('');
  }
  if (countEl) countEl.textContent = totalRaces > visibleRaces.length
    ? `${visibleRaces.length} di ${totalRaces} gare`
    : `${totalRaces} gare trovate`;

  // Always: rebuild only the cards area
  if (cardsEl) {
    cardsEl.innerHTML = visibleRaces.map(race => {
      const mult = race.mult || 1;
      const categories = Object.entries(race.byCategory || {});

      // Una sezione per ogni categoria dell'evento
      // Foto featured a livello card (prima categoria che ha una foto)
      const featuredPhoto = Object.values(race.byCategory || {})
        .map(c => photosMap[c.gara_id]).find(Boolean);

      // Video: usa la mappa gara_id → calendar_id
      const raceCalId = (globalData.garaToCalId || {})[race.id] || toCalId(race.id);
      const raceVideos = (globalData.videos || {})[raceCalId] ||
                         (globalData.videos || {})[race.id] || [];
      const featuredVideo = raceVideos[0] || null;
      const _vKind = featuredVideo ? videoKind(featuredVideo.url) : null;
      const featuredVideoId = (_vKind === 'yt') ? ytId(featuredVideo.url) : null;
      const hasVideoTile = _vKind === 'yt' || _vKind === 'file' || _vKind === 'fb';

      const catSections = categories.map(([catName, catData]) => {
        const sortedCatRes = (catData.results || []).sort((a,b) => a.posizione - b.posizione);
        const top3 = sortedCatRes.slice(0,3);
        const catGaraId = catData.gara_id;
        const cLabel = catLabel(catName) || catName;

        const firstRes = catData.results?.[0];
        const kmVal    = firstRes?.km    || '';
        const mediaVal = firstRes?.media || '';
        const techBit  = [
          kmVal    ? esc(kmVal) + ' km'    : '',
          mediaVal ? esc(mediaVal) + ' km/h' : ''
        ].filter(Boolean).join(' · ');

        const podioRows = top3.map((r,i) => {
          const pClass = ['p1','p2','p3'][i] || 'pout';
          // rank_dopo_gara è calcolato in loadAll() per ogni risultato
          const rkPos = r.rank_dopo_gara;
          const rkHtml = rkPos ? '<span class="ris-rank-pos">' + rkPos + '° class.</span>' : '';
          return '<div class="hero-podio-row ris-podio-row" style="animation-delay:' + (i*60) + 'ms">' +
            '<div class="hero-pos ' + pClass + '">' + r.posizione + '&#176;</div>' +
            '<div class="ris-podio-info">' +
              '<div class="hero-name"><a href="#/atleta/' + esc(r.atleta_id) + '">' + esc(r.cognome) + ' ' + esc(r.nome) + '</a>' + rkHtml + '</div>' +
              '<div class="hero-team"><a href="#/team/' + esc(r.team_id) + '" style="color:var(--text-secondary)">' + esc(r.team) + '</a></div>' +
            '</div>' +
          '</div>';
        }).join('');

        // Race impact
        const impact = siRaceImpact(sortedCatRes, resultsRaw);
        const impactStrip = impact ? (() => {
          const parts = [];
          if (impact.insight) parts.push(`<span class="ris-insight-chip">${impact.insight}</span>`);
          if (impact.topGainer) parts.push(`<span class="ris-mover ris-mover-up">+${impact.topGainer.gain} ${esc(impact.topGainer.cognome)}</span>`);
          if (impact.topFaller) parts.push(`<span class="ris-mover ris-mover-down">${impact.topFaller.gain} ${esc(impact.topFaller.cognome)}</span>`);
          if (impact.hasShakeup && !impact.topGainer && !impact.topFaller) parts.push(`<span class="ris-insight-chip ris-chip-shakeup">Scossone in classifica</span>`);
          return parts.length ? `<div class="ris-impact-strip">${parts.join('')}</div>` : '';
        })() : '';

        // Payload di condivisione pronto qui, senza dover entrare nella pagina
        // gara: stessa forma di _mkShare in renderGara, usando i dati che il
        // riepilogo ha già in memoria (risultati, categoria, km/media).
        if (catGaraId) {
          const calEntryRis = (calendar || []).find(c => c.id === catGaraId);
          window._risShareCache = window._risShareCache || {};
          window._risShareCache[catGaraId] = {
            _id: catGaraId, name: race.nome, date: fmtDate(race.data), cat: cLabel,
            mult, tipo: race.tipo,
            region: normalizeRegion(calEntryRis?.regione || firstRes?.regione || ''),
            luogo: calEntryRis?.luogo || '', km: kmVal, media: mediaVal,
            winnerTime: _calcWinnerTime(kmVal, mediaVal),
            results: sortedCatRes.slice(0, 10).map(r => ({
              cognome: r.cognome, nome: r.nome, team: r.team, atleta_id: r.atleta_id,
              punti_effettivi: r.punti_effettivi,
              tempo: r.posizione === 1 ? '' : (r.tempo || ''),
            })),
          };
        }

        return `
          <div class="ris-cat-section">
            <div class="ris-cat-label">${cLabel}</div>
            ${techBit ? `<div class="ris-tech-bit">${techBit}</div>` : ''}
            ${podioRows}
            ${impactStrip}
            <div class="ris-full-link" style="display:flex;gap:8px;align-items:stretch">
              <a href="/gara/${esc(catGaraId)}" class="btn-action full" style="font-size:0.75rem;text-align:center;flex:1">CLASSIFICA COMPLETA &rarr;</a>
              ${catGaraId ? `<button class="btn-action" title="Condividi risultati" aria-label="Condividi risultati" onclick="window.quickShareGara('${esc(catGaraId)}')" style="flex:0 0 auto;padding:0 12px"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/></svg></button>` : ''}
            </div>
          </div>`;
      }).join(categories.length > 1 ? '<div class="ris-cat-divider"></div>' : '');

      const _photoSrcRis = featuredPhoto?.url ? icProxy(featuredPhoto.url) : (featuredPhoto?.filename ? `${PHOTOS_BASE}/photos/${featuredPhoto.filename}` : '');
      const _photoCreditRis = (() => {
        if (!featuredPhoto) return '';
        if (featuredPhoto.photographer) return '📷 ' + featuredPhoto.photographer;
        if (featuredPhoto.display_name)  return '📷 ' + featuredPhoto.display_name;
        if (featuredPhoto.album_slug || featuredPhoto.source === 'xpix') return '📷 xpix.it';
        if (featuredPhoto.source === 'italiaciclismo') return '📷 italiaciclismo.net';
        return '';
      })();
      const photoEl = _photoSrcRis
        ? `<a href="/gara/${esc(race.id)}" class="ris-card-photo${hasVideoTile ? ' ris-media-half' : ''}">
             <img src="${esc(_photoSrcRis)}" alt="Foto gara" loading="lazy"/>
             ${_photoCreditRis ? `<div class="ris-photo-credit">${esc(_photoCreditRis)}</div>` : ''}
           </a>`
        : '';
      const _vTitleRis = featuredVideo ? esc((featuredVideo.title || '').replace(/'/g, "\\'")) : '';
      const videoEl = hasVideoTile
        ? `<div class="ris-card-video-thumb${featuredPhoto ? ' ris-media-half' : ''}"
               onclick="${_vKind === 'yt'
                 ? `window.openVideoModal('${featuredVideoId}','${_vTitleRis}')`
                 : _vKind === 'fb'
                   ? `window.openFacebookVideoModal('${esc(featuredVideo.url)}','${_vTitleRis}')`
                   : `window.openVideoFileModal('${esc(featuredVideo.url)}','${_vTitleRis}')`}">
             ${_vKind === 'yt'
               ? `<img src="https://img.youtube.com/vi/${featuredVideoId}/hqdefault.jpg" alt="${esc(featuredVideo.title||'Video')}" loading="lazy"/>`
               : _vKind === 'fb'
                 ? fbThumbHtml(featuredVideo.url)
                 : `<video src="${esc(featuredVideo.url)}#t=0.1" preload="metadata" muted playsinline style="width:100%;height:100%;object-fit:cover"></video>`}
             <div class="ris-video-play"><span>▶</span></div>
             ${featuredVideo.channel ? `<div class="ris-video-channel">${esc(featuredVideo.channel)}</div>` : ''}
           </div>`
        : '';
      const mediaPanel = (photoEl || videoEl)
        ? `<div class="ris-card-media${featuredPhoto && hasVideoTile ? ' ris-card-media-split' : ''}">${photoEl}${videoEl}</div>`
        : '';

      const cardTier = race.campionato_italiano ? 'ris-card-ci'
                    : race.campionato_regionale ? 'ris-card-cr'
                    : (race.mult >= 2)          ? 'ris-card-premium'
                    : '';
      const importanceBadge = race.campionato_italiano
        ? '<span class="ris-importance-badge ris-badge-ci">CAMPIONATO ITALIANO</span>'
        : race.campionato_regionale
        ? '<span class="ris-importance-badge ris-badge-cr">CAMP. REGIONALE</span>'
        : race.mult >= 2
        ? `<span class="ris-importance-badge ris-badge-mult">GARA MOLTIPLICATORE ×${race.mult}</span>`
        : '';

      const _raceNarr = siRaceNarrative(race.id, resultsRaw);

      return `
        <div class="hero-band ris-card ${cardTier}">
          ${mediaPanel}
          <div class="ris-card-body">
            ${importanceBadge}
            <div class="hero-race-name"><a href="/gara/${esc(race.id)}">${esc(race.nome)}</a></div>
            ${_raceNarr ? `<div class="ris-race-narrative">${_raceNarr}</div>` : ''}
            <div class="hero-race-meta" style="margin-bottom:14px;">
              <span>${fmtDate(race.data)}</span>
              ${race.regione ? `<span class="ris-region-tag">${esc(race.regione)}</span>` : ''}
              ${badgeMult(race.mult, race.tipo, race.campionato_regionale, race.campionato_italiano)}
            </div>
            <div class="hero-divider" style="margin-bottom:12px;"></div>
            <div class="hero-podio">${catSections}</div>
          </div>
        </div>`;
    }).join('') || '<div class="empty-state">Nessuna gara trovata</div>';

    if (totalRaces > visibleRaces.length) {
      cardsEl.insertAdjacentHTML('beforeend',
        `<button onclick="window.risLoadMore()" style="margin:28px auto;display:flex;align-items:center;justify-content:center;gap:8px;width:100%;max-width:360px;padding:16px 24px;background:var(--red-hot);color:#fff;border:none;border-radius:var(--r-md,10px);font-weight:800;font-size:1rem;letter-spacing:.02em;cursor:pointer;box-shadow:0 4px 14px rgba(255,107,0,0.35)">
          VEDI DI PIÙ <span style="opacity:.85;font-weight:600">(${totalRaces - visibleRaces.length})</span>
          <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="6 9 12 15 18 9"/></svg>
        </button>`);
    }
  }
  // La pagina Risultati usa una shell persistente (no setPage sui re-render):
  // assicura che la barra stagione sotto l'header sia presente/aggiornata.
  placeSeasonBar();
}

// ── SHARE ENGINE v3 ─────────────────────────────────────
window._shareGaraData=null; window._shareAtletaData=null; window._shareTeamData=null;

// SHARE ENGINE v3
const SHARE_PLATFORMS = {
  instagram: { w:1080, h:1350, label:'Instagram\nFeed', color:'#E1306C', cls:'plat-instagram' },
  story:     { w:1080, h:1920, label:'Story /\nReels', color:'#833AB4', cls:'plat-story' },
  facebook:  { w:1200, h:630,  label:'Facebook', color:'#1877F2', cls:'plat-facebook' },
  twitter:   { w:1200, h:675,  label:'Twitter/X', color:'#1DA1F2', cls:'plat-twitter' },
  whatsapp:  { w:1080, h:1080, label:'WhatsApp', color:'#25D366', cls:'plat-whatsapp' }
};
const SHARE_URL = 'italiacyclingstats.com';
const SHARE_TAG = '#italiacrit #ciclismo';
window._shareGaraData = null; window._shareAtletaData = null; window._shareTeamData = null;
let _shareType, _sharePayload, _sharePlatKey = 'instagram';
let _shareLogoImg = null;
// Stile grafica gara: 'winner' (solo vincitore in grande, stile "annuncio")
// o 'results' (podio+risultati in overlay) — scelta libera per qualunque
// formato (Post/Instagram/Story), non un formato a sé. "Vincitore" è quella
// principale, mostrata per prima di default.
let _shareGaraStyle = 'winner';
// Regolazione manuale della foto di sfondo (zoom + spostamento), per
// centrare a mano il soggetto quando il ritaglio automatico non va bene —
// resettata ad ogni apertura della modale. offsetX/offsetY sono in pixel
// "canvas" (spazio dell'immagine finale, non dello schermo).
let _shareImgAdjust = { scale: 1, offsetX: 0, offsetY: 0 };

// ── MEDIA (foto/video/dirette per gara, stile YouTube) ───────────────────
let mediaTab = 'video'; // 'video' | 'dirette' | 'presentazioni' | 'programmi_tv' | 'altro' | 'creator'
let mediaQueryGenere = '';
let mediaQueryCat = '';
let mediaQueryMonth = '';
let mediaSearchQuery = '';
// Filtro per canale/creator nelle schede Video/Dirette/Presentazioni/ecc.
// (striscia di cerchietti, stesso concetto della tab Creator ma basata sui
// campi channel/channel_avatar già presenti su ogni video legacy, non sui
// media_profiles — i due sistemi non sono collegati).
let mediaChannelFilter = '';
window.mediaSetChannelFilter = (ch) => { mediaChannelFilter = mediaChannelFilter === ch ? '' : ch; renderMedia(); };

// Contatore visualizzazioni NOSTRO per i video del sistema esistente (gara/
// dirette/presentazioni/programmi TV/altro) — non hanno un ID DB stabile,
// tracciati per url. Mappa caricata una volta a pagina (non blocca il
// render se fallisce), incrementata in modo ottimistico al click.
let _legacyViews = {};
let _legacyViewsLoaded = false;
async function _loadLegacyViews() {
  if (_legacyViewsLoaded) return;
  _legacyViewsLoaded = true;
  try { _legacyViews = (await fetch(`${API_BASE}/videos/views`).then(r => r.json())).views || {}; } catch {}
}
window._legacyIncrView = function(key) {
  if (!key) return;
  _legacyViews[key] = (_legacyViews[key] || 0) + 1;
  fetch(`${API_BASE}/videos/view`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ key }) }).catch(() => {});
};

const MEDIA_TAB_KEY_TO_URL = { video: 'video', dirette: 'dirette', presentazioni: 'presentazioni', programmi_tv: 'programmi-tv', altro: 'altro', creator: 'creator' };
window.mediaSetTab    = (t) => { mediaTab = t; mediaChannelFilter = ''; navTo('/media/' + (MEDIA_TAB_KEY_TO_URL[t] || t)); };
window.mediaSetGenere = (v) => { mediaQueryGenere = v; renderMedia(); };
window.mediaSetCat    = (v) => { mediaQueryCat = v; renderMedia(); };
window.mediaSetMonth  = (v) => { mediaQueryMonth = v; renderMedia(); };
window.mediaSetSearch = (v) => { mediaSearchQuery = v; renderMedia(); };

// ── Presentazioni/Programmi TV: elimina (admin) ─────────────────────────────
window.mediaDeleteExtra = async (tipo, idx) => {
  if (!confirm('Eliminare questo video?')) return;
  try {
    await apiCall(`/admin/media/extra/${tipo}/${idx}`, { method: 'DELETE' });
    await refreshVideos();
    renderMedia();
  } catch (e) { showToast('Errore: ' + e.message, 'error'); }
};

// ── Selezione multipla (admin): correggere a mano la destinazione
// Video/Diretta quando il rilevamento automatico sbaglia — es. una gara
// corta erroneamente lasciata tra i Video normali, o viceversa.
window._mediaSel = window._mediaSel || new Set();
window._mediaToggleSel = (key, checked) => {
  if (checked) window._mediaSel.add(key); else window._mediaSel.delete(key);
  renderMedia();
};
window._mediaClearSel = () => { window._mediaSel.clear(); renderMedia(); };
window._mediaBulkSetLive = async (isLive) => {
  const keys = [...window._mediaSel];
  if (!keys.length) return;
  try {
    for (const key of keys) {
      // Non usare split('::') semplice: per le tappe caricate in anticipo il
      // gara_id stesso contiene "::" (chiave sintetica "calId::data"), quindi
      // taglia solo sull'ULTIMO separatore, che precede sempre l'indice.
      const cut = key.lastIndexOf('::');
      const garaId = key.slice(0, cut), idx = key.slice(cut + 2);
      await apiCall(`/admin/videos/${encodeURIComponent(garaId)}/${idx}`, { method: 'PATCH', body: { is_live: isLive } });
    }
    window._mediaSel.clear();
    showToast(`✓ Aggiornati ${keys.length} video`);
    await refreshVideos();
    renderMedia();
  } catch (e) { showToast('Errore: ' + e.message, 'error'); }
};

// Segna una diretta come conclusa SENZA togliere il badge 🔴 DIRETTA (a
// differenza di "Video normale", che la tratta come mai stata una diretta).
// Serve per le piattaforme senza rilevamento automatico dello stato live
// (Facebook — YouTube invece lo capisce da solo via /api/live-status-today):
// sposta il video da "In Diretta Ora" ad "A seguire" mantenendo lo storico.
window._mediaBulkSetEnded = async () => {
  const keys = [...window._mediaSel];
  if (!keys.length) return;
  try {
    for (const key of keys) {
      const cut = key.lastIndexOf('::');
      const garaId = key.slice(0, cut), idx = key.slice(cut + 2);
      await apiCall(`/admin/videos/${encodeURIComponent(garaId)}/${idx}`, { method: 'PATCH', body: { live_ended: true } });
    }
    window._mediaSel.clear();
    showToast(`✓ Segnate come terminate ${keys.length} dirette`);
    await refreshVideos();
    renderMedia();
  } catch (e) { showToast('Errore: ' + e.message, 'error'); }
};

// Ricalcola data di pubblicazione YouTube reale + logo canale per tutti i
// video già salvati (utile una tantum per quelli aggiunti a mano prima che
// venissero catturati automaticamente in fase di inserimento).
window.mediaBackfillMetadata = async (btn) => {
  const prevText = btn.textContent;
  btn.disabled = true; btn.textContent = '⏳ Aggiornamento…';
  try {
    const r = await apiCall('/admin/youtube/backfill-metadata', { method: 'POST' });
    showToast(`✓ Aggiornati ${r.updated} di ${r.checked} video`);
    await refreshVideos();
    renderMedia();
  } catch (e) { showToast('Errore: ' + e.message, 'error'); }
  finally { btn.disabled = false; btn.textContent = prevText; }
};

// ── Aggiungi manualmente (admin): Video/Diretta di una gara, oppure
// Presentazione/Programma TV (nessuna gara da scegliere) — serve soprattutto
// per reinserire a mano video già scartati dalla coda dello scraper canali.
window.openMediaAddForm = () => {
  const inpStyle = 'width:100%;box-sizing:border-box;padding:8px 10px;border:1px solid var(--border-subtle);border-radius:var(--r-sm);font-size:0.875rem;background:var(--bg-primary);color:var(--text-primary);margin-bottom:10px';
  const overlay = document.createElement('div');
  overlay.id = 'modal-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px';
  overlay.innerHTML = `
    <div style="background:var(--bg-card);border-radius:var(--r-lg);padding:24px;width:100%;max-width:460px;box-shadow:0 8px 32px rgba(0,0,0,.3)">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
        <strong style="font-size:1rem">Aggiungi contenuto</strong>
        <button onclick="this.closest('[style*=fixed]').remove()" style="background:none;border:none;font-size:1.3rem;cursor:pointer;color:var(--text-muted)">✕</button>
      </div>
      <label style="display:block;font-size:0.8rem;color:var(--text-secondary);margin-bottom:4px">Tipo</label>
      <select id="madd-tipo" style="${inpStyle}" onchange="window._maddSetTipo(this.value)">
        <option value="gara">🏁 Video di una gara</option>
        <option value="diretta">🔴 Diretta di una gara</option>
        <option value="presentazione">🎤 Presentazione</option>
        <option value="programma_tv">📺 Programma TV</option>
        <option value="altro">🎬 Altro (nessuna gara collegata)</option>
      </select>
      <div id="madd-gara-wrap">
        <label style="display:block;font-size:0.8rem;color:var(--text-secondary);margin-bottom:4px">Gara</label>
        <div style="position:relative">
          <input type="text" id="madd-gara-search" placeholder="Cerca gara per nome…" autocomplete="off" style="${inpStyle}" oninput="window._maddSearchGara(this.value)"/>
          <div id="madd-gara-dd" style="display:none;position:absolute;left:0;right:0;top:calc(100% - 4px);background:var(--bg-card);border:1px solid var(--border-subtle);border-radius:var(--r-sm);max-height:200px;overflow:auto;z-index:5;box-shadow:0 6px 20px rgba(0,0,0,.25)"></div>
        </div>
        <div id="madd-gara-picked" style="font-size:.78rem;color:var(--text-muted);margin:-4px 0 10px"></div>
        <div id="madd-stage-wrap" style="display:none">
          <label style="display:block;font-size:0.8rem;color:var(--text-secondary);margin-bottom:4px">Data della tappa</label>
          <input type="date" id="madd-stage-date" style="${inpStyle}"/>
          <div style="font-size:.72rem;color:var(--text-muted);margin:-4px 0 10px">Gara a tappe: nessun risultato pubblicato ancora per questa tappa — il link resta in attesa e si collega da solo appena la FCI pubblica i risultati di quel giorno.</div>
        </div>
      </div>
      <input type="url" id="madd-url" placeholder="https://www.youtube.com/watch?v=... oppure link Facebook" style="${inpStyle}"/>
      <input type="text" id="madd-title" placeholder="Titolo" style="${inpStyle}"/>
      <input type="text" id="madd-channel" placeholder="Canale" style="${inpStyle}"/>
      <div id="madd-err" style="color:#EF4444;font-size:0.8rem;margin-bottom:8px;display:none"></div>
      <button id="madd-btn" onclick="window._submitMediaAdd()" style="width:100%;padding:9px;background:var(--red-hot);color:#fff;border:none;border-radius:var(--r-sm);font-weight:600;cursor:pointer">Invia</button>
    </div>`;
  document.body.appendChild(overlay);
  window._maddGaraId = null;
  window._maddIsStage = false;
  // Auto-compila titolo/canale dall'URL via oEmbed, come nel form video normale
  document.getElementById('madd-url').addEventListener('input', function() {
    const url = this.value.trim();
    const vid = ytId(url);
    const isFb = isFacebookVideoUrl(url);
    if (!vid && !isFb) return;
    clearTimeout(window._maddOembedTimer);
    window._maddOembedTimer = setTimeout(async () => {
      try {
        const titleEl = document.getElementById('madd-title'), channelEl = document.getElementById('madd-channel');
        if (vid) {
          const d = await fetch(`https://www.youtube.com/oembed?url=${encodeURIComponent(url)}&format=json`).then(r => r.json());
          if (d.title && titleEl && !titleEl.value) titleEl.value = d.title;
          if (d.author_name && channelEl && !channelEl.value) channelEl.value = d.author_name;
        } else {
          const d = await apiCall(`/fb-video-meta?url=${encodeURIComponent(url)}`);
          if (d.title && titleEl && !titleEl.value) titleEl.value = d.title;
          if (d.channel && channelEl && !channelEl.value) channelEl.value = d.channel;
          // Link "condividi"/dirette /watch/live/?v=... non si incorporano nel
          // player pubblico: sostituisci con l'URL canonico risolto dal server.
          if (d.canonical_url) this.value = d.canonical_url;
        }
      } catch {}
    }, 600);
  });
};

window._maddSetTipo = (tipo) => {
  const wrap = document.getElementById('madd-gara-wrap');
  if (wrap) wrap.style.display = (tipo === 'gara' || tipo === 'diretta') ? '' : 'none';
};

window._maddSearchGara = (q) => {
  const dd = document.getElementById('madd-gara-dd');
  if (!dd) return;
  if (!q || q.trim().length < 2) { dd.style.display = 'none'; return; }
  const query = q.trim().toLowerCase();
  const matches = _ytAllRaceCandidates()
    .filter(r => (r.nome_gara || '').toLowerCase().includes(query))
    .slice(0, 15);
  if (!matches.length) { dd.innerHTML = '<div style="padding:8px;font-size:.78rem;color:var(--text-muted)">Nessuna gara trovata</div>'; dd.style.display = 'block'; return; }
  dd.innerHTML = matches.map(r => {
    const isStage = /tappe/i.test(r.categoria || '');
    const label = `${r.nome_gara}${isStage ? ' 🚵 A TAPPE' : ''} — ${r.categoria || ''} ${r.genere || ''} (${r.data || ''})`;
    return `<div style="padding:7px 10px;cursor:pointer;font-size:.8rem;border-bottom:1px solid var(--border-subtle)" onmousedown="window._maddPickGara('${esc(r.gara_id)}','${esc(label.replace(/'/g,"\\'"))}',${isStage})">${esc(label)}</div>`;
  }).join('');
  dd.style.display = 'block';
};

window._maddPickGara = (garaId, label, isStage) => {
  window._maddGaraId = garaId;
  window._maddIsStage = !!isStage;
  const picked = document.getElementById('madd-gara-picked');
  if (picked) picked.textContent = '✓ ' + label;
  const dd = document.getElementById('madd-gara-dd');
  if (dd) dd.style.display = 'none';
  const search = document.getElementById('madd-gara-search');
  if (search) search.value = '';
  const stageWrap = document.getElementById('madd-stage-wrap');
  if (stageWrap) stageWrap.style.display = isStage ? '' : 'none';
};

window._submitMediaAdd = async () => {
  const err = document.getElementById('madd-err');
  const btn = document.getElementById('madd-btn');
  err.style.display = 'none';
  const tipo    = document.getElementById('madd-tipo')?.value;
  const url     = document.getElementById('madd-url')?.value.trim();
  const title   = document.getElementById('madd-title')?.value.trim();
  const channel = document.getElementById('madd-channel')?.value.trim();
  if (!url) { err.textContent = 'Inserisci un URL YouTube o Facebook'; err.style.display = 'block'; return; }
  btn.disabled = true; btn.textContent = 'Invio…';
  try {
    if (tipo === 'gara' || tipo === 'diretta') {
      if (!window._maddGaraId) { err.textContent = 'Seleziona una gara'; err.style.display = 'block'; btn.disabled = false; btn.textContent = 'Invia'; return; }
      let targetGaraId = window._maddGaraId;
      if (window._maddIsStage) {
        const stageDate = document.getElementById('madd-stage-date')?.value;
        if (!stageDate) { err.textContent = 'Inserisci la data della tappa'; err.style.display = 'block'; btn.disabled = false; btn.textContent = 'Invia'; return; }
        // Chiave sintetica "{calendar_id}::{data tappa}" — processLoadedData la
        // ricollega da sola al gara_id reale appena la FCI pubblica i
        // risultati di quella tappa (stessa gara, stessa data).
        targetGaraId = `${window._maddGaraId}::${stageDate}`;
      }
      await apiCall('/videos/submit', { method: 'POST', body: { gara_id: targetGaraId, url, title, channel, is_live: tipo === 'diretta' } });
    } else {
      await apiCall('/admin/media/extra', { method: 'POST', body: { tipo, url, title, channel } });
    }
    document.getElementById('modal-overlay')?.remove();
    showToast('✓ Aggiunto!');
    await refreshVideos();
    renderMedia();
  } catch (e) { err.textContent = e.message; err.style.display = 'block'; btn.disabled = false; btn.textContent = 'Invia'; }
};

async function renderMedia(openOpts) {
  if (!globalData) return;
  await _loadLegacyViews();
  // Navigazione diretta a una scheda specifica (link condivisibile, vedi
  // route()) — gli openOpts.openXxx sotto possono comunque forzare una
  // scheda diversa se il contenuto condiviso vive altrove (es. un link a un
  // video di una presentazione forza "presentazioni" anche se tab=video).
  if (openOpts?.tab) mediaTab = openOpts.tab;
  if (openOpts?.tab !== 'creator') mediaChannelFilter = openOpts?.channel || '';
  if (openOpts?.creatorProfileId) _mediaCreatorProfileId = openOpts.creatorProfileId;
  const { calendar, resultsRaw, videos } = globalData;

  // Indice gara_id → metadati evento (nome/data/categoria/genere), da resultsRaw
  // e in fallback dal calendario per le gare senza risultati ancora scrapati.
  const evIndex = {};
  for (const r of (resultsRaw || [])) {
    if (!r.gara_id || evIndex[r.gara_id]) continue;
    evIndex[r.gara_id] = { nome: r.nome_gara, data: r.data, categoria: r.categoria, genere: r.genere, regione: r.regione };
  }
  for (const g of (calendar || [])) {
    if (!evIndex[g.id]) evIndex[g.id] = { nome: g.nome, data: g.data, categoria: g.categoria, genere: '', regione: g.regione };
  }
  // Un video/diretta collegato PRIMA dello scraping usa il gara_id del
  // calendario come chiave; una volta scrapata, la gara può ottenere un
  // gara_id diverso (suffissato per categoria/genere) che non coincide più con
  // nessuna chiave del calendario né con quella sotto cui il video è salvato —
  // senza questo fallback il video sparirebbe silenziosamente dalla pagina
  // Media (nessuna voce in evIndex = scartato). garaToCalId (calcolato in
  // processLoadedData) mappa gara_id scrapato → id calendario corrispondente:
  // lo usiamo al contrario per "prestare" i metadati reali anche alla chiave
  // calendario originale.
  for (const [realGaraId, calId] of Object.entries(globalData.garaToCalId || {})) {
    if (evIndex[realGaraId] && !evIndex[calId]) evIndex[calId] = evIndex[realGaraId];
  }

  // Bucket "virtuali" (non legati a nessuna gara): Presentazioni/Programmi TV/Altro.
  const EXTRA_BUCKETS = { presentazioni: '__PRESENTAZIONI__', programmi_tv: '__PROGRAMMI_TV__', altro: '__ALTRO__' };

  let videoItems = [];
  for (const [gid, arr] of Object.entries(videos || {})) {
    if (gid === EXTRA_BUCKETS.presentazioni || gid === EXTRA_BUCKETS.programmi_tv || gid === EXTRA_BUCKETS.altro) continue;
    // Se il gara_id non trova corrispondenza in evIndex (gara futura non
    // ancora nel calendario, id salvato a mano che non collima, ecc.) il
    // video/diretta NON va perso: si mostra comunque con i pochi dati che ha
    // (titolo del video), invece di sparire silenziosamente dalla pagina Media.
    let meta = evIndex[gid];
    if (!meta) {
      // Chiave sintetica "calId::data tappa" (tappa caricata in anticipo,
      // non ancora scrapata): recuperiamo la data DALLA CHIAVE stessa, così
      // l'ordinamento/filtro mese usa la data della tappa che l'admin ha
      // scelto a mano, non quella (spesso fuorviante) di pubblicazione su
      // YouTube — vedi criterio richiesto per i video inseriti manualmente.
      const stageMatch = gid.match(/::(\d{4}-\d{2}-\d{2})$/);
      meta = stageMatch ? { data: stageMatch[1] } : {};
    }
    (arr || []).forEach((v, idx) => videoItems.push({ gara_id: gid, idx, meta, video: v }));
  }
  const presentazioniItems = (videos?.[EXTRA_BUCKETS.presentazioni] || []).map((v, idx) => ({ video: v, extraIdx: idx }));
  const programmiTvItems   = (videos?.[EXTRA_BUCKETS.programmi_tv]   || []).map((v, idx) => ({ video: v, extraIdx: idx }));
  const altroItems         = (videos?.[EXTRA_BUCKETS.altro]         || []).map((v, idx) => ({ video: v, extraIdx: idx }));

  // Link diretto condiviso (vedi route()): trova la voce giusta fra TUTTI i
  // bucket (gare + presentazioni + programmi TV) e apre subito il player
  // sopra la pagina Media, mai su youtube.com/facebook.com — così un link
  // condiviso resta sempre sul nostro sito. mediaTab viene forzato di
  // conseguenza (Dirette per una diretta, altrimenti Video) prima di
  // costruire le liste sotto, così la scheda aperta corrisponde a quella
  // evidenziata nei chip in alto.
  if (openOpts) {
    const allBuckets = [
      ...videoItems.map(x => ({ ...x, _bucket: 'video' })),
      ...presentazioniItems.map(x => ({ ...x, _bucket: 'presentazione' })),
      ...programmiTvItems.map(x => ({ ...x, _bucket: 'programma_tv' })),
      ...altroItems.map(x => ({ ...x, _bucket: 'altro' })),
    ];
    if (openOpts.openLive) {
      const hit = videoItems.find(x => x.video.is_live && ytId(x.video.url) === openOpts.openLive);
      if (hit) { mediaTab = 'dirette'; setTimeout(() => window.openLivePlayer(openOpts.openLive, hit.video.title, hit.gara_id), 0); }
    } else if (openOpts.openVideo) {
      const hit = allBuckets.find(x => !x.video.is_live && ytId(x.video.url) === openOpts.openVideo);
      if (hit) {
        mediaTab = hit._bucket === 'presentazione' ? 'presentazioni'
          : hit._bucket === 'programma_tv' ? 'programmi_tv'
          : hit._bucket === 'altro' ? 'altro' : 'video';
        setTimeout(() => window.openVideoModal(openOpts.openVideo, hit.video.title || ''), 0);
      }
    } else if (openOpts.openFb) {
      const hit = videoItems.find(x => x.gara_id === openOpts.openFb.garaId && x.idx === openOpts.openFb.idx);
      if (hit) { mediaTab = hit.video.is_live ? 'dirette' : 'video'; setTimeout(() => window.openFacebookVideoModal(hit.video.url, hit.video.title || ''), 0); }
    } else if (openOpts.openFbExtra) {
      const hit = openOpts.openFbExtra.bucket === 'presentazione'
        ? presentazioniItems.find(x => x.extraIdx === openOpts.openFbExtra.idx)
        : openOpts.openFbExtra.bucket === 'programma_tv'
        ? programmiTvItems.find(x => x.extraIdx === openOpts.openFbExtra.idx)
        : altroItems.find(x => x.extraIdx === openOpts.openFbExtra.idx);
      if (hit) {
        mediaTab = openOpts.openFbExtra.bucket === 'presentazione' ? 'presentazioni'
          : openOpts.openFbExtra.bucket === 'programma_tv' ? 'programmi_tv' : 'altro';
        setTimeout(() => window.openFacebookVideoModal(hit.video.url, hit.video.title || ''), 0);
      }
    }
  }

  const applyFilters = (arr) => arr.filter(x => {
    if (mediaQueryGenere && x.meta?.genere && x.meta.genere !== mediaQueryGenere) return false;
    if (mediaQueryCat) {
      const c = x.meta ? (getRankingFileCode(x.meta) || x.meta.categoria) : null;
      if (c !== mediaQueryCat) return false;
    }
    if (mediaQueryMonth && x.meta?.data && x.meta.data.split('-')[1] !== mediaQueryMonth) return false;
    if (mediaSearchQuery) {
      const hay = `${x.meta?.nome || ''} ${x.video?.title || ''}`.toLowerCase();
      if (!hay.includes(mediaSearchQuery.toLowerCase())) return false;
    }
    return true;
  });

  // Ordine cronologico di pubblicazione su YouTube, dal più recente al più
  // vecchio (fallback sulla data della gara per video legacy senza published_at).
  // Eccezione: i video di una tappa caricati in anticipo (gara_id sintetico
  // "calId::data tappa") vanno ordinati sulla data della tappa scelta a mano,
  // non su published_at — stesso criterio delle Dirette, per coerenza.
  const byPublishedDesc = (a, b) => {
    // Presentazioni/Programmi TV non hanno gara_id (non collegati a nessuna
    // gara) — senza il controllo, .includes su undefined mandava in eccezione
    // l'intero sort e quindi tutta renderMedia(), lasciando la pagina bianca.
    const ka = (a.gara_id || '').includes('::') ? (a.meta?.data || a.video.published_at || '') : (a.video.published_at || a.meta?.data || '');
    const kb = (b.gara_id || '').includes('::') ? (b.meta?.data || b.video.published_at || '') : (b.video.published_at || b.meta?.data || '');
    return kb.localeCompare(ka);
  };
  // Le DIRETTE vanno ordinate per data della GARA (calendario), non di
  // pubblicazione YouTube: il video/link diretta viene spesso preparato e
  // caricato giorni prima che la gara si disputi davvero, quindi published_at
  // non riflette affatto quando si è svolta la gara.
  const byRaceDateDesc = (a, b) => (b.meta?.data || b.video.published_at || '').localeCompare(a.meta?.data || a.video.published_at || '');

  // Lo stesso video (stesso URL) può essere collegato a più gare — ancora
  // deve apparire su ciascuna delle rispettive pagine gara, ma nell'elenco
  // aggregato Video/Dirette deve comparire UNA volta sola, non una per gara
  // a cui è stato agganciato. Si tiene la prima occorrenza incontrata.
  {
    const seenUrls = new Set();
    videoItems = videoItems.filter(x => {
      const key = x.video?.url;
      if (!key) return true; // niente URL: non possiamo dedupare, teniamo tutto
      if (seenUrls.has(key)) return false;
      seenUrls.add(key);
      return true;
    });
  }
  videoItems = applyFilters(videoItems).sort(byPublishedDesc);
  // Tab "Video" e "Dirette" sono mutuamente esclusivi: una diretta non deve
  // comparire anche tra i video normali.
  const direteItemsAll = videoItems.filter(x => x.video.is_live).sort(byRaceDateDesc);
  const videoItemsAll  = videoItems.filter(x => !x.video.is_live);
  // Identità "reale" di un video legacy per il raggruppamento dei cerchietti:
  // - Facebook: sempre un unico bucket, indipendentemente dal testo salvato
  //   nel campo "channel" (spesso assente/generico per questi video).
  // - Se il nome del canale combacia (per parole intere o nome compattato)
  //   con un profilo Media già esistente, usa QUEL profilo come identità
  //   (nome+logo canonici) — stessa testata scritta in modi diversi
  //   (es. "BetaCycling"/"Beta Cycling") finisce così nello stesso cerchietto.
  //   Il logo usa il logo del profilo se presente, altrimenti quello salvato
  //   sul singolo video (molti profili "fotografo" scrapati non hanno mai
  //   avuto un logo proprio impostato).
  // - Altrimenti resta un'identità "per canale grezzo".
  // Il click filtra SEMPRE dentro la scheda (mai un link a una pagina
  // profilo: i video legacy non vivono lì, ci si troverebbe una pagina vuota).
  const _mvChannelIdentity = (video, allProfiles) => {
    if (isFacebookVideoUrl(video?.url)) return { key: '__FB__', label: 'Facebook', avatar: '', isFb: true };
    const ch = video?.channel;
    const matched = ch ? _matchChannelToProfile(ch, allProfiles) : null;
    if (matched) return { key: 'profile:' + matched.id, label: matched.display_name, avatar: (matched.cover_url ? mediaUrl(matched.cover_url) : '') || video.channel_avatar || '' };
    if (ch) return { key: 'channel:' + ch, label: ch, avatar: video.channel_avatar || '' };
    return { key: '__OTHER__', label: 'Altri', avatar: '', isOther: true };
  };
  // Video/Presentazioni/Programmi TV/Altro collassano anche tutto ciò che
  // NON combacia con un profilo (e non è Facebook) in un unico bucket
  // "Altri" — troppi cerchietti isolati era la fonte di confusione. Le
  // Dirette invece restano un cerchietto per ogni fonte distinta (sapere
  // esattamente chi trasmette conta di più lì), MA le varianti dello stesso
  // canale/profilo vengono comunque unite fra loro.
  const _mvGroupIdentity = (video, allProfiles, collapseOther) => {
    const id = _mvChannelIdentity(video, allProfiles);
    if (collapseOther && !id.isFb && !id.key.startsWith('profile:')) {
      return { key: '__OTHER__', label: 'Altri', avatar: '', isOther: true };
    }
    return id;
  };
  const _collapseOther = mediaTab !== 'dirette';
  const _allProfilesForFilter = mediaTab !== 'creator' ? await _ensureAllMediaProfiles() : [];
  const _chFilter = (arr) => !mediaChannelFilter ? arr
    : arr.filter(x => _mvGroupIdentity(x.video, _allProfilesForFilter, _collapseOther).key === mediaChannelFilter);
  videoItems  = _chFilter(videoItemsAll);
  let direteItems = _chFilter(direteItemsAll);
  // Data di oggi nel fuso delle gare (Italia), non UTC del browser — stesso
  // criterio usato server-side per il banner "IN DIRETTA ORA".
  const _todayStrMedia = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Rome' });
  // Le dirette di OGGI ancora effettivamente in corso e quelle future
  // ("prossimamente") vanno isolate in cima, prima di tutte le altre — che
  // restano nell'ordine cronologico già esistente (byRaceDateDesc) e in
  // QUELLA posizione ci tornano da sole il giorno dopo, quando smettono di
  // essere "di oggi". "is_live" è un flag statico impostato all'inserimento
  // e da solo NON riflette la fine reale della trasmissione — window._liveStatusToday
  // (aggiornato da _refreshLiveStatusToday, vedi sotto) dice per ogni video_id
  // se YouTube lo segna ancora realmente live: appena una diretta finisce,
  // sparisce da "In Diretta" e ricompare in "A seguire" senza aspettare il
  // giorno dopo.
  const _isEndedLive = (x) => {
    if (x.video.live_ended) return true; // segnata a mano (es. Facebook, niente rilevamento automatico)
    const vid = ytId(x.video.url);
    return vid && window._liveStatusToday && window._liveStatusToday[vid] === false;
  };
  const diretteOggi = direteItems.filter(x => x.meta?.data === _todayStrMedia && !_isEndedLive(x));
  const direttePros = direteItems
    .filter(x => x.meta?.data && x.meta.data > _todayStrMedia)
    .sort((a, b) => (a.meta.data || '').localeCompare(b.meta.data || '')); // più vicina prima
  const diretteResto = direteItems.filter(x =>
    !(x.meta?.data === _todayStrMedia && !_isEndedLive(x)) && !(x.meta?.data && x.meta.data > _todayStrMedia));
  if (mediaTab === 'dirette') _refreshLiveStatusToday();
  const presentazioniAll = applyFilters(presentazioniItems).sort(byPublishedDesc);
  const programmiTvAll   = applyFilters(programmiTvItems).sort(byPublishedDesc);
  const altroAll         = applyFilters(altroItems).sort(byPublishedDesc);
  const presentazioniFiltered = _chFilter(presentazioniAll);
  const programmiTvFiltered   = _chFilter(programmiTvAll);
  const altroFiltered         = _chFilter(altroAll);

  const items = mediaTab === 'dirette' ? direteItems
    : mediaTab === 'presentazioni' ? presentazioniFiltered
    : mediaTab === 'programmi_tv' ? programmiTvFiltered
    : mediaTab === 'altro' ? altroFiltered
    : videoItems;

  // Striscia cerchietti canale (solo per le schede con contenuti video
  // legacy — non per "creator", che ha già la sua): costruita dai canali
  // presenti nella scheda PRIMA del filtro (altrimenti, selezionandone uno,
  // la striscia collasserebbe a un solo cerchietto e non si potrebbe più
  // tornare indietro o sceglierne un altro). Il click filtra SEMPRE questa
  // scheda (mai un link a una pagina profilo, vedi _mvChannelIdentity sopra).
  // Un cerchietto "Tutti" sempre presente in cima toglie qualunque filtro.
  let mediaChannelsHtml = '';
  if (mediaTab !== 'creator') {
    // Ogni scheda mostra SOLO i canali che hanno davvero contenuti in QUELLA
    // scheda — itemsAll è scelto in base a mediaTab e non viene mai
    // "ricordato" da una scheda all'altra: cambiando scheda si ricalcola da
    // zero (nessuno stato condiviso fra Video/Dirette/Presentazioni/ecc.).
    const itemsAll = mediaTab === 'dirette' ? direteItemsAll
      : mediaTab === 'presentazioni' ? presentazioniAll
      : mediaTab === 'programmi_tv' ? programmiTvAll
      : mediaTab === 'altro' ? altroAll
      : videoItemsAll;
    const _tabUrl = MEDIA_TAB_KEY_TO_URL[mediaTab] || mediaTab;
    const allProfiles = _allProfilesForFilter.length ? _allProfilesForFilter : await _ensureAllMediaProfiles();
    const groups = new Map(); // groupKey -> { label, avatar, isFb, isOther }
    for (const x of itemsAll) {
      const id = _mvGroupIdentity(x.video, allProfiles, _collapseOther);
      if (!groups.has(id.key)) groups.set(id.key, id);
    }

    const groupsList = [...groups.values()].sort((a, b) => a.label.localeCompare(b.label));
    if (groupsList.length > 1) {
      // href reale (non un onclick a parte): il gestore globale dei click
      // interni intercetta questi <a> e naviga con navTo(), aggiornando
      // davvero la barra indirizzi — così il link è copiabile/condivisibile.
      // I cerchietti hanno la stessa dimensione di quelli della tab Creator (56px).
      // "Tutti" in cima toglie qualunque filtro attivo nella scheda.
      const allEntry = { key: '', label: 'Tutti', avatar: '', isAll: true };
      mediaChannelsHtml = `
        <div style="display:flex;gap:14px;overflow-x:auto;padding:4px 2px 12px">
          ${[allEntry, ...groupsList].map(g => {
            const active = mediaChannelFilter === g.key;
            const href = active || g.isAll ? `#/media/${_tabUrl}` : `#/media/${_tabUrl}/canale/${encodeURIComponent(g.key)}`;
            return `<a href="${href}" style="text-decoration:none;display:flex;flex-direction:column;align-items:center;gap:6px;flex:0 0 auto;width:64px">
              <div style="width:56px;height:56px;border-radius:50%;overflow:hidden;background:var(--bg-base);border:2px solid ${active ? 'var(--accent)' : 'var(--border-subtle)'};display:flex;align-items:center;justify-content:center;font-size:1.3rem">
                ${g.isAll ? '🗂️' : g.isFb ? '📘' : g.isOther ? '🎬' : (g.avatar ? `<img src="${esc(g.avatar)}" style="width:100%;height:100%;object-fit:cover"/>` : '🎬')}
              </div>
              <span style="font-size:.68rem;color:var(--text-secondary);text-align:center;line-height:1.2;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:64px">${esc(g.label)}</span>
            </a>`;
          }).join('')}
        </div>`;
    }
  }

  const allCatsSet = new Set();
  [...videoItems, ...direteItems].forEach(x => { const c = getRankingFileCode(x.meta) || x.meta.categoria; if (c) allCatsSet.add(c); });
  const allCats = [...allCatsSet].sort();

  const ytThumb = (url) => { const id = ytId(url); return id ? `https://img.youtube.com/vi/${id}/mqdefault.jpg` : ''; };
  const _avatarLetter = (s) => esc((s || '?').trim().charAt(0).toUpperCase());
  // Logo reale del canale se lo conosciamo (fetchato via YouTube Data API al
  // momento dell'inserimento), altrimenti ricade sull'iniziale colorata.
  const _avatarHtml = (video) => video.channel_avatar
    ? `<img class="yt-avatar" src="${esc(video.channel_avatar)}" alt="${esc(video.channel || '')}" loading="lazy"/>`
    : `<div class="yt-avatar">${_avatarLetter(video.channel)}</div>`;
  const _durationBadge = (sec) => {
    if (!sec) return '';
    const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60);
    return h > 0 ? `${h}:${String(m).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}` : `${m}:${String(sec%60).padStart(2,'0')}`;
  };
  const _isAdminMedia = authUser()?.role === 'admin';

  // URL diretto e condivisibile per una card (vedi route(), match /media/live|video|fb|fbextra):
  // apre sempre il player DENTRO al nostro sito, mai su youtube.com/facebook.com.
  // Per i video YouTube si passa dal proxy /og/media-live|video/:id (vedi
  // server.js) invece del link pulito diretto: incollato su Facebook/WhatsApp
  // il link pulito verrebbe letto dal crawler come una pagina SPA vuota
  // (GitHub Pages è statico, niente JS eseguito) e mostrerebbe nessuna
  // copertina — il proxy risponde con i meta tag/copertina YouTube reali ai
  // bot e rimanda un utente vero dritto alla pagina Media pulita (stesso
  // pattern già usato per gara/atleta/team, vedi /og/gara/:id).
  const _mediaShareUrl = (x, bucketKey) => {
    const vid = ytId(x.video.url);
    if (vid) return `https://italiacyclingstats.com/og/media-${x.video.is_live ? 'live' : 'video'}/${encodeURIComponent(vid)}`;
    if (isFacebookVideoUrl(x.video.url)) {
      return bucketKey
        ? `${location.origin}/media/fbextra/${bucketKey}/${x.extraIdx}`
        : `${location.origin}/media/fb/${encodeURIComponent(x.gara_id)}/${x.idx}`;
    }
    return x.video.url; // nessun player integrato possibile: condivide il link esterno originale
  };
  const shareBtnHtml = (x, bucketKey) => {
    const url = esc(_mediaShareUrl(x, bucketKey));
    const t = esc((x.video.title || '').replace(/'/g, "\\'"));
    return `<button class="yt-share-btn" title="Condividi"
      onclick="event.preventDefault();event.stopPropagation();window.shareBattle('${url}','${t}')">
      <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/>
        <line x1="8.6" y1="10.5" x2="15.4" y2="6.5"/><line x1="8.6" y1="13.5" x2="15.4" y2="17.5"/>
      </svg>
    </button>`;
  };
  const videoCardHtml = (x) => {
    const thumb = ytThumb(x.video.url);
    const durBadge = _durationBadge(x.video.duration_seconds);
    const selKey = `${x.gara_id}::${x.idx}`;
    const isSel = (window._mediaSel || new Set()).has(selKey);
    // Video di una tappa caricato in anticipo (chiave sintetica "calId::data",
    // vedi window._maddSubmitStageVideo): il gara_id NON è ancora una gara
    // reale, quindi non deve linkare a una pagina /gara/ inesistente — si apre
    // direttamente il player, come per Presentazioni/Programmi TV.
    const isPending = x.gara_id.includes('::');
    const pendingBadge = isPending ? `<span class="yt-badge-duration" style="left:6px;right:auto">⏳ IN ATTESA TAPPA</span>` : '';
    const t = esc((x.video.title || '').replace(/'/g, "\\'"));
    const vid = ytId(x.video.url);
    const pendingOnclick = vid
      ? `window.openVideoModal('${vid}','${t}')`
      : isFacebookVideoUrl(x.video.url)
        ? `window.openFacebookVideoModal('${esc(x.video.url)}','${t}')`
        : `window.open('${esc(x.video.url)}','_blank')`;
    // Diretta in corso: apre il player persistente (minimizzabile, resta
    // in riproduzione navigando altrove) invece di andare sulla pagina
    // della gara — vale sia per una gara già reale sia per una tappa ancora
    // in attesa (chiave sintetica), a differenza di un video normale/VOD
    // "in attesa tappa" per cui il vecchio player usa e getta va benissimo.
    // Il player persistente (minimizzabile/mini-player) è costruito attorno
    // all'API YouTube (rilevamento diretta, notifiche): una diretta Facebook
    // non ha quell'infrastruttura, quindi si apre col modale semplice.
    const isLive = !!x.video.is_live;
    const liveOnclick = vid ? `window.openLivePlayer('${vid}','${t}','${esc(x.gara_id)}')` : pendingOnclick;
    const tag = (isPending || isLive) ? 'div' : 'a';
    const viewKey = esc(x.video.url || '');
    const incrCall = `window._legacyIncrView('${viewKey}');`;
    const hrefAttr = isLive ? `onclick="${incrCall}${liveOnclick}" style="cursor:pointer"`
      : isPending ? `onclick="${incrCall}${pendingOnclick}" style="cursor:pointer"`
      : `href="#/gara/${esc(x.gara_id)}" onclick="${incrCall}"`;
    return `<${tag} ${hrefAttr} class="yt-card${isSel ? ' yt-card-selected' : ''}">
      <div class="yt-thumb">
        ${_isAdminMedia ? `<input type="checkbox" class="yt-card-check" ${isSel ? 'checked' : ''}
          onclick="event.preventDefault();event.stopPropagation();window._mediaToggleSel('${esc(selKey)}',this.checked)"
          aria-label="Seleziona per correggere destinazione"/>` : ''}
        ${thumb ? `<img src="${esc(thumb)}" loading="lazy" alt="${esc(x.video.title || '')}"/>`
          : isFacebookVideoUrl(x.video.url) ? fbThumbHtml(x.video.url)
          : `<div class="yt-thumb-fallback">▶</div>`}
        ${pendingBadge}
        ${x.video.is_live ? `<span class="yt-badge-live">🔴 DIRETTA</span>` : (durBadge ? `<span class="yt-badge-duration">${esc(durBadge)}</span>` : '')}
        ${shareBtnHtml(x)}
        <span class="yt-play">▶</span>
      </div>
      <div class="yt-card-body">
        ${_avatarHtml(x.video)}
        <div class="yt-card-text">
          <div class="yt-card-title">${esc(x.video.title || x.meta.nome || 'Video')}</div>
          <div class="yt-card-meta">${esc(x.video.channel || '')}</div>
          <div class="yt-card-meta">${esc((x.meta.data || x.video.published_at) ? formatTimeAgo(x.meta.data || x.video.published_at) : '')} <span style="margin-left:6px">👁 ${_legacyViews[x.video.url] || 0}</span></div>
        </div>
      </div>
    </${tag}>`;
  };
  // Presentazioni/Programmi TV: nessuna gara collegata, il click apre
  // direttamente il video (stesso player modale usato altrove) invece di
  // navigare a una pagina gara che non esiste per questi contenuti.
  const extraVideoCardHtml = (bucketKey) => (x) => {
    const thumb = ytThumb(x.video.url);
    const t = esc((x.video.title || '').replace(/'/g, "\\'"));
    const vid = ytId(x.video.url);
    const viewKey = esc(x.video.url || '');
    const onclick = `window._legacyIncrView('${viewKey}');` + (vid ? `window.openVideoModal('${vid}','${t}')` : `window.open('${esc(x.video.url)}','_blank')`);
    return `<div class="yt-card" onclick="${onclick}" style="cursor:pointer">
      <div class="yt-thumb">
        ${thumb ? `<img src="${esc(thumb)}" loading="lazy" alt="${esc(x.video.title || '')}"/>`
          : isFacebookVideoUrl(x.video.url) ? fbThumbHtml(x.video.url)
          : `<div class="yt-thumb-fallback">▶</div>`}
        <span class="yt-play">▶</span>
        ${shareBtnHtml(x, bucketKey)}
        ${_isAdminMedia ? `<button onclick="event.stopPropagation();window.mediaDeleteExtra('${bucketKey}',${x.extraIdx})" style="position:absolute;top:6px;right:6px;background:rgba(220,38,38,.92);color:#fff;border:none;padding:3px 8px;border-radius:4px;font-size:.68rem;cursor:pointer;z-index:3">🗑</button>` : ''}
      </div>
      <div class="yt-card-body">
        ${_avatarHtml(x.video)}
        <div class="yt-card-text">
          <div class="yt-card-title">${esc(x.video.title || '')}</div>
          <div class="yt-card-meta">${esc(x.video.channel || '')}</div>
          <div class="yt-card-meta">${esc(formatTimeAgo(x.video.published_at))} <span style="margin-left:6px">👁 ${_legacyViews[x.video.url] || 0}</span></div>
        </div>
      </div>
    </div>`;
  };
  const cardHtml = mediaTab === 'presentazioni' ? extraVideoCardHtml('presentazione')
    : mediaTab === 'programmi_tv' ? extraVideoCardHtml('programma_tv')
    : mediaTab === 'altro' ? extraVideoCardHtml('altro')
    : videoCardHtml;

  const _showRaceFilters = mediaTab === 'video' || mediaTab === 'dirette';

  const MEDIA_TAB_META = {
    video: ['Media — Video', 'Video delle gare di ciclismo agonistico italiano.'],
    dirette: ['Media — Dirette', 'Dirette streaming delle gare di ciclismo agonistico italiano.'],
    presentazioni: ['Media — Presentazioni', 'Presentazioni delle gare di ciclismo agonistico italiano.'],
    programmi_tv: ['Media — Programmi TV', 'Programmi TV sul ciclismo agonistico italiano.'],
    altro: ['Media — Altro', 'Altri contenuti video sul ciclismo agonistico italiano.'],
    creator: ['Media — Creator', 'I creator che pubblicano video sul ciclismo agonistico italiano.'],
  };
  const [_mediaMetaTitle, _mediaMetaDesc] = MEDIA_TAB_META[mediaTab] || ['Media', 'Video, dirette, presentazioni e programmi TV delle gare di ciclismo agonistico italiano.'];
  setPageMeta(_mediaMetaTitle, _mediaMetaDesc);
  setPage(`
    <div class="content-wrapper">
      <div class="section-header">
        <h1 style="font-family:var(--font-display);font-size:var(--size-h1);margin-bottom:0">Media</h1>
        <span class="section-line"></span>
      </div>
    </div>
    <div class="yt-page">
      <div class="yt-chips">
        <button class="yt-chip ${mediaTab === 'video' ? 'yt-chip-active' : ''}" onclick="window.mediaSetTab('video')">🎬 Video <span class="yt-chip-count">${videoItems.length}</span></button>
        <button class="yt-chip ${mediaTab === 'dirette' ? 'yt-chip-active' : ''}" onclick="window.mediaSetTab('dirette')">🔴 Dirette <span class="yt-chip-count">${direteItems.length}</span></button>
        <button class="yt-chip ${mediaTab === 'presentazioni' ? 'yt-chip-active' : ''}" onclick="window.mediaSetTab('presentazioni')">🎤 Presentazioni <span class="yt-chip-count">${presentazioniFiltered.length}</span></button>
        <button class="yt-chip ${mediaTab === 'programmi_tv' ? 'yt-chip-active' : ''}" onclick="window.mediaSetTab('programmi_tv')">📺 Programmi TV <span class="yt-chip-count">${programmiTvFiltered.length}</span></button>
        <button class="yt-chip ${mediaTab === 'altro' ? 'yt-chip-active' : ''}" onclick="window.mediaSetTab('altro')">🎬 Altro <span class="yt-chip-count">${altroFiltered.length}</span></button>
        <button class="yt-chip ${mediaTab === 'creator' ? 'yt-chip-active' : ''}" onclick="window.mediaSetTab('creator')">🧑‍🎨 Creator</button>
        <span class="yt-chip-sep"></span>
        ${_showRaceFilters ? `
        <select class="yt-chip yt-chip-select" onchange="window.mediaSetGenere(this.value)">
          <option value="">Tutti i generi</option>
          <option value="M" ${mediaQueryGenere === 'M' ? 'selected' : ''}>Uomini</option>
          <option value="F" ${mediaQueryGenere === 'F' ? 'selected' : ''}>Donne</option>
        </select>
        <select class="yt-chip yt-chip-select" onchange="window.mediaSetCat(this.value)">
          <option value="">Tutte le categorie</option>
          ${allCats.map(c => `<option value="${esc(c)}" ${c === mediaQueryCat ? 'selected' : ''}>${esc(catLabel(c) || c)}</option>`).join('')}
        </select>
        <select class="yt-chip yt-chip-select" onchange="window.mediaSetMonth(this.value)">
          <option value="">Tutti i mesi</option>
          ${['01','02','03','04','05','06','07','08','09','10','11','12'].map((m, i) =>
            `<option value="${m}" ${m === mediaQueryMonth ? 'selected' : ''}>${['Gennaio','Febbraio','Marzo','Aprile','Maggio','Giugno','Luglio','Agosto','Settembre','Ottobre','Novembre','Dicembre'][i]}</option>`
          ).join('')}
        </select>` : ''}
        ${mediaTab !== 'creator' ? `
        <div class="yt-search-wrap">
          <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
          <input type="text" placeholder="Cerca…" oninput="window.mediaSetSearch(this.value)" value="${esc(mediaSearchQuery)}">
        </div>
        ${_isAdminMedia ? `<button class="yt-chip" style="background:var(--red-hot);color:#fff;border-color:var(--red-hot)" onclick="window.openMediaAddForm()">➕ Aggiungi</button>` : ''}
        ${_isAdminMedia ? `<button class="yt-chip" onclick="window.mediaBackfillMetadata(this)">🔄 Ricalcola date/loghi</button>` : ''}` : ''}
      </div>
      ${mediaChannelsHtml}
      ${_isAdminMedia && _showRaceFilters && (window._mediaSel || new Set()).size ? `
      <div class="yt-bulk-bar">
        <span>${(window._mediaSel || new Set()).size} selezionati</span>
        <button onclick="window._mediaBulkSetLive(true)">🔴 Segna come Diretta</button>
        <button onclick="window._mediaBulkSetEnded()">🏁 Diretta terminata</button>
        <button onclick="window._mediaBulkSetLive(false)">🎬 Segna come Video normale</button>
        <button class="yt-bulk-clear" onclick="window._mediaClearSel()">Annulla selezione</button>
      </div>` : ''}
      ${mediaTab === 'creator' ? `
        <div id="media-creator-area"><div class="admin-loading">Caricamento…</div></div>
      ` : mediaTab === 'dirette' ? `
        ${diretteOggi.length ? `
          <div class="yt-group-hdr"><span class="yt-group-dot"></span>IN DIRETTA <span class="yt-chip-count">${diretteOggi.length}</span></div>
          <div class="yt-grid">${diretteOggi.map(cardHtml).join('')}</div>
        ` : ''}
        ${direttePros.length ? `
          <div class="yt-group-hdr">📅 PROSSIMAMENTE <span class="yt-chip-count">${direttePros.length}</span></div>
          <div class="yt-grid">${direttePros.map(cardHtml).join('')}</div>
        ` : ''}
        ${diretteOggi.length || direttePros.length ? `<div class="yt-group-hdr">TUTTE LE DIRETTE</div>` : ''}
        <div class="yt-grid">
          ${diretteResto.length ? diretteResto.map(cardHtml).join('') : (!diretteOggi.length && !direttePros.length ? `<p style="color:var(--text-muted);padding:24px 4px">Nessun elemento trovato.</p>` : '')}
        </div>
      ` : `
        <div class="yt-grid">
          ${items.length ? items.map(cardHtml).join('') : `<p style="color:var(--text-muted);padding:24px 4px">Nessun elemento trovato.</p>`}
        </div>
      `}
    </div>
  `);
  if (mediaTab === 'creator') window._loadMediaCreatorArea();
}

async function _getLogo() {
  if (_shareLogoImg) return _shareLogoImg;
  return new Promise(res => {
    const img = new Image(); img.crossOrigin = 'anonymous';
    img.onload = () => { _shareLogoImg = img; res(img); };
    img.onerror = () => res(null);
    img.src = 'assets/logo.png?v=3';
  });
}

// Vero quando la foto è di xpix.it — sia per le foto prese in automatico
// dall'album scrapato (photo_source==='xpix') sia per una foto CARICATA A
// MANO il cui campo fotografo contiene "xpix" in qualunque forma (es. "Xpix
// (Valerio Pagni)"): un admin scrive quel credit per attribuire la foto a
// xpix.it anche quando non viene dall'album automatico, e deve comunque
// mostrare il loro logo, non solo il testo.
function _isXpixCredit(d) {
  return d?.photo_source === 'xpix' || /xpix/i.test(d?.photo_credit || '');
}

// Logo xpix.it (badge tondo bianco, sfondo trasparente) da affiancare al
// logo ICS nelle grafiche di condivisione quando la foto viene da lì.
let _xpixLogoImg = null;
async function _getXpixLogo() {
  if (_xpixLogoImg) return _xpixLogoImg;
  return new Promise(res => {
    const img = new Image(); img.crossOrigin = 'anonymous';
    img.onload = () => { _xpixLogoImg = img; res(img); };
    img.onerror = () => res(null);
    img.src = 'assets/xpix-logo.png?v=1';
  });
}

// ── Helper tempo gara ─────────────────────────────────────────────────────
// Calcola il tempo del vincitore da km e media (km/h) → "4h 19'18\""
function _calcWinnerTime(km, media) {
  const k = parseFloat(km), m = parseFloat(media);
  if (!k || !m) return '';
  const totalSec = Math.round(k / m * 3600);
  const h = Math.floor(totalSec / 3600);
  const min = Math.floor((totalSec % 3600) / 60);
  const sec = totalSec % 60;
  const mm = String(min).padStart(2,'0');
  const ss = String(sec).padStart(2,'0');
  return h > 0 ? `${h}h ${mm}'${ss}"` : `${mm}'${ss}"`;
}
// Pulisce il distacco FCI "a 14\"" → "+14\"" / "a 1'55\"" → "+1'55\""
function _fmtGap(tempo) {
  if (!tempo || !tempo.trim()) return '';
  return tempo.trim().replace(/^a\s*/, '+');
}
// Tempo vincitore in secondi (da km e media)
function _winnerSeconds(km, media) {
  const k = parseFloat(km), m = parseFloat(media);
  if (!k || !m) return 0;
  return k / m * 3600;
}
// Parsa il distacco FCI in secondi: "a 14\"" → 14, "a 1'55\"" → 115, "a 3'02\"" → 182
function _parseGapSeconds(tempo) {
  if (!tempo) return 0;
  const t = String(tempo).replace(/^a\s*/, '').trim();
  // formato m'ss" oppure ss"
  const mMin = t.match(/(\d+)\s*'/);
  const mSec = t.match(/(\d+)\s*"/);
  let sec = 0;
  if (mMin) sec += parseInt(mMin[1], 10) * 60;
  if (mSec) sec += parseInt(mSec[1], 10);
  // se non c'è né ' né " ma c'è un numero puro, trattalo come secondi
  if (!mMin && !mSec) { const n = parseInt(t, 10); if (!isNaN(n)) sec = n; }
  return sec;
}
// Media reale di un corridore = km / (tempoVincitore + distacco) * 3600
function _realAvgSpeed(km, winnerSec, gapSec) {
  const k = parseFloat(km);
  if (!k || !winnerSec) return null;
  const totalSec = winnerSec + (gapSec || 0);
  if (totalSec <= 0) return null;
  return k / (totalSec / 3600);
}

function _bg(ctx, W, H) {
  // ── Stile Velon: dark pulito, flat, data-forward ──
  // Base quasi-nera con leggerissimo gradiente verticale
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#0c0e12'); g.addColorStop(0.6, '#0a0c10'); g.addColorStop(1, '#070809');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  // Soft glow accent in alto a destra (molto tenue)
  const rg = ctx.createRadialGradient(W * 0.92, -H * 0.05, 0, W * 0.92, -H * 0.05, W * 0.95);
  rg.addColorStop(0, 'rgba(232,0,29,0.10)'); rg.addColorStop(1, 'transparent');
  ctx.fillStyle = rg; ctx.fillRect(0, 0, W, H);
  // Sottile filo accento sul bordo sinistro (brand, discreto)
  ctx.fillStyle = '#e8001d'; ctx.fillRect(0, 0, Math.max(3, Math.round(W * 0.005)), H);
}

// Stesso trattamento della card gara "foto intera" lato server
// (buildGaraResultOverlaySvg): la foto riempie tutto il riquadro, un
// degradé scuro la rende leggibile sotto il testo esistente (già bianco/
// chiaro, pensato per lo sfondo quasi-nero di _bg — funziona identico sopra
// questo degradé, nessuna riscrittura del resto del disegno). Sostituisce
// _bg quando una foto è disponibile, per qualunque formato (quadrato,
// story, ecc.), non solo per Facebook.
// Rettangolo sorgente per un ritaglio "cover" di img in un riquadro W×H,
// con zoom/spostamento manuali opzionali (adjust, vedi _shareImgAdjust):
// scale>1 = zoom in (inquadra meno immagine), offsetX/Y in pixel canvas
// spostano il punto inquadrato. Clippato per non uscire mai dai bordi
// dell'immagine sorgente.
function _photoCoverRect(img, W, H, adjust) {
  const { scale = 1, offsetX = 0, offsetY = 0 } = adjust || {};
  const ir = img.naturalWidth / img.naturalHeight, cr = W / H;
  let baseSw, baseSh;
  if (ir > cr) { baseSh = img.naturalHeight; baseSw = baseSh * cr; }
  else { baseSw = img.naturalWidth; baseSh = baseSw / cr; }
  // Un ritaglio "cover" puro (scale=1) spesso non lascia NESSUN margine per
  // spostare l'inquadratura sull'asse già al limite (es. foto larga appena
  // quanto basta) — lo zoom minimo di sicurezza (1.12) garantisce sempre un
  // po' di margine da trascinare, anche a zoom "100%" sullo slider, senza un
  // salto visibile (il margine è piccolo, quasi impercettibile finché non
  // si trascina davvero).
  const s = Math.max(1.12, scale);
  let sw = baseSw / s, sh = baseSh / s;
  let sx = (img.naturalWidth - baseSw) / 2 + (baseSw - sw) / 2 - offsetX * (baseSw / W);
  let sy = (img.naturalHeight - baseSh) / 2 + (baseSh - sh) / 2 - offsetY * (baseSh / H);
  sx = Math.max(0, Math.min(sx, img.naturalWidth - sw));
  sy = Math.max(0, Math.min(sy, img.naturalHeight - sh));
  return { sx, sy, sw, sh };
}

// Stesso trattamento della card gara "foto intera" lato server
// (buildGaraResultOverlaySvg): la foto riempie tutto il riquadro, un
// degradé scuro la rende leggibile sotto il testo esistente (già bianco/
// chiaro, pensato per lo sfondo quasi-nero di _bg — funziona identico sopra
// questo degradé, nessuna riscrittura del resto del disegno). Sostituisce
// _bg quando una foto è disponibile, per qualunque formato (quadrato,
// story, ecc.), non solo per Facebook.
function _bgPhoto(ctx, W, H, img, adjust) {
  const { sx, sy, sw, sh } = _photoCoverRect(img, W, H, adjust);
  ctx.drawImage(img, sx, sy, sw, sh, 0, 0, W, H);
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, 'rgba(0,0,0,0.55)');
  g.addColorStop(0.35, 'rgba(0,0,0,0.55)');
  g.addColorStop(0.6, 'rgba(0,0,0,0.78)');
  g.addColorStop(1, 'rgba(0,0,0,0.93)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = '#e8001d'; ctx.fillRect(0, 0, Math.max(3, Math.round(W * 0.005)), H);
}

// Variante per la card "Vincitore": il testo occupa solo la parte bassa
// (nome vincitore + nome gara + logo), quindi la foto resta chiara e ben
// visibile su gran parte del riquadro, scurita solo dove serve.
function _bgPhotoBottom(ctx, W, H, img, adjust) {
  const { sx, sy, sw, sh } = _photoCoverRect(img, W, H, adjust);
  ctx.drawImage(img, sx, sy, sw, sh, 0, 0, W, H);
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.55, 'rgba(0,0,0,0)');
  g.addColorStop(0.72, 'rgba(0,0,0,0.55)');
  g.addColorStop(1, 'rgba(0,0,0,0.90)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
}
function _header(ctx, logo, W, H, classData, topRightCat) {
  // ── Stile Velon: header flat, niente barra scura, logo che siede sul fondo dark ──
  const bH = Math.round(H * 0.092);
  // Logo ITC grande
  let logoRight = 18;
  if (logo) {
    const lH = Math.round(bH * 0.76), lW = Math.round(lH * logo.naturalWidth / logo.naturalHeight);
    ctx.drawImage(logo, 18, Math.round((bH - lH) / 2), lW, lH);
    logoRight = 18 + lW;
  }
  const isRegio = classData && classData.scope === 'regionale' && classData.region;
  // ── Wordmark accanto al logo: solo per le card classifica (regione o ICS).
  //    Per atleta/team niente wordmark (il logo dice già ICS). ──
  if (classData) {
    const brand = isRegio ? classData.region.toUpperCase() : 'ICS';
    ctx.fillStyle = 'rgba(255,255,255,0.16)';
    ctx.fillRect(logoRight + 16, Math.round(bH * 0.28), 2, Math.round(bH * 0.44));
    const wfs = Math.round(bH * 0.30);
    ctx.font = `700 ${wfs}px 'Inter Tight',sans-serif`;
    ctx.letterSpacing = '1px';
    ctx.fillStyle = isRegio ? '#f5c400' : 'rgba(255,255,255,0.90)';
    ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.fillText(brand, logoRight + 30, Math.round(bH * 0.52));
    ctx.textBaseline = 'alphabetic'; ctx.letterSpacing = '0px';
  }

  if (classData) {
    // ── A destra: "CLASSIFICA <categoria>" (+ mese se filtrato) ──
    const lblFs = Math.round(bH * 0.24);
    ctx.textAlign = 'right';
    const catTxt = (classData.catLabel || '').toUpperCase();
    // categoria (bianca) + label "CLASSIFICA" (muted), su stessa baseline
    const baseY = classData.month ? Math.round(bH * 0.46) : Math.round(bH * 0.58);
    ctx.font = `700 ${lblFs}px 'Inter Tight',sans-serif`; ctx.fillStyle = '#f2f2f2';
    ctx.fillText(catTxt, W - 18, baseY);
    const catW = ctx.measureText(catTxt).width;
    ctx.font = `500 ${lblFs}px 'Inter Tight',sans-serif`; ctx.fillStyle = 'rgba(255,255,255,0.42)';
    ctx.letterSpacing = '1px';
    ctx.fillText('CLASSIFICA ', W - 18 - catW - 10, baseY);
    ctx.letterSpacing = '0px';
    if (classData.month) {
      ctx.font = `600 ${Math.round(lblFs * 0.78)}px 'Inter Tight',sans-serif`;
      ctx.fillStyle = '#f5c400';
      ctx.fillText(classData.month.toUpperCase(), W - 18, Math.round(bH * 0.80));
    }
    ctx.textAlign = 'left';
  } else if (topRightCat) {
    // atleta / team: categoria in alto a destra (al posto di ICS + sito)
    const fs = Math.round(bH * 0.30);
    ctx.font = `700 ${fs}px 'Inter Tight',sans-serif`;
    ctx.letterSpacing = '1px';
    ctx.fillStyle = '#e8001d';
    ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
    ctx.fillText(topRightCat.toUpperCase(), W - 18, Math.round(bH * 0.52));
    ctx.letterSpacing = '0px'; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  }
  // Filo divisorio discreto
  ctx.fillStyle = 'rgba(255,255,255,0.06)'; ctx.fillRect(0, bH, W, 1);
}
// ── Disegna le 3 icone social nel footer (Instagram, Facebook, Sito) ──
// Usa i glifi SVG ufficiali (da _SVGS) via Path2D, scalati nel box sz×sz.
function _drawSocialIcons(ctx, cx, cy, sz, color) {
  const dOf = key => { const m = /\bd="([^"]+)"/.exec(_SVGS[key] || ''); return m ? m[1] : null; };
  const drawSvg = (key, x, y) => {
    const d = dOf(key);
    if (!d || typeof Path2D === 'undefined') return false;
    ctx.save();
    ctx.translate(x, y); ctx.scale(sz / 24, sz / 24);
    ctx.fillStyle = color;
    try { ctx.fill(new Path2D(d), 'evenodd'); } catch (e) { ctx.restore(); return false; }
    ctx.restore();
    return true;
  };
  const drawGlobe = (x, y) => {
    ctx.save();
    ctx.strokeStyle = color; ctx.lineWidth = Math.max(1.5, sz * 0.07);
    const r = sz / 2, mx = x + r, my = y + r;
    ctx.beginPath(); ctx.arc(mx, my, r, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x, my); ctx.lineTo(x + sz, my); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(mx, y); ctx.lineTo(mx, y + sz); ctx.stroke();
    ctx.beginPath(); ctx.ellipse(mx, my, r * 0.52, r, 0, 0, Math.PI * 2); ctx.stroke();
    ctx.restore();
  };
  const items = [
    (x, y) => drawSvg('instagram', x, y),
    (x, y) => drawSvg('facebook', x, y),
    (x, y) => drawGlobe(x, y),
  ];
  const gap = sz * 1.7;
  const totalW = gap * (items.length - 1);
  let x = cx - totalW / 2 - sz / 2;
  const y = cy - sz / 2;
  items.forEach((draw) => { draw(x, y); x += gap; });
  ctx.textAlign = 'left';
}
function _footer(ctx, W, H) {
  // ── Stile Velon: footer minimale, niente barra scura ──
  const fH = Math.round(H * 0.06); const y = H - fH;
  // linea divisoria sottile
  ctx.fillStyle = 'rgba(255,255,255,0.07)'; ctx.fillRect(0, y, W, 1);
  // micro accento tricolore (sobrio, in basso a sinistra)
  const s = 2, accW = Math.round(W * 0.018), ax = Math.round(W * 0.012), ay = y + Math.round(fH * 0.42);
  ctx.fillStyle = '#009246'; ctx.fillRect(ax, ay, accW, s);
  ctx.fillStyle = '#f0f0ee'; ctx.fillRect(ax + accW, ay, accW, s);
  ctx.fillStyle = '#ce2b37'; ctx.fillRect(ax + accW * 2, ay, accW, s);
  // ── Icone social al centro: Instagram · Facebook · Sito ──
  _drawSocialIcons(ctx, W / 2, y + Math.round(fH * 0.50), Math.round(fH * 0.40), 'rgba(255,255,255,0.55)');
  // handle a destra
  ctx.font = `500 ${Math.round(fH * 0.30)}px 'Inter Tight',sans-serif`;
  ctx.fillStyle = 'rgba(255,255,255,0.32)'; ctx.textAlign = 'right';
  ctx.fillText('@italiacrit', W - Math.round(W * 0.012), y + Math.round(fH * 0.66));
  ctx.textAlign = 'left';
}
function _wrap(ctx, txt, x, y, maxW, lH) {
  const words=txt.split(' '); let line='';
  for(const w of words){
    const t=line?line+' '+w:w;
    if(ctx.measureText(t).width>maxW&&line){ctx.fillText(line,x,y);y+=lH;line=w;}
    else line=t;
  }
  if(line) ctx.fillText(line,x,y);
  return y+lH;
}

// ── Colonna risultati gara (riusabile: 1 o 2 colonne) ───────
// Righe a altezza uniforme + font ancorati alla larghezza (no ballooning su Storie/landscape)
function _drawGaraColumn(ctx, x, colW, topY, bottomY, slice, startIdx, winnerTime, _prevGapRef, avatarMap) {
  // _prevGapRef = { gap: string } — oggetto condiviso per tracciare il gap precedente tra colonne
  if (!_prevGapRef) _prevGapRef = { gap: null };
  const medalBg = ['#f5c400','#c8c8c8','#cd7f32'];
  const medalFg = ['#1a1200','#1a1a1a','#2a1500'];
  const right = x + colW;
  const n = slice.length;
  if (!n) return;
  // Altezza riga: mai oltre quella che avrebbero 6 righe piene, altrimenti
  // con poche gare (comune nelle categorie giovanili, es. 3-4 arrivati) le
  // righe si allungano a dismisura per riempire tutto lo spazio verticale,
  // lasciando vuoti enormi tra una riga e l'altra che fanno sembrare la
  // card vuota/rotta invece che una lista corta ma pulita.
  const availH = bottomY - topY;
  const rH = Math.min(Math.round(availH / n), Math.round(availH / 6));
  // Il blocco (n righe) può essere più corto dello spazio disponibile:
  // lo centriamo verticalmente invece di ancorarlo sempre in alto.
  topY += Math.round((availH - rH * n) / 2);

  // Font unico per nome atleta (cognome + nome stessa dimensione)
  // e font leggermente più piccolo per il team sotto.
  // Cap sia per altezza riga che per larghezza colonna.
  const fsName = Math.min(Math.round(rH * 0.28), Math.round(colW * 0.052));
  const fsTm   = Math.round(fsName * 0.82);

  // Altezza del blocco testo (2 righe): usata per centrare verticalmente
  const lineGap  = Math.round(fsName * 0.35);  // spazio tra riga nome e riga team
  const blockH   = fsName + lineGap + fsTm;

  slice.forEach((r, i) => {
    const gIdx   = startIdx + i;
    const isTop3 = gIdx < 3;
    const isFirst = gIdx === 0;
    const ry = topY + i * rH;
    const cy = Math.round(ry + rH / 2);

    // ── Sfondo riga ──
    if (isFirst) {
      const goldG = ctx.createLinearGradient(x, ry, right, ry + rH);
      goldG.addColorStop(0, 'rgba(245,196,0,0.13)'); goldG.addColorStop(1, 'rgba(245,196,0,0.04)');
      ctx.fillStyle = goldG; ctx.fillRect(x, ry, colW, rH);
      ctx.strokeStyle = 'rgba(245,196,0,0.42)'; ctx.lineWidth = 1.5;
      if (ctx.roundRect) { ctx.beginPath(); ctx.roundRect(x, ry+1, colW, rH-2, 7); ctx.stroke(); }
      else ctx.strokeRect(x, ry+1, colW, rH-2);
    } else if (gIdx === 1) {
      ctx.fillStyle = 'rgba(200,200,200,0.045)'; ctx.fillRect(x, ry, colW, rH);
    } else if (gIdx === 2) {
      ctx.fillStyle = 'rgba(205,127,50,0.035)'; ctx.fillRect(x, ry, colW, rH);
    } else if (i > 0) {
      ctx.fillStyle = 'rgba(255,255,255,0.045)'; ctx.fillRect(x, ry, colW, 1);
    }

    // ── Pill posizione ──
    const pillH = Math.min(Math.round(rH * 0.52), Math.round(colW * 0.075));
    const pillW = Math.round(pillH * 1.55);
    const pillX = x + Math.round(colW * 0.008);
    const pillY = cy - Math.round(pillH / 2);
    ctx.fillStyle = isTop3 ? medalBg[gIdx] : 'rgba(255,255,255,0.07)';
    if (ctx.roundRect) { ctx.beginPath(); ctx.roundRect(pillX, pillY, pillW, pillH, Math.round(pillH*0.2)); ctx.fill(); }
    else ctx.fillRect(pillX, pillY, pillW, pillH);
    const fsPos = Math.round(pillH * 0.56);
    ctx.font = `700 ${fsPos}px 'Inter Tight',sans-serif`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = isTop3 ? medalFg[gIdx] : 'rgba(255,255,255,0.38)';
    ctx.fillText(String(gIdx+1).padStart(2,'0'), pillX + pillW/2, cy+1);

    // ── Avatar (solo se questo atleta ha una foto profilo — mai un
    // segnaposto vuoto per chi non ce l'ha) ──
    const avatarImg = avatarMap && avatarMap.get(r.atleta_id);
    const avatarD   = avatarImg ? Math.min(Math.round(rH * 0.72), Math.round(colW * 0.09)) : 0;
    const avatarX   = pillX + pillW + Math.round(colW * 0.025);
    if (avatarImg) {
      const acx = avatarX + avatarD / 2, acy = cy;
      ctx.save();
      ctx.beginPath(); ctx.arc(acx, acy, avatarD / 2, 0, Math.PI * 2); ctx.clip();
      // Ritaglia ancorando in alto (viso in cima), come l'avatar della card atleta
      const scale = Math.max(avatarD / avatarImg.naturalWidth, avatarD / avatarImg.naturalHeight);
      const sw = avatarImg.naturalWidth * scale, sh = avatarImg.naturalHeight * scale;
      ctx.drawImage(avatarImg, acx - avatarD / 2 + (avatarD - sw) / 2, acy - avatarD / 2, sw, sh);
      ctx.restore();
      ctx.strokeStyle = 'rgba(255,255,255,0.18)'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(acx, acy, avatarD / 2, 0, Math.PI * 2); ctx.stroke();
    }

    // ── Blocco testo: nome (riga 1) + team (riga 2) ──
    const nameX   = avatarImg ? (avatarX + avatarD + Math.round(colW * 0.025)) : (pillX + pillW + Math.round(colW * 0.04));
    const maxW    = right - nameX - Math.round(colW * 0.02);
    const nameY   = cy - Math.round(blockH / 2) + fsName;       // baseline riga nome
    const teamY   = nameY + lineGap + fsTm;                      // baseline riga team

    // Riga 1 — COGNOME Nome, stessa grandezza, cognome in grassetto
    const fullName = ((r.cognome||'').toUpperCase() + ' ' + (r.nome||'')).trim();
    ctx.textBaseline = 'alphabetic'; ctx.textAlign = 'left';

    // Clip se troppo lungo
    ctx.save();
    ctx.beginPath(); ctx.rect(nameX, ry+2, maxW, rH-4); ctx.clip();

    ctx.font = `600 ${fsName}px 'Inter Tight',sans-serif`;
    ctx.fillStyle = isTop3 ? '#f4f4f4' : 'rgba(255,255,255,0.88)';
    ctx.fillText(fullName, nameX, nameY);

    // Riga 2 — team, tono più chiaro
    if (r.team) {
      ctx.font = `400 ${fsTm}px 'Inter Tight',sans-serif`;
      ctx.fillStyle = isFirst ? 'rgba(255,255,255,0.52)' : 'rgba(255,255,255,0.36)';
      ctx.fillText(r.team, nameX, teamY);
    }

    ctx.restore();

    // ── Tempo / distacco a destra ──
    let timeStr;
    if (startIdx === 0 && i === 0) {
      timeStr = winnerTime || '';
    } else {
      const rawGap = r.tempo || '';
      if (!rawGap) {
        timeStr = 'ST';
      } else if (rawGap === _prevGapRef.gap) {
        timeStr = 'ST';
      } else {
        timeStr = _fmtGap(rawGap);
      }
      _prevGapRef.gap = rawGap || _prevGapRef.gap;
    }
    if (timeStr) {
      const fsTi = Math.round(rH * 0.28);
      ctx.font = `600 ${fsTi}px 'Inter Tight',sans-serif`;
      ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
      ctx.fillStyle = isFirst ? 'rgba(245,196,0,0.85)' : 'rgba(255,255,255,0.38)';
      ctx.fillText(timeStr, right - Math.round(colW * 0.012), cy);
      ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
    }
  });
}

// ── GARA CARD "VINCITORE" — solo il primo classificato, stile annuncio ───
// Foto quasi a pieno schermo (scurita solo in basso, vedi _bgPhotoBottom),
// categoria/nome vincitore/nome gara centrati sopra il degradé, logo ICS in
// fondo — riferimento visivo indicato dall'utente (grafica di terzi).
function _drawGaraWinner(ctx, W, H, d, logo, xpixLogo) {
  const winner = (d.results || [])[0];
  if (!winner) return;
  const winnerName = `${winner.cognome || ''} ${winner.nome || ''}`.trim().toUpperCase();
  const raceName = (d.name || '').toUpperCase();
  const pad = Math.round(W * 0.08);
  const maxW = W - pad * 2;
  ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';

  let y = H - Math.round(H * 0.14);

  // Nome gara (riga più bassa, più piccola)
  let fsRace = Math.round(W * 0.042);
  ctx.font = `700 ${fsRace}px 'Inter Tight',sans-serif`;
  while (ctx.measureText(raceName).width > maxW && fsRace > Math.round(W * 0.02)) {
    fsRace -= 1; ctx.font = `700 ${fsRace}px 'Inter Tight',sans-serif`;
  }
  ctx.fillStyle = 'rgba(255,255,255,0.88)';
  ctx.fillText(raceName, W / 2, y);

  // Nome vincitore (grande, sopra il nome gara)
  y -= Math.round(fsRace * 1.55);
  let fsName = Math.round(W * 0.078);
  ctx.font = `800 ${fsName}px 'Inter Tight',sans-serif`;
  while (ctx.measureText(winnerName).width > maxW && fsName > Math.round(W * 0.032)) {
    fsName -= 1; ctx.font = `800 ${fsName}px 'Inter Tight',sans-serif`;
  }
  ctx.fillStyle = '#fff';
  ctx.fillText(winnerName, W / 2, y);

  // Categoria (eyebrow, sopra il nome vincitore)
  y -= Math.round(fsName * 1.25);
  const fsCat = Math.round(W * 0.026);
  ctx.font = `600 ${fsCat}px 'Inter Tight',sans-serif`;
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.letterSpacing = Math.round(fsCat * 0.5) + 'px';
  ctx.fillText((d.cat || '').toUpperCase(), W / 2, y);
  ctx.letterSpacing = '0px';

  // Logo ICS centrato in fondo. Quando la foto viene da xpix.it, il loro
  // logo compare in fila accanto al nostro, stessa altezza — non più un
  // piccolo richiamo testuale a parte, come nel riferimento fornito
  // dall'utente (due loghi affiancati, stesso peso visivo).
  const lH = Math.round(H * 0.065);
  const logoY = H - Math.round(H * 0.045) - lH;
  if (xpixLogo && logo) {
    const gap = Math.round(W * 0.022);
    const xpixW = Math.round(lH * xpixLogo.naturalWidth / xpixLogo.naturalHeight);
    const icsW = Math.round(lH * logo.naturalWidth / logo.naturalHeight);
    const startX = W / 2 - (xpixW + gap + icsW) / 2;
    ctx.drawImage(xpixLogo, startX, logoY, xpixW, lH);
    ctx.drawImage(logo, startX + xpixW + gap, logoY, icsW, lH);
  } else {
    if (logo) {
      const lW = Math.round(lH * logo.naturalWidth / logo.naturalHeight);
      ctx.drawImage(logo, W / 2 - lW / 2, logoY, lW, lH);
    }
    _drawPhotoCredit(ctx, W, H, d, {});
  }
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
}

// Credit foto (fotografo o fonte esterna) — quando la foto viene da xpix.it,
// disegna il loro logo vero (badge tondo, non solo testo) accanto al nostro
// logo ICS, così l'attribuzione è visibile davvero e non solo scritta in
// piccolo. Condiviso tra la card "Vincitore" (sotto il logo, centrato) e la
// card "Risultati" (nel footer, accanto all'handle @italiacrit).
function _drawPhotoCredit(ctx, W, H, d, { x, y, align = 'center', xpixLogo } = {}) {
  if (!d.photo_credit) return;
  const fs = Math.round(W * 0.022);
  ctx.font = `600 ${fs}px 'Inter Tight',sans-serif`;
  const baseX = x != null ? x : W / 2;
  const baseY = y != null ? y : H - Math.round(H * 0.015);

  if (_isXpixCredit(d) && xpixLogo) {
    const badgeH = Math.round(fs * 1.7);
    const badgeW = Math.round(badgeH * xpixLogo.naturalWidth / xpixLogo.naturalHeight);
    const gap = Math.round(fs * 0.4);
    const label = 'xpix.it';
    ctx.fillStyle = 'rgba(255,255,255,0.65)';
    const textW = ctx.measureText(label).width;
    const totalW = badgeW + gap + textW;
    const startX = align === 'left' ? baseX : baseX - totalW / 2;
    ctx.drawImage(xpixLogo, startX, baseY - badgeH * 0.8, badgeW, badgeH);
    ctx.textAlign = 'left';
    ctx.fillText(label, startX + badgeW + gap, baseY);
    return;
  }
  if (d.photo_source === 'ic') return;
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  ctx.textAlign = align;
  const label = `📷 Foto: ${d.photo_credit}`;
  ctx.fillText(label, baseX, baseY);
}

// ── GARA CARD v6 — UCI-inspired, no points, big names ────────
function _drawGara(ctx, W, H, d, logo, avatarMap, xpixLogo) {
  const { name, date, cat, mult, tipo, km, media, results, winnerTime } = d;
  const pad = Math.round(W * 0.048);

  // ── Header compatto Velon: flat, logo a sinistra (grande), categoria a destra ──
  // Niente regione: il dato non è sempre affidabile nei risultati gara (a
  // differenza della categoria, sempre corretta) — meglio ometterla che
  // rischiare di mostrarne una sbagliata su un'immagine pubblica.
  const hH = Math.round(H * 0.095);
  if (logo) {
    const lH = Math.round(hH * 0.70);
    const lW = Math.round(lH * logo.naturalWidth / logo.naturalHeight);
    ctx.drawImage(logo, pad, Math.round((hH - lH) / 2), lW, lH);
  } else {
    const fsLg = Math.round(hH * 0.42);
    ctx.font = `900 ${fsLg}px 'Inter Tight','Inter Tight',sans-serif`;
    ctx.fillStyle = '#ffffff';
    ctx.fillText('ICS', pad, Math.round(hH * 0.64));
  }
  // Categoria in alto a destra (sostituisce l'URL italiacrit)
  const fsCatH = Math.round(hH * 0.36);
  ctx.font = `800 ${fsCatH}px 'Inter Tight',sans-serif`;
  ctx.letterSpacing = '1px';
  ctx.fillStyle = '#e8001d'; ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
  ctx.fillText(cat.toUpperCase(), W - pad, Math.round(hH * 0.52));
  ctx.letterSpacing = '0px'; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  // Linea accento sottile flat sotto l'header
  ctx.fillStyle = 'rgba(255,255,255,0.07)'; ctx.fillRect(0, hH, W, 1);
  ctx.fillStyle = '#e8001d'; ctx.fillRect(pad, hH, Math.round(W * 0.10), 2);

  let y = hH + Math.round(H * 0.022);

  // ── Race name — singola riga auto-shrink ──
  // Parte da un font grande, riduce finché il nome entra in una riga sola.
  const fsTMax = Math.round(W * 0.052);
  const fsTMin = Math.round(W * 0.026);
  let fsT = fsTMax;
  const nameStr = name.toUpperCase();
  const nameMaxW = W - pad * 2;
  ctx.font = `700 ${fsT}px 'Inter Tight',sans-serif`;
  while (ctx.measureText(nameStr).width > nameMaxW && fsT > fsTMin) {
    fsT -= 1;
    ctx.font = `700 ${fsT}px 'Inter Tight',sans-serif`;
  }
  ctx.fillStyle = '#f4f4f4';
  y += fsT;
  ctx.fillText(nameStr, pad, y);
  y += Math.round(H * 0.006);

  // ── Meta riga: data · ×mult · km · media (categoria è già in header) ──
  const fsMeta = Math.round(W * 0.024);
  ctx.font = `400 ${fsMeta}px 'Inter Tight',sans-serif`;
  ctx.fillStyle = 'rgba(255,255,255,0.40)';
  const metaArr = [date, `×${mult}`];
  if (km)         metaArr.push(`${km} km`);
  if (media)      metaArr.push(`${media} km/h`);
  if (winnerTime) metaArr.push(`⏱ ${winnerTime}`);
  y += fsMeta;
  ctx.fillText(metaArr.join('   ·   '), pad, y);
  y += Math.round(fsMeta * 0.8);

  // Accent divider flat (Velon): linea sottile + tratto brand
  ctx.fillStyle = 'rgba(255,255,255,0.07)'; ctx.fillRect(pad, y, W - pad * 2, 1);
  ctx.fillStyle = '#e8001d'; ctx.fillRect(pad, y, Math.round(W * 0.10), 2);
  y += Math.round(H * 0.012);

  // ── Footer Velon: minimale ──
  const fB = Math.round(H * 0.05);
  const footerY = H - fB;
  ctx.fillStyle = 'rgba(255,255,255,0.07)'; ctx.fillRect(0, footerY, W, 1);
  const s = 2, accW = Math.round(W * 0.018), ax = pad, ay = footerY + Math.round(fB * 0.40);
  ctx.fillStyle = '#009246'; ctx.fillRect(ax, ay, accW, s);
  ctx.fillStyle = '#f0f0ee'; ctx.fillRect(ax + accW, ay, accW, s);
  ctx.fillStyle = '#ce2b37'; ctx.fillRect(ax + accW * 2, ay, accW, s);
  // Icone social al centro + handle a destra
  _drawSocialIcons(ctx, W / 2, footerY + Math.round(fB * 0.50), Math.round(fB * 0.40), 'rgba(255,255,255,0.55)');
  ctx.font = `500 ${Math.round(fB * 0.3)}px 'Inter Tight',sans-serif`;
  ctx.fillStyle = 'rgba(255,255,255,0.3)'; ctx.textAlign = 'right';
  ctx.fillText('@italiacrit', W - pad, footerY + Math.round(fB * 0.66)); ctx.textAlign = 'left';
  // Credit foto (fotografo o xpix.it/ciclismo.info), sinistra — stessa riga
  // dell'handle, così non serve spazio verticale extra.
  _drawPhotoCredit(ctx, W, H, d, { x: ax + accW * 3 + Math.round(W * 0.014), y: footerY + Math.round(fB * 0.66), align: 'left', xpixLogo });

  // ── Results list (1 colonna; 2 colonne su formati landscape con >5 atleti) ──
  const listTop = y;
  const listBot = footerY - Math.round(H * 0.003);
  const maxR = Math.min(results.length, 10);
  const slice = results.slice(0, maxR);
  const landscape = W > H * 1.25;

  const wt = d.winnerTime || '';
  const _gapRef = { gap: null };
  if (landscape && maxR > 5) {
    const gap = Math.round(W * 0.045);
    const colW = Math.round((W - pad * 2 - gap) / 2);
    _drawGaraColumn(ctx, pad, colW, listTop, listBot, slice.slice(0, 5), 0, wt, _gapRef, avatarMap);
    _drawGaraColumn(ctx, pad + colW + gap, colW, listTop, listBot, slice.slice(5), 5, wt, _gapRef, avatarMap);
  } else {
    _drawGaraColumn(ctx, pad, W - pad * 2, listTop, listBot, slice, 0, wt, _gapRef, avatarMap);
  }
}

// ── ATLETA CARD ────────────────────────────────────────────
// ── Helper: rettangolo arrotondato (fallback se roundRect non c'è) ──
function _rr(ctx, x, y, w, h, r) {
  // Clamp difensivo: su formati molto larghi/bassi (Facebook 1.91:1, Twitter
  // 16:9) un'altezza calcolata può arrivare a 0 o leggermente negativa per
  // arrotondamenti a cascata — roundRect() lancia un'eccezione hard (non un
  // warning) con un raggio negativo, che altrimenti blocca l'intera card.
  const rr = Math.max(0, Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2));
  if (ctx.roundRect) { ctx.beginPath(); ctx.roundRect(x, y, w, Math.max(0, h), rr); }
  else { ctx.beginPath(); ctx.rect(x, y, w, Math.max(0, h)); }
}
// ── Helper: box "hero" con numero grande + etichetta ──
function _statHero(ctx, x, y, w, h, val, label, style) {
  const r = Math.round(h * 0.10);
  ctx.fillStyle = 'rgba(255,255,255,0.045)'; _rr(ctx, x, y, w, h, r); ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.09)'; ctx.lineWidth = 1.5; _rr(ctx, x, y, w, h, r); ctx.stroke();
  const fsV = Math.round(h * 0.44);
  ctx.font = `900 ${fsV}px 'Inter Tight',sans-serif`;
  ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
  if (style === 'grad') { const g = ctx.createLinearGradient(x, y, x + w, y); g.addColorStop(0, '#e8001d'); g.addColorStop(1, '#f5c400'); ctx.fillStyle = g; }
  else ctx.fillStyle = '#f5c400';
  ctx.fillText(String(val), x + w / 2, y + Math.round(h * 0.56));
  const fsL = Math.round(h * 0.135);
  ctx.font = `600 ${fsL}px 'Inter Tight',sans-serif`; ctx.fillStyle = 'rgba(255,255,255,0.46)';
  ctx.letterSpacing = '1px'; ctx.fillText(label, x + w / 2, y + Math.round(h * 0.83));
  ctx.letterSpacing = '0px'; ctx.textAlign = 'left';
}
// ── Helper: cella statistica con accento colorato in alto ──
function _statCell(ctx, x, y, w, h, val, label, color) {
  const r = Math.round(Math.min(w, h) * 0.09);
  ctx.fillStyle = 'rgba(255,255,255,0.04)'; _rr(ctx, x, y, w, h, r); ctx.fill();
  ctx.fillStyle = color; _rr(ctx, x, y, w, Math.max(3, Math.round(h * 0.035)), 2); ctx.fill();
  const fsV = Math.min(Math.round(h * 0.40), Math.round(w * 0.52));
  ctx.font = `900 ${fsV}px 'Inter Tight',sans-serif`; ctx.fillStyle = color;
  ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
  ctx.fillText(String(val), x + w / 2, y + Math.round(h * 0.56));
  const fsL = Math.min(Math.round(h * 0.13), Math.round(w * 0.15));
  ctx.font = `600 ${fsL}px 'Inter Tight',sans-serif`; ctx.fillStyle = 'rgba(255,255,255,0.42)';
  ctx.fillText(label, x + w / 2, y + Math.round(h * 0.80));
  ctx.textAlign = 'left';
}

function _drawAtleta(ctx, W, H, d, athImg) {
  const {cognome,nome,cat,team,punti,pos,p1,p2,p3,gare} = d;
  const hB=Math.round(H*0.09), fB=Math.round(H*0.06), pad=Math.round(W*0.055);
  const cTop = hB + Math.round(H*0.025);
  const cBot = H - fB - Math.round(H*0.02);
  const cH   = cBot - cTop;

  // ── Foto corridore (cerchio in alto a destra) ──
  const phD = athImg ? Math.round(W * 0.22) : 0; // diametro cerchio
  const phX = athImg ? W - pad - phD : 0;
  const phY = athImg ? cTop + Math.round(H * 0.01) : 0;
  if (athImg) {
    ctx.save();
    ctx.beginPath();
    ctx.arc(phX + phD/2, phY + phD/2, phD/2, 0, Math.PI*2);
    ctx.clip();
    // disegna ritagliando dall'alto (viso in cima)
    const scale = Math.max(phD / athImg.naturalWidth, phD / athImg.naturalHeight);
    const sw = athImg.naturalWidth * scale, sh = athImg.naturalHeight * scale;
    ctx.drawImage(athImg, phX + (phD - sw)/2, phY, sw, sh);
    ctx.restore();
    // bordo sottile
    ctx.strokeStyle = 'rgba(255,255,255,0.18)'; ctx.lineWidth = Math.round(W*0.004);
    ctx.beginPath(); ctx.arc(phX + phD/2, phY + phD/2, phD/2, 0, Math.PI*2); ctx.stroke();
  }

  // ── Blocco nome (larghezza ridotta se c'è la foto) ──
  const nameMaxW = athImg ? (phX - pad - Math.round(W*0.03)) : (W - pad*2);
  let y = cTop;
  const fsC=Math.round(W*(cognome.length>12?0.072:0.092));
  ctx.font=`900 ${fsC}px 'Inter Tight',sans-serif`; ctx.fillStyle='#f4f4f4';
  ctx.textAlign='left'; ctx.textBaseline='alphabetic';
  y=_wrap(ctx,cognome.toUpperCase(),pad,y+fsC,nameMaxW,fsC*1.05);
  const fsN=Math.round(fsC*0.46);
  ctx.font=`700 ${fsN}px 'Inter Tight',sans-serif`; ctx.fillStyle='#e8001d';
  ctx.fillText(nome.toUpperCase(),pad,y); y+=Math.round(fsN*1.55);
  // Team (leggermente più grande, la categoria è in alto a destra)
  if (team) {
    const fsTm=Math.round(W*0.032);
    ctx.font=`600 ${fsTm}px 'Inter Tight',sans-serif`; ctx.fillStyle='rgba(255,255,255,0.55)';
    ctx.fillText(team.substring(0,40),pad,y);
  }

  // ── Hero: PUNTI + POSIZIONE ──
  const heroTop=y+Math.round(H*0.04);
  const heroH=Math.round(cH*0.30);
  const gap=Math.round(W*0.03);
  const boxW=(W-pad*2-gap)/2;
  _statHero(ctx,pad,heroTop,boxW,heroH,punti,'PUNTI STAGIONE','grad');
  _statHero(ctx,pad+boxW+gap,heroTop,boxW,heroH,(pos&&pos!=='-')?`${pos}°`:'—','IN CLASSIFICA','gold');

  // ── Griglia statistiche (riempie lo spazio fino al footer) ──
  const gridTop=heroTop+heroH+Math.round(H*0.035);
  const gridH=cBot-gridTop;
  const cells=[['VITTORIE',p1,'#f5c400'],['2° POSTI',p2,'#cfcfcf'],['3° POSTI',p3,'#cd7f32'],['4°-10°',(d.p4_10||0),'#f0f0f0']];
  const cgap=Math.round(W*0.025);
  const cw=(W-pad*2-cgap*3)/4;
  cells.forEach((c,i)=>_statCell(ctx,pad+i*(cw+cgap),gridTop,cw,gridH,c[1],c[0],c[2]));
}

// ── TEAM CARD ──────────────────────────────────────────────
function _drawTeam(ctx, W, H, d) {
  const {nome,cat,punti,pos,atleti} = d;
  const hB=Math.round(H*0.09), fB=Math.round(H*0.06), pad=Math.round(W*0.055);
  const cTop=hB+Math.round(H*0.025), cBot=H-fB-Math.round(H*0.02), cH=cBot-cTop;

  // ── Nome team (categoria in alto a destra nell'header) ──
  let y=cTop;
  const fsN=Math.round(W*(nome.length>20?0.052:0.07));
  ctx.font=`900 ${fsN}px 'Inter Tight',sans-serif`; ctx.fillStyle='#f4f4f4';
  ctx.textAlign='left'; ctx.textBaseline='alphabetic';
  y=_wrap(ctx,nome.toUpperCase(),pad,y+fsN,W-pad*2,fsN*1.08);

  // ── Hero: PUNTI + POSIZIONE ──
  const heroTop=y+Math.round(H*0.03);
  const heroH=Math.round(cH*0.26);
  const gap=Math.round(W*0.03);
  const boxW=(W-pad*2-gap)/2;
  _statHero(ctx,pad,heroTop,boxW,heroH,punti,'PUNTI TEAM','grad');
  _statHero(ctx,pad+boxW+gap,heroTop,boxW,heroH,(pos?`${pos}°`:'—'),'IN CLASSIFICA','gold');

  // ── Miglior atleta ──
  const best = (atleti && atleti[0]) || null;
  const labelY=heroTop+heroH+Math.round(H*0.045);
  const fsLbl=Math.round(W*0.023);
  ctx.font=`700 ${fsLbl}px 'Inter Tight',sans-serif`; ctx.fillStyle='rgba(255,255,255,0.45)';
  ctx.letterSpacing='1.5px'; ctx.textAlign='left'; ctx.textBaseline='alphabetic';
  ctx.fillText('MIGLIOR ATLETA',pad,labelY); ctx.letterSpacing='0px';
  const bestTop=labelY+Math.round(H*0.016);
  const bestH=Math.round(cH*0.16);
  if (best) {
    ctx.fillStyle='rgba(245,196,0,0.10)'; _rr(ctx,pad,bestTop,W-pad*2,bestH,Math.round(bestH*0.12)); ctx.fill();
    ctx.strokeStyle='rgba(245,196,0,0.40)'; ctx.lineWidth=1.5; _rr(ctx,pad,bestTop,W-pad*2,bestH,Math.round(bestH*0.12)); ctx.stroke();
    const bMid=bestTop+bestH/2;
    // medaglia
    const mD=Math.round(bestH*0.46), mX=pad+Math.round(W*0.03);
    ctx.fillStyle='#f5c400'; ctx.beginPath(); ctx.arc(mX+mD/2,bMid,mD/2,0,Math.PI*2); ctx.fill();
    ctx.font=`800 ${Math.round(mD*0.6)}px 'Inter Tight',sans-serif`; ctx.fillStyle='#1a1200';
    ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText('1',mX+mD/2,bMid+1);
    // nome
    const nX=mX+mD+Math.round(W*0.03);
    const ptsResW=Math.round(W*0.18);
    const nameMaxW=W-pad-ptsResW-nX;
    const fsA=Math.min(Math.round(bestH*0.40),Math.round(W*0.05));
    ctx.font=`800 ${fsA}px 'Inter Tight',sans-serif`; ctx.fillStyle='#f4f4f4';
    ctx.textAlign='left'; ctx.textBaseline='middle';
    let nm=`${(best.cognome||'').toUpperCase()} ${(best.nome||'')}`.trim();
    while(nm.length>3 && ctx.measureText(nm).width>nameMaxW) nm=nm.slice(0,-1);
    ctx.fillText(nm,nX,bMid-Math.round(bestH*0.07));
    ctx.font=`500 ${Math.round(fsA*0.5)}px 'Inter Tight',sans-serif`; ctx.fillStyle='rgba(255,255,255,0.5)';
    ctx.fillText('Miglior punteggio del team',nX,bMid+Math.round(bestH*0.26));
    // punti
    ctx.font=`900 ${Math.round(bestH*0.46)}px 'Inter Tight',sans-serif`; ctx.fillStyle='#f5c400'; ctx.textAlign='right';
    ctx.fillText(String(best.puntiCat||0),W-pad-Math.round(W*0.02),bMid);
    ctx.textAlign='left'; ctx.textBaseline='alphabetic';
  }

  // ── Griglia statistiche team: 1° / 2° / 3° / 4°-10° ──
  const gridTop=bestTop+bestH+Math.round(H*0.04);
  const gridH=cBot-gridTop;
  const cells=[['1° POSTI',(d.p1||0),'#f5c400'],['2° POSTI',(d.p2||0),'#cfcfcf'],['3° POSTI',(d.p3||0),'#cd7f32'],['4°-10°',(d.p4_10||0),'#f0f0f0']];
  const cgap=Math.round(W*0.025);
  const cw=(W-pad*2-cgap*3)/4;
  cells.forEach((c,i)=>_statCell(ctx,pad+i*(cw+cgap),gridTop,cw,gridH,c[1],c[0],c[2]));
}

// ── ATLETA/TEAM DEL MESE (card individuale per categoria) ──
// Stessa impaginazione della card atleta/team "di stagione", ma con le
// statistiche del solo mese selezionato invece che dell'intera stagione
// (niente "posizione in classifica" perché non calcolata a livello mensile).
function _drawAtletaMese(ctx, W, H, d, athImg) {
  const { cognome, nome, team, catLabel, punti, p1: wins, p2, p3, gare } = d;
  const hB = Math.round(H * 0.092), fB = Math.round(H * 0.06), pad = Math.round(W * 0.055);
  const cTop = hB + Math.round(H * 0.025);
  const cBot = H - fB - Math.round(H * 0.02);
  const cH = cBot - cTop;

  const phD = athImg ? Math.round(W * 0.22) : 0;
  const phX = athImg ? W - pad - phD : 0;
  const phY = athImg ? cTop + Math.round(H * 0.01) : 0;
  if (athImg) {
    ctx.save();
    ctx.beginPath();
    ctx.arc(phX + phD / 2, phY + phD / 2, phD / 2, 0, Math.PI * 2);
    ctx.clip();
    const scale = Math.max(phD / athImg.naturalWidth, phD / athImg.naturalHeight);
    const sw = athImg.naturalWidth * scale, sh = athImg.naturalHeight * scale;
    ctx.drawImage(athImg, phX + (phD - sw) / 2, phY, sw, sh);
    ctx.restore();
    ctx.strokeStyle = 'rgba(255,255,255,0.18)'; ctx.lineWidth = Math.round(W * 0.004);
    ctx.beginPath(); ctx.arc(phX + phD / 2, phY + phD / 2, phD / 2, 0, Math.PI * 2); ctx.stroke();
  }

  // Hero + griglia ancorati dal BASSO (cBot) verso l'alto — calcolati PRIMA
  // del blocco nome così quest'ultimo sa dove fermarsi (vedi commento più
  // sotto sul perché dell'ancoraggio dal basso).
  const landscape = W > H * 1.25;
  const gridH = Math.round(cH * (landscape ? 0.20 : 0.155));
  const heroH = Math.round(cH * (landscape ? 0.26 : 0.30));
  const gridTop = cBot - gridH;
  const heroTop = gridTop - Math.round(H * (landscape ? 0.022 : 0.035)) - heroH;

  // Font con TETTO sull'altezza (non solo sulla larghezza): sui formati
  // molto larghi/bassi (Facebook 1.91:1, Twitter 16:9) H è ridotto ma W resta
  // grande — senza il tetto H-relativo il blocco nome+categoria da solo
  // sfora l'altezza disponibile e spinge le celle sotto in negativo.
  const nameMaxW = athImg ? (phX - pad - Math.round(W * 0.03)) : (W - pad * 2);
  let y = cTop;
  const fsCat = Math.min(Math.round(W * 0.026), Math.round(H * 0.045));
  ctx.font = `700 ${fsCat}px 'Inter Tight',sans-serif`; ctx.fillStyle = '#e8001d';
  ctx.letterSpacing = '1px'; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillText('ATLETA DEL MESE · ' + (catLabel || '').toUpperCase(), pad, y + fsCat);
  ctx.letterSpacing = '0px';
  y += fsCat + Math.round(H * 0.014);
  const fsC = Math.min(Math.round(W * (cognome.length > 12 ? 0.072 : 0.092)), Math.round(H * 0.16));
  ctx.font = `900 ${fsC}px 'Inter Tight',sans-serif`; ctx.fillStyle = '#f4f4f4';
  y = _wrap(ctx, cognome.toUpperCase(), pad, y + fsC, nameMaxW, fsC * 1.05);
  const fsN = Math.round(fsC * 0.46);
  ctx.font = `700 ${fsN}px 'Inter Tight',sans-serif`; ctx.fillStyle = '#e8001d';
  ctx.fillText((nome || '').toUpperCase(), pad, y);
  // Sui formati landscape (poco spazio verticale) il team va sulla STESSA
  // riga del nome, subito dopo, invece che su una riga propria sotto — così
  // c'è sempre spazio garantito per mostrarlo, senza doverlo mai omettere né
  // rischiare che si sovrapponga al box "PUNTI DEL MESE" ancorato dal basso.
  if (team && landscape) {
    const nomeW = ctx.measureText((nome || '').toUpperCase()).width;
    const fsTm = Math.min(Math.round(W * 0.024), Math.round(H * 0.045));
    ctx.font = `500 ${fsTm}px 'Inter Tight',sans-serif`; ctx.fillStyle = 'rgba(255,255,255,0.48)';
    let tm = ' · ' + String(team);
    const teamMaxW = nameMaxW - nomeW - 6;
    while (tm.length > 5 && ctx.measureText(tm).width > teamMaxW) tm = tm.slice(0, -1) === ' ' ? tm.slice(0, -2) : tm.slice(0, -1);
    if (teamMaxW > 20) ctx.fillText(tm, pad + nomeW + 6, y);
  }
  y += Math.round(fsN * 1.55);
  if (team && !landscape) {
    const fsTm = Math.min(Math.round(W * 0.032), Math.round(H * 0.055));
    ctx.font = `600 ${fsTm}px 'Inter Tight',sans-serif`; ctx.fillStyle = 'rgba(255,255,255,0.55)';
    let tm = String(team).substring(0, 40);
    while (tm.length > 3 && ctx.measureText(tm).width > nameMaxW) tm = tm.slice(0, -1);
    ctx.fillText(tm, pad, y);
  }

  const gap = Math.round(W * 0.03);
  const boxW = (W - pad * 2 - gap) / 2;
  _statHero(ctx, pad, heroTop, boxW, heroH, punti, 'PUNTI DEL MESE', 'grad');
  _statHero(ctx, pad + boxW + gap, heroTop, boxW, heroH, wins, 'VITTORIE', 'gold');

  const cells = [['1° POSTI', wins, '#f5c400'], ['2° POSTI', (p2 || 0), '#cfcfcf'], ['3° POSTI', (p3 || 0), '#cd7f32'], ['GARE', (gare || 0), '#f0f0f0']];
  const cgap = Math.round(W * 0.025);
  const cw = (W - pad * 2 - cgap * 3) / 4;
  cells.forEach((c, i) => _statCell(ctx, pad + i * (cw + cgap), gridTop, cw, gridH, c[1], c[0], c[2]));
}
function _drawTeamMese(ctx, W, H, d) {
  const { nome, catLabel, punti, p1: wins, p2, p3 } = d;
  const hB = Math.round(H * 0.092), fB = Math.round(H * 0.06), pad = Math.round(W * 0.055);
  const cTop = hB + Math.round(H * 0.025), cBot = H - fB - Math.round(H * 0.02), cH = cBot - cTop;
  let y = cTop;
  const fsCat = Math.min(Math.round(W * 0.026), Math.round(H * 0.045));
  ctx.font = `700 ${fsCat}px 'Inter Tight',sans-serif`; ctx.fillStyle = '#e8001d';
  ctx.letterSpacing = '1px'; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillText('TEAM DEL MESE · ' + (catLabel || '').toUpperCase(), pad, y + fsCat);
  ctx.letterSpacing = '0px';
  y += fsCat + Math.round(H * 0.016);
  const fsN = Math.min(Math.round(W * (nome.length > 20 ? 0.052 : 0.07)), Math.round(H * 0.13));
  ctx.font = `900 ${fsN}px 'Inter Tight',sans-serif`; ctx.fillStyle = '#f4f4f4';
  y = _wrap(ctx, nome.toUpperCase(), pad, y + fsN, W - pad * 2, fsN * 1.08);

  // Ancorate dal basso — stesso motivo della card atleta (vedi commento lì).
  const landscape = W > H * 1.25;
  const gridH = Math.round(cH * (landscape ? 0.22 : 0.17));
  const heroH = Math.round(cH * (landscape ? 0.26 : 0.30));
  const gridTop = cBot - gridH;
  const heroTop = gridTop - Math.round(H * (landscape ? 0.025 : 0.04)) - heroH;
  const gap = Math.round(W * 0.03);
  const boxW = (W - pad * 2 - gap) / 2;
  _statHero(ctx, pad, heroTop, boxW, heroH, punti, 'PUNTI DEL MESE', 'grad');
  _statHero(ctx, pad + boxW + gap, heroTop, boxW, heroH, wins, 'VITTORIE', 'gold');

  const cells = [['1° POSTI', wins, '#f5c400'], ['2° POSTI', (p2 || 0), '#cfcfcf'], ['3° POSTI', (p3 || 0), '#cd7f32']];
  const cgap = Math.round(W * 0.03);
  const cw = (W - pad * 2 - cgap * 2) / 3;
  cells.forEach((c, i) => _statCell(ctx, pad + i * (cw + cgap), gridTop, cw, gridH, c[1], c[0], c[2]));
}

// ── Disegna una colonna di classifica (header colonne + accento + righe) ──
// medalCol: oro/argento/bronzo per le posizioni 1-3 (in base a r.pos)
function _drawRankColumn(ctx, x, colW, topY, bottomY, slice, hdFs) {
  const tickX = x + Math.round(colW * 0.012);
  const posX  = x + Math.round(colW * 0.040);
  const nameX = posX + Math.round(colW * 0.150);
  const right = x + colW;
  const posCol = ['#f5c400', '#dadada', '#cd7f32'];
  let y = topY;
  // intestazione colonne
  ctx.font = `600 ${hdFs}px 'Inter Tight',sans-serif`; ctx.fillStyle = 'rgba(255,255,255,0.34)';
  ctx.letterSpacing = '1.5px'; ctx.textAlign = 'left';
  ctx.fillText('POS', posX, y + hdFs);
  ctx.fillText('ATLETA', nameX, y + hdFs);
  ctx.textAlign = 'right'; ctx.fillText('PUNTI', right, y + hdFs);
  ctx.letterSpacing = '0px'; ctx.textAlign = 'left';
  y += hdFs + Math.round(hdFs * 0.35);
  const accW = Math.round(colW * 0.22);
  ctx.fillStyle = 'rgba(232,0,29,0.85)'; ctx.fillRect(x, y, accW, 2);
  ctx.fillStyle = 'rgba(255,255,255,0.06)'; ctx.fillRect(x + accW, y, colW - accW, 1);
  y += 12;
  const rH = Math.round((bottomY - y - 4) / slice.length);
  const ptsResW = Math.round(colW * 0.16); // larghezza riservata ai punti
  const nameMaxW = right - nameX - ptsResW;
  // ── Font con TETTO: indipendenti dall'altezza riga, così i nomi non
  //    diventano enormi/tagliati su formati alti (Story) o larghi (Facebook). ──
  const fsPos = Math.min(Math.round(rH * 0.44), Math.round(colW * 0.052));
  const fsN   = Math.min(Math.round(rH * 0.34), Math.round(colW * 0.038));
  const fsT   = Math.round(fsN * 0.66);
  const fsPts = Math.min(Math.round(rH * 0.40), Math.round(colW * 0.048));
  slice.forEach((r, i) => {
    const ry = y + i * rH, mid = ry + rH / 2;
    const medal = (r.pos >= 1 && r.pos <= 3) ? posCol[r.pos - 1] : null;
    if (i % 2 === 0) { ctx.fillStyle = 'rgba(255,255,255,0.022)'; ctx.fillRect(x, ry, colW, rH); }
    if (medal) { ctx.fillStyle = medal; ctx.fillRect(tickX, mid - Math.round(rH * 0.30), 3, Math.round(rH * 0.60)); }
    // posizione (centrata verticalmente)
    ctx.font = `700 ${fsPos}px 'Inter Tight',sans-serif`; ctx.fillStyle = medal || 'rgba(255,255,255,0.45)';
    ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.fillText(r.pos, posX, mid);
    // nome + team come blocco centrato (clip per larghezza colonna)
    const hasTeam = !!(r.team && String(r.team).trim());
    ctx.textBaseline = 'alphabetic';
    const nameBy = hasTeam ? mid - Math.round(fsT * 0.15) : mid + Math.round(fsN * 0.35);
    ctx.font = `600 ${fsN}px 'Inter Tight',sans-serif`; ctx.fillStyle = '#f0f0f0';
    let nm = (`${r.cognome || ''} ${r.nome || ''}`).toUpperCase().trim();
    while (nm.length > 3 && ctx.measureText(nm).width > nameMaxW) nm = nm.slice(0, -1);
    ctx.fillText(nm, nameX, nameBy);
    if (hasTeam) {
      ctx.font = `400 ${fsT}px 'Inter Tight',sans-serif`; ctx.fillStyle = 'rgba(255,255,255,0.42)';
      let tm = String(r.team);
      while (tm.length > 2 && ctx.measureText(tm).width > nameMaxW) tm = tm.slice(0, -1);
      ctx.fillText(tm, nameX, nameBy + Math.round(fsT * 1.5));
    }
    // punti (centrati verticalmente)
    ctx.font = `700 ${fsPts}px 'Inter Tight',sans-serif`; ctx.fillStyle = '#f5c400';
    ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
    ctx.fillText(r.punti, right, mid);
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  });
}
// ── RIEPILOGO MENSILE CARD ───────────────────────────────────
// Breve testo descrittivo per ogni corridore/team in classifica del mese
// (vittorie/podi), al posto del solo nome squadra — è quello che rende la
// card "raccontata" e non una tabella nuda, pensata per essere salvata e
// condivisa così com'è sui social.
function _recapBlurb(entry) {
  const parts = [];
  if (entry.wins) parts.push(`${entry.wins} vittoria${entry.wins === 1 ? '' : 'e'}`);
  if (entry.podi) parts.push(`${entry.podi} podio${entry.podi === 1 ? '' : 'i'}`);
  return parts.join(' · ');
}
function _drawRecapColumn(ctx, x, colW, topY, bottomY, slice, hdFs, title, isTeam) {
  const posX = x + Math.round(colW * 0.04);
  const nameX = posX + Math.round(colW * 0.13);
  const right = x + colW;
  const posCol = ['#f5c400', '#dadada', '#cd7f32'];
  let y = topY;
  ctx.font = `700 ${Math.round(hdFs * 1.15)}px 'Inter Tight',sans-serif`;
  ctx.fillStyle = '#f4f4f4'; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillText(title, x, y + hdFs);
  y += hdFs + Math.round(hdFs * 0.5);
  const accW = Math.round(colW * 0.22);
  ctx.fillStyle = 'rgba(232,0,29,0.85)'; ctx.fillRect(x, y, accW, 2);
  ctx.fillStyle = 'rgba(255,255,255,0.06)'; ctx.fillRect(x + accW, y, colW - accW, 1);
  y += 12;
  if (!slice.length) {
    ctx.font = `500 ${Math.round(hdFs * 0.9)}px 'Inter Tight',sans-serif`;
    ctx.fillStyle = 'rgba(255,255,255,0.35)';
    ctx.fillText('Nessun dato questo mese', x, y + hdFs);
    return;
  }
  const rH = Math.round((bottomY - y - 4) / slice.length);
  const ptsResW = Math.round(colW * 0.20);
  const nameMaxW = right - nameX - ptsResW;
  const fsPos = Math.min(Math.round(rH * 0.40), Math.round(colW * 0.050));
  const fsN   = Math.min(Math.round(rH * 0.30), Math.round(colW * 0.036));
  const fsB   = Math.round(fsN * 0.62);
  const fsPts = Math.min(Math.round(rH * 0.36), Math.round(colW * 0.044));
  slice.forEach((r, i) => {
    const ry = y + i * rH, mid = ry + rH / 2;
    const medal = i < 3 ? posCol[i] : null;
    if (i % 2 === 0) { ctx.fillStyle = 'rgba(255,255,255,0.022)'; ctx.fillRect(x, ry, colW, rH); }
    if (medal) { ctx.fillStyle = medal; ctx.fillRect(x + Math.round(colW * 0.012), mid - Math.round(rH * 0.30), 3, Math.round(rH * 0.60)); }
    ctx.font = `700 ${fsPos}px 'Inter Tight',sans-serif`; ctx.fillStyle = medal || 'rgba(255,255,255,0.45)';
    ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.fillText(String(i + 1), posX, mid);
    const blurb = _recapBlurb(r);
    ctx.textBaseline = 'alphabetic';
    const nameBy = (blurb || (!isTeam && r.team)) ? mid - Math.round(fsB * 0.15) : mid + Math.round(fsN * 0.35);
    ctx.font = `600 ${fsN}px 'Inter Tight',sans-serif`; ctx.fillStyle = '#f0f0f0';
    let nm = (isTeam ? (r.nome || r.team_id || '') : `${r.cognome || ''} ${r.nome || ''}`).toUpperCase().trim();
    while (nm.length > 3 && ctx.measureText(nm).width > nameMaxW) nm = nm.slice(0, -1);
    ctx.fillText(nm, nameX, nameBy);
    // Sotto il nome: testo descrittivo (vittorie/podi) se presente, altrimenti il team
    if (blurb) {
      ctx.font = `500 ${fsB}px 'Inter Tight',sans-serif`; ctx.fillStyle = 'rgba(245,196,0,0.78)';
      let bl = blurb;
      while (bl.length > 3 && ctx.measureText(bl).width > nameMaxW) bl = bl.slice(0, -1);
      ctx.fillText(bl, nameX, nameBy + Math.round(fsB * 1.5));
    } else if (!isTeam && r.team) {
      ctx.font = `400 ${fsB}px 'Inter Tight',sans-serif`; ctx.fillStyle = 'rgba(255,255,255,0.38)';
      let tm = String(r.team);
      while (tm.length > 2 && ctx.measureText(tm).width > nameMaxW) tm = tm.slice(0, -1);
      ctx.fillText(tm, nameX, nameBy + Math.round(fsB * 1.5));
    }
    ctx.font = `700 ${fsPts}px 'Inter Tight',sans-serif`; ctx.fillStyle = '#f5c400';
    ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
    ctx.fillText(`${r.punti}pt`, right, mid);
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  });
}
function _drawRecap(ctx, W, H, d) {
  const { totalGare, topAthletes = [], topTeams = [] } = d;
  const hB = Math.round(H * 0.092), fB = Math.round(H * 0.06), pad = Math.round(W * 0.048);
  let y = hB + Math.round(H * 0.03);
  const fsSub = Math.round(H * 0.026);
  ctx.font = `600 ${fsSub}px 'Inter Tight',sans-serif`;
  ctx.fillStyle = 'rgba(255,255,255,0.55)'; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillText(`${totalGare} gar${totalGare === 1 ? 'a' : 'e'} disputat${totalGare === 1 ? 'a' : 'e'} questo mese`, pad, y + fsSub);
  y += fsSub + Math.round(H * 0.022);
  const bottomY = H - fB - 4;
  const landscape = W > H * 1.15;
  const hdFs = Math.round(H * 0.024);
  const athletes = topAthletes.slice(0, 5), teams = topTeams.slice(0, 5);
  if (landscape) {
    const gap = Math.round(W * 0.045);
    const colW = Math.round((W - pad * 2 - gap) / 2);
    _drawRecapColumn(ctx, pad, colW, y, bottomY, athletes, hdFs, 'TOP ATLETI', false);
    _drawRecapColumn(ctx, pad + colW + gap, colW, y, bottomY, teams, hdFs, 'TOP TEAM', true);
  } else {
    const totalH = bottomY - y;
    const athH = Math.round(totalH * 0.56);
    const gapV = Math.round(totalH * 0.045);
    const teamTop = y + athH + gapV;
    _drawRecapColumn(ctx, pad, W - pad * 2, y, y + athH, athletes, hdFs, '🏆 TOP ATLETI', false);
    _drawRecapColumn(ctx, pad, W - pad * 2, teamTop, bottomY, teams, hdFs, '🚴 TOP TEAM', true);
  }
}

// ── CLASSIFICA CARD ────────────────────────────────────────
function _drawClass(ctx, W, H, d) {
  const {rows} = d;
  const hB=Math.round(H*0.092),fB=Math.round(H*0.06),pad=Math.round(W*0.048);
  // Titolo "CLASSIFICA <categoria>" + eventuale mese sono nell'header.
  const topY=hB+Math.round(H*0.022);
  const bottomY=H-fB-4;
  const maxR=Math.min(rows.length,10);
  const landscape = W > H*1.25; // Facebook (1.91:1), Twitter (16:9)
  if(landscape && maxR>5){
    // ── Due colonne: 1-5 a sinistra, 6-10 a destra ──
    const gap=Math.round(W*0.045);
    const colW=Math.round((W-pad*2-gap)/2);
    const half=Math.ceil(maxR/2);
    const hdFs=Math.round(H*0.030);
    _drawRankColumn(ctx, pad, colW, topY, bottomY, rows.slice(0,half), hdFs);
    _drawRankColumn(ctx, pad+colW+gap, colW, topY, bottomY, rows.slice(half,maxR), hdFs);
  } else {
    // ── Colonna singola (verticale / quadrato) ──
    _drawRankColumn(ctx, pad, W-pad*2, topY, bottomY, rows.slice(0,maxR), Math.round(H*0.020));
  }
}

// Foto profilo dei corridori in classifica (fino a 10), per la card gara:
// mostra il volto SOLO a chi ce l'ha, nessun segnaposto per gli altri —
// un'unica chiamata batch invece di una per atleta. Stesso pattern
// fetch+blob usato sotto per l'avatar della card atleta (evita problemi
// CORS da cache del browser sull'immagine remota).
// fetch con timeout: senza, una singola foto lenta/irraggiungibile blocca
// per sempre la generazione dell'intera card (Promise.all non si sblocca mai
// se anche una sola promise al suo interno non si risolve né rigetta) —
// bug reale osservato: modale di condivisione bloccata su "Generazione..."
function _fetchTimeout(url, opts = {}, ms = 6000) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), ms);
  return fetch(url, { ...opts, signal: ctrl.signal }).finally(() => clearTimeout(t));
}
async function _fetchGaraAvatars(results) {
  const map = new Map();
  const ids = [...new Set((results || []).map(r => r.atleta_id).filter(Boolean))].slice(0, 10);
  if (!ids.length) return map;
  try {
    const resp = await _fetchTimeout(`${API_BASE}/athlete-photos?ids=${encodeURIComponent(ids.join(','))}`);
    if (!resp.ok) return map;
    const urls = await resp.json();
    await Promise.all(Object.entries(urls).map(([id, url]) => new Promise(resolve => {
      _fetchTimeout(url, { mode: 'cors', cache: 'no-store' }).then(r => {
        if (!r.ok) return resolve();
        return r.blob().then(blob => {
          const blobUrl = URL.createObjectURL(blob);
          const img = new Image();
          img.onload = () => { map.set(id, img); URL.revokeObjectURL(blobUrl); resolve(); };
          img.onerror = () => { URL.revokeObjectURL(blobUrl); resolve(); };
          img.src = blobUrl;
        });
      }).catch(() => resolve());
    })));
  } catch {}
  return map;
}

// Fetch+blob di un'immagine remota per disegnarla su canvas evitando
// problemi CORS da cache del browser (stesso pattern usato per l'avatar
// atleta e per le foto profilo in classifica gara).
// Timeout più largo (15s, non 6s) + un ritentativo: su rete mobile lenta
// (spesso il caso — foto condivise da bordo strada durante/dopo una gara) il
// download della foto poteva scadere prima di completare, e senza retry si
// ricadeva silenziosamente su uno sfondo generico senza foto, senza nessun
// errore visibile — sembrava che "le immagini non si vedessero".
async function _fetchImgBlob(url, retries = 1) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const resp = await _fetchTimeout(url, { mode: 'cors', cache: 'no-store' }, 15000);
      if (!resp.ok) continue;
      const blob = await resp.blob();
      const blobUrl = URL.createObjectURL(blob);
      const img = await new Promise(resolve => {
        const i = new Image();
        i.onload = () => { URL.revokeObjectURL(blobUrl); resolve(i); };
        i.onerror = () => { URL.revokeObjectURL(blobUrl); resolve(null); };
        i.src = blobUrl;
      });
      if (img) return img;
    } catch { /* prova ancora se resta un tentativo */ }
  }
  return null;
}

// ── Generatore canvas ──────────────────────────────────────
async function generateShareCanvas(type, payload, platKey) {
  const p=SHARE_PLATFORMS[platKey]||SHARE_PLATFORMS.instagram;
  const canvas=document.createElement('canvas'); canvas.width=p.w; canvas.height=p.h;
  const ctx=canvas.getContext('2d');
  const logo=await _getLogo();
  // Assicura che i webfont (Inter Tight) siano pronti prima di disegnare sul canvas
  try { if (document.fonts && document.fonts.ready) await document.fonts.ready; } catch(e){}
  if(type==='gara') {
    // Stessa grafica "foto intera + risultati in overlay" usata per la
    // condivisione Facebook (server, buildGaraResultOverlaySvg), non solo
    // lì: quando la gara ha una foto, la usiamo come sfondo per TUTTI i
    // formati (Post Quadrato, Instagram, Story, ecc.), non solo per FB.
    // _shareGaraStyle sceglie tra "risultati" (podio+classifica) e
    // "vincitore" (solo il primo, stile annuncio) — libero per ogni formato.
    const isWinner = _shareGaraStyle === 'winner';
    const [avatarMap, photoImg, xpixLogo] = await Promise.all([
      isWinner ? Promise.resolve(new Map()) : _fetchGaraAvatars(payload.results),
      payload.photo_url ? _fetchImgBlob(payload.photo_url) : Promise.resolve(null),
      _isXpixCredit(payload) ? _getXpixLogo() : Promise.resolve(null),
    ]);
    window._shareHasPhoto = !!photoImg;
    // Foto attesa ma non caricata (rete lenta/assente, tipico da mobile) —
    // avviso visibile invece di ricadere silenziosamente su uno sfondo
    // generico senza che sembri un errore del sito.
    window._sharePhotoLoadFailed = !!(payload.photo_url && !photoImg);
    if (photoImg) {
      (isWinner ? _bgPhotoBottom : _bgPhoto)(ctx,p.w,p.h,photoImg,_shareImgAdjust);
    } else _bg(ctx,p.w,p.h);
    if (isWinner) _drawGaraWinner(ctx,p.w,p.h,payload,logo,xpixLogo);
    else _drawGara(ctx,p.w,p.h,payload,logo,avatarMap,xpixLogo);
  } else {
    _bg(ctx,p.w,p.h);
    const _headerClassData = type==='class' ? payload
      : type==='recap' ? { catLabel:'RIEPILOGO MENSILE', month:(payload.monthLabel||'').toUpperCase() }
      : (type==='atleta-mese'||type==='team-mese') ? { catLabel:(type==='atleta-mese'?'ATLETA DEL MESE':'TEAM DEL MESE'), month:(payload.monthLabel||'').toUpperCase() }
      : null;
    _header(ctx,logo,p.w,p.h, _headerClassData, (type==='atleta'||type==='team')?payload.cat:null); _footer(ctx,p.w,p.h);
    if(type==='atleta') {
      const athImg = payload.photo_url ? await _fetchImgBlob(payload.photo_url) : null;
      _drawAtleta(ctx,p.w,p.h,payload,athImg);
    }
    else if(type==='atleta-mese') {
      const athImg = payload.photo_url ? await _fetchImgBlob(payload.photo_url) : null;
      _drawAtletaMese(ctx,p.w,p.h,payload,athImg);
    }
    else if(type==='team')  _drawTeam(ctx,p.w,p.h,payload);
    else if(type==='team-mese') _drawTeamMese(ctx,p.w,p.h,payload);
    else if(type==='class') _drawClass(ctx,p.w,p.h,payload);
    else if(type==='recap') _drawRecap(ctx,p.w,p.h,payload);
  }
  return canvas;
}

// ── SVG loghi social ────────────────────────────────────────
