// ── Modale principale ──────────────────────────────────────
window.showShareModal = async function(type, payload) {
  _shareType=type; _sharePayload=payload; _sharePlatKey='instagram';
  _shareGaraStyle='winner'; _shareImgAdjust={scale:1,offsetX:0,offsetY:0};
  // "Riscalda" subito la generazione della grafica OG lato server (appena si
  // apre la modale, prima ancora che l'utente scelga Facebook): la prima
  // generazione può richiedere alcuni secondi (foto + composizione avatar),
  // e se Facebook la richiede lui stesso a freddo durante "Pubblicazione in
  // corso" il popup resta bloccato in attesa. Fire-and-forget, nessun await:
  // basta che la richiesta parta ora, il risultato resta in cache 30 min.
  if (payload?._id && ['gara','atleta','team','class'].includes(type)) {
    fetch(`${API_BASE}/og-image/${type}/${encodeURIComponent(payload._id)}`).catch(()=>{});
  }
  const titles={gara:'Risultati Gara',atleta:'Profilo Atleta',team:'Profilo Team',class:'Classifica',recap:'Riepilogo Mensile','atleta-mese':'Atleta del Mese','team-mese':'Team del Mese'};
  // Riepilogo mensile e atleta/team-del-mese non hanno una pagina/URL
  // persistente da far leggere al Facebook Sharer (niente route /og/:id
  // dedicata) — per questi tipi il bottone "Facebook" si comporta come gli
  // altri (genera+scarica l'immagine 1200×630) invece di aprire il popup
  // "condividi link" di Facebook.
  const _noFbSharerTypes = ['recap','atleta-mese','team-mese'];
  const platBtns = [
    {k:'instagram', label:'Instagram\nFeed',sz:'1080×1350',  fb:false},
    {k:'story',     label:'Story /\nReels', sz:'1080×1920',  fb:false},
    {k:'facebook',  label:'Facebook',       sz:'Link + foto', fb: !_noFbSharerTypes.includes(type)},
    {k:'twitter',   label:'Twitter/X',      sz:'1200×675',   fb:false},
    {k:'whatsapp',  label:'WhatsApp',       sz:'1080×1080',  fb:false},
  ].map(({k,label,sz,fb})=>{
    const p=SHARE_PLATFORMS[k];
    const onclick = fb
      ? `window.shareOnFacebook()`
      : `window.setSharePlat('${k}')`;
    return `<button class="share-plat-btn ${p.cls} ${k==='instagram'?'active':''}" id="sp-${k}" onclick="${onclick}" title="${sz}">
      <div class="share-plat-icon">${_SVGS[k]||''}</div>
      <span class="share-plat-label">${label.replace('\n','\n')}</span>
    </button>`;
  }).join('');

  document.body.insertAdjacentHTML('beforeend',`
  <div class="share-modal-overlay" id="share-overlay" onclick="if(event.target===this)window.closeShareModal()">
    <div class="share-modal" role="dialog">
      <div class="share-modal-header">
        <span class="share-modal-title">📤 ${titles[type]||'Condividi'}</span>
        <button class="share-modal-close" onclick="window.closeShareModal()">✕</button>
      </div>
      <div class="share-platforms">${platBtns}</div>
      ${type==='gara' ? `
      <div class="share-style-toggle" style="display:flex;gap:8px;margin-bottom:10px">
        <button class="share-plat-btn active" id="sgs-winner" onclick="window.setGaraStyle('winner')" style="flex:1;padding:8px 6px">🏆 Vincitore</button>
        <button class="share-plat-btn" id="sgs-results" onclick="window.setGaraStyle('results')" style="flex:1;padding:8px 6px">🏁 Risultati</button>
      </div>
      <div id="share-photo-adjust" style="display:none;margin-bottom:10px">
        <div style="font-size:.72rem;color:var(--text-muted);margin-bottom:4px">🖼 Trascina l'anteprima per spostare la foto · usa lo zoom per ingrandirla</div>
        <div style="display:flex;align-items:center;gap:8px">
          <span style="font-size:.72rem;color:var(--text-muted)">Zoom</span>
          <input type="range" id="share-zoom-slider" min="100" max="250" value="100" style="flex:1" oninput="window._onShareZoom(this.value)"/>
          <button class="share-action-btn" style="padding:4px 10px;font-size:.72rem" onclick="window.resetShareImgAdjust()">↺ Reimposta</button>
        </div>
      </div>` : ''}
      <div id="share-fb-text-box" style="display:none;margin-bottom:12px">
        <div style="font-size:.72rem;color:var(--text-muted);margin-bottom:4px">Testo per il post — copialo e incollalo su Facebook insieme alla grafica</div>
        <textarea id="share-fb-text" readonly rows="6" style="width:100%;resize:vertical;font:inherit;font-size:.85rem;padding:8px;border-radius:8px;border:1px solid var(--border-subtle);background:var(--bg-elevated,rgba(255,255,255,0.04));color:var(--text-primary)"></textarea>
        <div style="display:flex;gap:6px;margin-top:6px">
          <button class="share-action-btn" onclick="window.copyFbShareText()" id="share-fb-copy-btn">📋 Copia testo</button>
          <button class="share-action-btn" onclick="window._showFbShareText(true)" id="share-fb-regen-btn">🔄 Rigenera</button>
        </div>
      </div>
      <div class="share-size-label" id="share-size-lbl">Instagram Feed · 1080×1350 (4:5)</div>
      <div class="share-preview-wrap">
        <div class="share-generating" id="share-loading"><div class="share-spinner"></div> Generazione...</div>
        <img id="share-canvas-preview" draggable="false" style="display:none;${type==='gara'?'cursor:grab;touch-action:none;-webkit-user-drag:none;user-select:none':''}" alt="Anteprima"/>
      </div>
      <div class="share-actions" id="share-actions-default">
        <button class="share-action-btn share-action-download" id="share-dl-btn" onclick="window.downloadShareCard()">⬇ Scarica</button>
        <button class="share-action-btn share-action-native" id="share-native-btn" onclick="window.nativeShare()">↗ Condividi</button>
      </div>
      <div class="share-actions" id="share-actions-whatsapp" style="display:none">
        <button class="share-action-btn" onclick="window.shareWhatsappLink()">🔗 Condividi il link</button>
        <button class="share-action-btn share-action-native" id="share-native-btn-wa" onclick="window.nativeShare()">🖼 Condividi la foto</button>
      </div>
    </div>
  </div>`);
  // Il testo pronto (narrazione podio) va mostrato subito all'apertura,
  // qualunque piattaforma l'admin scelga dopo — prima compariva solo dopo
  // aver cliccato "Facebook", quindi restava nascosto per chi condivideva
  // altrove (WhatsApp, Instagram, Twitter, Post) pur essendo lo stesso
  // identico testo utile per qualsiasi condivisione manuale.
  _showFbShareText();
  await _refreshPreview();
};

window.closeShareModal=function(){const e=document.getElementById('share-overlay');if(e)e.remove();};

window.setSharePlat=async function(k){
  _sharePlatKey=k;
  document.querySelectorAll('.share-platforms .share-plat-btn').forEach(b=>b.classList.remove('active'));
  const btn=document.getElementById('sp-'+k); if(btn)btn.classList.add('active');
  const p=SHARE_PLATFORMS[k];
  const sizes={instagram:'1080×1350 (4:5)',story:'1080×1920 (9:16)',facebook:'1200×630 (1.91:1)',twitter:'1200×675 (16:9)',whatsapp:'1080×1080 (1:1)'};
  const names={instagram:'Instagram Feed',story:'Story / Reels',facebook:'Facebook',twitter:'Twitter/X',whatsapp:'WhatsApp'};
  const lbl=document.getElementById('share-size-lbl');
  if(lbl) lbl.textContent=`${names[k]} · ${sizes[k]}`;
  // Per WhatsApp: niente "Scarica"/"Condividi" generico, ma link (apre l'app,
  // si sceglie la chat) o foto (share sheet nativo, stesso risultato per
  // l'immagine). Per tutte le altre piattaforme resta invariato.
  const defRow=document.getElementById('share-actions-default');
  const waRow=document.getElementById('share-actions-whatsapp');
  if(defRow) defRow.style.display = k==='whatsapp' ? 'none' : '';
  if(waRow) waRow.style.display = k==='whatsapp' ? '' : 'none';
  await _refreshPreview();
};

// Stile grafica gara: "risultati" (podio+classifica) o "vincitore" (solo il
// primo, stile annuncio) — libero per ogni formato (Post/Instagram/Story/…).
window.setGaraStyle=async function(style){
  _shareGaraStyle=style;
  document.querySelectorAll('.share-style-toggle .share-plat-btn').forEach(b=>b.classList.remove('active'));
  const btn=document.getElementById(style==='winner'?'sgs-winner':'sgs-results'); if(btn)btn.classList.add('active');
  await _refreshPreview();
};

// ── Regolazione manuale foto (zoom + trascinamento) ────────────────────────
let _shareZoomTimer=null;
window._onShareZoom=function(pct){
  _shareImgAdjust.scale = Math.max(1, parseFloat(pct)/100);
  clearTimeout(_shareZoomTimer);
  _shareZoomTimer=setTimeout(()=>{ _refreshPreview(); }, 180);
};
window.resetShareImgAdjust=async function(){
  _shareImgAdjust={scale:1,offsetX:0,offsetY:0};
  const s=document.getElementById('share-zoom-slider'); if(s)s.value=100;
  await _refreshPreview();
};
// Trascinamento sull'anteprima: sposta il ritaglio della foto (drag = pan).
// I delta sono in pixel-schermo dell'<img> visualizzata, convertiti in
// pixel-canvas (risoluzione reale della grafica, quasi sempre più grande)
// nel rapporto tra le due — altrimenti un trascinamento di 50px sull'anteprima
// (magari mostrata a metà della risoluzione reale) sposterebbe la foto la
// metà di quanto ci si aspetta.
let _shareDrag=null;
function _initShareDragHandlers(){
  const img=document.getElementById('share-canvas-preview');
  if(!img || img._dragBound) return;
  img._dragBound=true;
  const start=(x,y)=>{
    if(_shareType!=='gara') return;
    _shareDrag={x,y,ox:_shareImgAdjust.offsetX,oy:_shareImgAdjust.offsetY};
    img.style.cursor='grabbing';
  };
  const move=(x,y)=>{
    if(!_shareDrag) return;
    const p=SHARE_PLATFORMS[_sharePlatKey];
    const rect=img.getBoundingClientRect();
    const scaleRatio = rect.width ? (p.w/rect.width) : 1;
    const dx=(x-_shareDrag.x)*scaleRatio, dy=(y-_shareDrag.y)*scaleRatio;
    _shareImgAdjust.offsetX=_shareDrag.ox+dx;
    _shareImgAdjust.offsetY=_shareDrag.oy+dy;
    clearTimeout(_shareZoomTimer);
    _shareZoomTimer=setTimeout(()=>{ _refreshPreview(); }, 60);
  };
  const end=()=>{ if(_shareDrag){ _shareDrag=null; img.style.cursor='grab'; } };
  // preventDefault ovunque: un <img> è trascinabile dal browser di default
  // (drag-out nativo, "fantasma" dell'immagine) — senza bloccarlo, il primo
  // movimento del mouse avviava quel drag nativo invece di alimentare
  // pointermove, e il trascinamento personalizzato non spostava mai nulla.
  img.addEventListener('dragstart', e=>e.preventDefault());
  img.addEventListener('pointerdown', e=>{ e.preventDefault(); start(e.clientX,e.clientY); img.setPointerCapture(e.pointerId); });
  img.addEventListener('pointermove', e=>{ if(_shareDrag){ e.preventDefault(); move(e.clientX,e.clientY); } });
  img.addEventListener('pointerup', end);
  img.addEventListener('pointercancel', end);
}

async function _refreshPreview(){
  const loading=document.getElementById('share-loading');
  const preview=document.getElementById('share-canvas-preview');
  if(!loading||!preview) return;
  loading.style.display='flex'; preview.style.display='none';
  try{
    const canvas=await generateShareCanvas(_shareType,_sharePayload,_sharePlatKey);
    preview.src=canvas.toDataURL('image/png');
    loading.style.display='none'; preview.style.display='block';
    if (window._sharePhotoLoadFailed) showToast('⚠️ Foto non caricata (connessione lenta) — la grafica è senza foto, riprova', 'error');
    _initShareDragHandlers();
    const adjustBox=document.getElementById('share-photo-adjust');
    if(adjustBox) adjustBox.style.display = window._shareHasPhoto ? 'block' : 'none';
  }catch(e){loading.innerHTML='❌ Errore: '+e.message; console.error(e);}
}

function _downloadCanvas(canvas, suffix){
  const a=document.createElement('a');
  const p=SHARE_PLATFORMS[_sharePlatKey];
  a.download=`italiacrit-${_shareType}-${suffix}-${p.w}x${p.h}.png`;
  a.href=canvas.toDataURL('image/png'); a.click();
}

// Scaricando dalla vista "Vincitore" (quella principale) escono ENTRAMBE le
// grafiche in un colpo solo — quella del vincitore e quella dei risultati —
// invece di dover cambiare vista e riscaricare a mano. Scaricando invece
// dalla vista "Risultati" esce solo quella (nessun cambio di comportamento lì).
window.downloadShareCard=async function(){
  if(_shareType==='gara' && _shareGaraStyle==='winner'){
    const winnerCanvas=await generateShareCanvas(_shareType,_sharePayload,_sharePlatKey);
    _downloadCanvas(winnerCanvas,'winner');
    _shareGaraStyle='results';
    try{
      const resultsCanvas=await generateShareCanvas(_shareType,_sharePayload,_sharePlatKey);
      await new Promise(r=>setTimeout(r,300)); // due download troppo ravvicinati, alcuni browser ne bloccano uno
      _downloadCanvas(resultsCanvas,'risultati');
    } finally { _shareGaraStyle='winner'; } // ripristina lo stile visibile in anteprima
    return;
  }
  const canvas=await generateShareCanvas(_shareType,_sharePayload,_sharePlatKey);
  _downloadCanvas(canvas,_sharePlatKey);
};

window.nativeShare=async function(){
  // Due bottoni "Condividi" possono esistere nel DOM (riga azioni normale +
  // riga dedicata WhatsApp), ma solo uno è visibile alla volta: prendiamo
  // quello effettivamente mostrato per aggiornarne testo/stato di caricamento.
  const btn=[...document.querySelectorAll('.share-action-native')].find(b=>b.offsetParent!==null);
  const label = btn===document.getElementById('share-native-btn-wa') ? '🖼 Condividi la foto' : '↗ Condividi';
  if(btn){btn.disabled=true;btn.textContent='⏳…';}
  try{
    const canvas=await generateShareCanvas(_shareType,_sharePayload,_sharePlatKey);
    const filename=`italiacrit-${_shareType}-${_sharePlatKey}.png`;
    // Prova share con file (mobile)
    if(navigator.share&&navigator.canShare){
      const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));
      const f=new File([blob],filename,{type:'image/png'});
      if(navigator.canShare({files:[f]})){
        await navigator.share({title:'Italia Cycling Stats',files:[f]});
        if(btn){btn.disabled=false;btn.textContent=label;}
        return;
      }
    }
    // Fallback: copia immagine negli appunti
    const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));
    await navigator.clipboard.write([new ClipboardItem({'image/png':blob})]);
    if(btn){btn.disabled=false;btn.textContent='✓ Copiata!';}
    setTimeout(()=>{if(btn)btn.textContent=label;},2500);
  }catch(e){
    // Ultimo fallback: download diretto
    window.downloadShareCard();
    if(btn){btn.disabled=false;btn.textContent=label;}
  }
};

// Condivisione via link (non foto): apre WhatsApp con testo pronto
// (narrazione + link alla pagina) e lascia scegliere la chat dentro l'app,
// invece del solito download/condividi immagine.
window.shareWhatsappLink=function(){
  const id = _sharePayload?._id;
  const url = id ? `https://italiacyclingstats.com/${_shareType}/${encodeURIComponent(id)}` : 'https://italiacyclingstats.com';
  const ta = document.getElementById('share-fb-text');
  const text = (ta && ta.value && !ta.value.includes('Generazione') && !ta.value.includes('Rigenerazione')) ? ta.value : '';
  const full = text ? `${text}\n\n${url}` : url;
  window.open(`https://wa.me/?text=${encodeURIComponent(full)}`, '_blank');
};

// ── Open Graph URL per Facebook ────────────────────────────
const OG_BASE = 'https://italiacyclingstats.com/og';
function _ogUrl(type, payload) {
  const id = payload?._id;
  if (!id) return null;
  return `${OG_BASE}/${type}/${encodeURIComponent(id)}`;
}
window.shareOnFacebook = function() {
  let url = _ogUrl(_shareType, _sharePayload);
  if (!url) { showToast('Dati non disponibili per la condivisione Facebook'); return; }
  // Inoltra la stessa regolazione zoom/posizione usata per l'anteprima
  // Post/Instagram/Story (_shareImgAdjust): senza, la card Facebook usava
  // sempre il ritaglio automatico del server, ignorando quanto centrato a
  // mano nella modale — unico formato dove non si poteva correggere.
  if (_shareType === 'gara' && (_shareImgAdjust.scale > 1.001 || Math.abs(_shareImgAdjust.offsetX) > 0.5 || Math.abs(_shareImgAdjust.offsetY) > 0.5)) {
    const qs = `s=${_shareImgAdjust.scale.toFixed(3)}&ox=${Math.round(_shareImgAdjust.offsetX)}&oy=${Math.round(_shareImgAdjust.offsetY)}`;
    url += (url.includes('?') ? '&' : '?') + qs;
  }
  window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`, '_blank', 'width=600,height=400');
  _showFbShareText();
};

// Testo pronto da incollare nel post Facebook — Facebook non permette di
// precompilare il corpo del post via URL (solo il link, l'anteprima la
// genera lui), quindi qui mostriamo lo stesso tipo di narrazione dinamica
// usata per i meta tag e l'admin la copia a mano sopra alla grafica.
// Solo per l'admin e solo per le gare (unico tipo con questa narrazione).
async function _showFbShareText(regen) {
  const box = document.getElementById('share-fb-text-box');
  if (!box) return;
  if (authUser()?.role !== 'admin' || _shareType !== 'gara' || !_sharePayload?._id) { box.style.display = 'none'; return; }
  box.style.display = 'block';
  const ta = document.getElementById('share-fb-text');
  const regenBtn = document.getElementById('share-fb-regen-btn');
  ta.value = regen ? 'Rigenerazione testo…' : 'Generazione testo…';
  if (regenBtn) regenBtn.disabled = true;
  try {
    const qs = regen ? '?regen=1' : '';
    const { text } = await apiCall(`/admin/gara-share-text/${encodeURIComponent(_sharePayload._id)}${qs}`);
    ta.value = text || '';
  } catch (e) { ta.value = ''; }
  finally { if (regenBtn) regenBtn.disabled = false; }
}
window.copyFbShareText = async function() {
  const ta = document.getElementById('share-fb-text');
  const btn = document.getElementById('share-fb-copy-btn');
  if (!ta?.value) return;
  try {
    await navigator.clipboard.writeText(ta.value);
    if (btn) { btn.textContent = '✓ Copiato!'; setTimeout(() => { btn.textContent = '📋 Copia testo'; }, 2000); }
  } catch {
    ta.select();
    document.execCommand('copy');
  }
};

