window._mvcSetMode = function(mode) {
  window._mvcMode = mode;
  document.getElementById('mvc-link-wrap').style.display   = mode === 'link'   ? '' : 'none';
  document.getElementById('mvc-upload-wrap').style.display = mode === 'upload' ? '' : 'none';
  document.getElementById('mvc-tab-link').className   = `dash-btn dash-btn--sm ${mode==='link'   ? 'dash-btn--accent' : 'dash-btn--outline'}`;
  document.getElementById('mvc-tab-upload').className = `dash-btn dash-btn--sm ${mode==='upload' ? 'dash-btn--accent' : 'dash-btn--outline'}`;
};

window._submitMediaVideoCreate = async function(profileId) {
  const title = document.getElementById('mvc-title')?.value.trim();
  const palinsesto = document.getElementById('mvc-pal')?.value;
  const gara  = document.getElementById('mvc-gara')?.value.trim() || null;
  const desc  = document.getElementById('mvc-desc')?.value.trim() || '';
  const errEl = document.getElementById('mvc-err');
  const btn   = document.getElementById('mvc-submit');
  const showErr = (msg) => { errEl.textContent = msg; errEl.style.display = 'block'; };
  if (!title) return showErr('Il titolo è obbligatorio');

  if (window._mvcMode === 'link') {
    const url = document.getElementById('mvc-url')?.value.trim();
    if (!url) return showErr('Inserisci il link del video');
    btn.disabled = true; btn.textContent = 'Pubblicazione…';
    try {
      await apiCall('/media/video', { method: 'POST', body: { title, palinsesto, url, gara_id: gara, description: desc } });
      document.getElementById('modal-overlay')?.remove();
      showToast('✓ Video pubblicato!');
      renderMyProfile();
    } catch(err) {
      showErr(err.message);
      btn.disabled = false; btn.textContent = 'Pubblica video';
    }
  } else {
    const file = document.getElementById('mvc-file')?.files?.[0];
    if (!file) return showErr('Seleziona un file video');
    btn.disabled = true; btn.textContent = 'Caricamento…';
    document.getElementById('mvc-progress').style.display = 'block';
    const fd = new FormData();
    fd.append('video', file);
    fd.append('title', title);
    fd.append('palinsesto', palinsesto);
    if (gara) fd.append('gara_id', gara);
    fd.append('description', desc);
    try {
      const xhr = new XMLHttpRequest();
      xhr.upload.onprogress = ev => {
        if (ev.lengthComputable) {
          const pct = Math.round(ev.loaded / ev.total * 100);
          document.getElementById('mvc-bar').style.width = pct + '%';
          document.getElementById('mvc-status').textContent = `${pct}% caricato…`;
        }
      };
      await new Promise((resolve, reject) => {
        xhr.onload = () => {
          const d = JSON.parse(xhr.responseText);
          if (xhr.status >= 400) reject(new Error(d.error || `HTTP ${xhr.status}`));
          else resolve(d);
        };
        xhr.onerror = () => reject(new Error('Errore di rete'));
        xhr.open('POST', `${API_BASE}/media/video/upload`);
        xhr.setRequestHeader('Authorization', `Bearer ${authToken()}`);
        xhr.send(fd);
      });
      document.getElementById('modal-overlay')?.remove();
      showToast('✓ Video caricato!');
      renderMyProfile();
    } catch(err) {
      showErr(err.message);
      btn.disabled = false; btn.textContent = 'Pubblica video';
    }
  }
};

window.deleteMediaVideo = async function(videoId) {
  if (!confirm('Eliminare questo video?')) return;
  try {
    await apiCall(`/media/video/${videoId}`, { method: 'DELETE' });
    showToast('Video eliminato');
    renderMyProfile();
  } catch(err) { showToast('Errore: ' + err.message, 'error'); }
};

window.searchAtletaForLink = function(q) {
  const container = document.getElementById('link-results');
  if (!container) return;
  if (!q || q.length < 2) { container.innerHTML = ''; return; }
  const { athletes } = globalData;
  const matches = Object.entries(athletes)
    .filter(([id, a]) => {
      const name = ((a.cognome || '') + ' ' + (a.nome || '')).toLowerCase();
      return name.includes(q.toLowerCase());
    })
    .slice(0, 8);
  container.innerHTML = matches.length
    ? matches.map(([id, a]) => `
        <div class="link-result-row" onclick="selectAtletaLink('${esc(id)}','${esc(a.cognome)} ${esc(a.nome)}')">
          <strong>${esc(a.cognome)} ${esc(a.nome)}</strong>
          <span style="color:var(--text-muted);font-size:0.8rem">${esc(a.team || '')}</span>
        </div>`).join('')
    : `<div style="padding:8px;color:var(--text-muted);font-size:0.85rem">Nessun risultato</div>`;
};

window.selectAtletaLink = function(id, label) {
  const inp = document.getElementById('link-search');
  const hid = document.getElementById('link-atleta-id');
  const res = document.getElementById('link-results');
  if (inp) inp.value = label;
  if (hid) hid.value = id;
  if (res) res.innerHTML = '';
};

window.submitLinkAthlete = async function(e) {
  e.preventDefault();
  const atleta_id = document.getElementById('link-atleta-id')?.value || null;
  const fci_code  = document.getElementById('link-fci')?.value.trim() || null;
  const first_name = document.getElementById('link-fname')?.value.trim() || null;
  const last_name  = document.getElementById('link-lname')?.value.trim() || null;
  try {
    const r = await apiCall('/profile/link-athlete', { method: 'POST', body: { atleta_id, fci_code, first_name, last_name } });
    alert(r.generated
      ? `Profilo creato e attivo subito! Il tuo atleta_id è ${r.atleta_id} — non avendo ancora risultati FCI, il profilo parte da 0 punti.`
      : 'Profilo collegato! Attivo immediatamente.');
    renderMyProfile();
  } catch (err) { alert('Errore: ' + err.message); }
};

window.submitLinkTeam = async function(e) {
  e.preventDefault();
  const team_name = document.getElementById('link-team-name')?.value.trim();
  const { teams } = globalData;
  const match = Object.entries(teams).find(([id, t]) =>
    (t.nome || '').toLowerCase() === team_name.toLowerCase()
  );
  try {
    await apiCall('/profile/link-team', { method: 'POST', body: { team_id: match ? match[0] : null, team_name } });
    alert('Team collegato! ' + (match ? 'Attivo immediatamente.' : 'In attesa di verifica admin.'));
    renderMyProfile();
  } catch (err) { alert('Errore: ' + err.message); }
};

window.submitLinkFamily = async function(e) {
  e.preventDefault();
  const linked_atleta_id = document.getElementById('link-atleta-id')?.value;
  if (!linked_atleta_id) { alert('Seleziona prima un atleta dalla lista.'); return; }
  try {
    await apiCall('/profile/link-family', { method: 'POST', body: { linked_atleta_id } });
    alert('Atleta collegato! Attivo immediatamente.');
    renderMyProfile();
  } catch (err) { alert('Errore: ' + err.message); }
};

window.submitTeamAddAthlete = async function() {
  const cognome = document.getElementById('team-add-cognome')?.value.trim();
  const nome = document.getElementById('team-add-nome')?.value.trim();
  const genere = document.getElementById('team-add-genere')?.value;
  const categoria = document.getElementById('team-add-categoria')?.value.trim();
  if (!cognome || !nome) { alert('Nome e cognome obbligatori.'); return; }
  try {
    const r = await apiCall('/team/add-athlete', { method: 'POST', body: { cognome, nome, genere, categoria } });
    showToast(`✓ ${cognome} ${nome} aggiunto al roster`);
    document.getElementById('team-add-cognome').value = '';
    document.getElementById('team-add-nome').value = '';
    document.getElementById('team-add-categoria').value = '';
    // Ricarica i dati (nuovo atleta manuale incluso) e ridisegna la dashboard.
    globalData = await loadAll();
    renderMyProfile();
  } catch (err) { showToast('Errore: ' + err.message, 'error'); }
};

